INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20158204895', 'Wella Professionals Oil Reflections Condicionador 200ml', '* DESCRIÇÃO TÉCNICA: A PRIMEIRA COLEÇÃO DA WELLA À BASE DE ÓLEOS PRECIOSOS PARA CABELOS MAIS MACIOS, COM LUMINOSIDADE INSTANTÂNEA: Wella Professionals Condicionador Oil Reflections é um condicionador suavizante que age em 30 segundos. Mantém a água dentro dos fios, deixando os cabelos macios e luminosos instantaneamente. Contém óleo da semente de camélia, que promove a cicatrização e a selagem dos fios, e extrato de chá branco, um antioxidante natural que limpa profundamente os fios do cabelo. Possui uma textura creme e uma fragrância delicada que te conduz às dunas de areias brancas do Oriente. * MODO DE USO: Distribua o produto no cabelo úmido no comprimento e pontas depois do shampoo. Deixe agir por 30 segundos e depois enxague. Pode ser utilizado diariamente. * RESULTADO: Condicionador hidratante para cabelos mais macios, hidratados e luminosos. Ação instantânea.', 247.9, 153.9, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-22100-2c567d4gl7ivb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F20158204895', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
