INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42213976614', 'Par Tambor Traseiro Hipper Freios Kombi 1982', 'Seja Bem-vindo(a)!! É um prazer imenso tê-lo em nosso anuncio. Abaixo algumas informações sobre o Produto e Aplicação. Por fim, conheça um pouco mais sobre a nossa loja. Produtos: 01 Par De Tambor Traseiro Sem Cubo Marcas: Hipper Freios Aplicação: Veículo: V. Kombi Motor: Todos Ano: 1982 Ficha Técnica: Medidas: Diametro Externo: 282mm / Espessura da pista: 61.5mm / Furo central: 65mm / 5 Furos Garantia: 90 dias. É novo, e acompanha nota fiscal Sim! Todos nossos produtos são novos acompanhados de nota fiscal. Sobre a Loja: Somos uma empresa que trabalha exclusivamente com o setor de peças para veículos leves e médios, sendo eles nacionais ou importados. Oferecemos peças com qualidade, prazo de entrega, parcerias com as melhores marcas e eficiência no atendimento. Temos uma equipe de profissionais qualificados para orientar o cliente nas suas mais variadas necessidades relacionadas à manutenção do seu veículo. Oferecemos também um amplo estoque de peças e envios diários. Visamos constantemente o aperfeiçoamento e melhoria dos serviços para a satisfação total do cliente. ATENÇÃO Para garantia de AMORTECEDORES, só serão aceitas mediante apresentação do certificado enviado junto ao produto. Sem esse documento, não será possível efetuar a garantia do produto. Em caso do não recebimento do certificado, favor nos enviar assim que receber a mercadoria e notar a ausência.', 444.52, 355.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/sg-11134201-7rdyb-mdm5emz62q8adf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373135807%2F42213976614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
