INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53602205550', 'CE LIMAX No ni Glow PAD 50ea', '⭐ Características dos recursos Contém extrato de Noni para acalmar e nutrir a pele. Auxiliando na vermelhidão.Fornece efeitos de resfriamento e hidratação, ajudando a reduzir a vermelhidão. Fórmula de baixa irritação adequada para peles sensíveis. As pilhas de pele mais lisa e impurezas removidas suavemente removem pilhas de pele morta e impurezas para uma textura mais suave. Entrega um brilho natural e brilho à pele. Ajuda a equilibrar os níveis de umidade da pele logo após a limpeza. 📘 Modo de usar Retire uma almofada. Removendo o excesso de sebo e as células mortas da pele. Use o lado em relevo para limpar suavemente todo o rosto, removendo o excesso de sebo e as células mortas da pele. Segure a almofada e use o lado macio para suavizar e refinar a textura da pele. Também pode usar a máscara como uma máscara de sooth colocando-a em áreas que precisam de 5 minutos. Continue com sua pele regular (toner, creme, etc.).', 111.43, 111.43, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134207-822x7-mhzjuott0av7da', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F53602205550', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
