INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19078251506', 'Cortador De Tubos De PVC 42mm Plus Vonder', 'Cortador De Tubos De PVC 42mm Plus Vonder Ideal para cortes rápidos e precisos em tubos de PVC, o Cortador de Tubos Plus Vonder facilita o trabalho em hidráulica, construção civil e outras aplicações. Com sistema de catraca e lâmina de aço com revestimento antiaderente, oferece cortes limpos com menor esforço. Itens Inclusos • 1 Cortador de tubos de PVC Especificações Técnicas Marca: Vonder Material da Lâmina: Aço com revestimento de PTFE Material do Corpo: Alumínio Capacidade de Corte: Tubos de PVC até 42 mm (1.5/8") Peso Aproximado: 437 g Garantia: 90 dias (legal, conforme o CDC) Por que escolher este produto? Produto novo e original Pronta entrega e envio em até 24 horas Compra 100% segura', 130.0, 89.9, NULL, 'Home & Living > Kitchenware > Graters, Peelers & Cutters', 'https://cf.shopee.com.br/file/sg-11134201-7qvek-lfh5zsvbf2rlae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F19078251506', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49564133457', 'Mixer 3 em 1 800W PMX2000 Philco', 'O Mixer Philco PMX2000 é ideal para quem busca mais praticidade, potência e versatilidade na cozinha. Com função 3 em 1, pode ser utilizado como mixer, processador e batedor, facilitando o preparo de receitas doces e salgadas no dia a dia. Com 800W de potência, oferece alto desempenho para bater, misturar, triturar, processar e preparar alimentos com mais rapidez. A lâmina Pro Maxx com 4 lâminas em inox, sendo duas grandes e duas pequenas, garante maior resistência, durabilidade e eficiência durante o uso. Conta com velocidade variável e função turbo, permitindo ajustar a intensidade conforme a necessidade da receita. O corpo desmontável facilita a limpeza, o armazenamento e o manuseio, tornando a rotina mais prática. O conjunto acompanha haste em inox, copo com capacidade total de 1050 ml e útil de 800 ml, jarra com capacidade total de 1,2 litro e útil de 600 ml, além de batedor de claras, ideal para omeletes, suspiros, claras e outras receitas leves. Destaques do produto: Função 3 em 1: mixer, processador e batedor Potência de 800W para alto desempenho Lâmina Pro Maxx com 4 lâminas em inox Velocidade variável com função turbo Acompanha copo, jarra, haste em inox e batedor de claras Informações técnicas: Marca: Philco Modelo: PMX2000 Tipo: Mixer 3 em 1 Potência: 800W Cor: Preto Funções: Mixer, processador e batedor Velocidade: Variável Função turbo: Sim Corpo desmontável: Sim Design: Ergonômico Haste: Inox Lâminas: Pro Maxx com 4 lâminas Material das lâminas: Inox Capacidade total do copo: 1050 ml Capacidade útil do copo: 800 ml Capacidade total da jarra: 1,2 litro Capacidade útil da jarra: 600 ml Acessório: Batedor de claras Aplicação: Bater, misturar, triturar, processar e preparar alimentos Uso indicado: Molhos, cremes, vitaminas, sopas, patês, massas leves, omeletes, claras, suspiros e receitas rápidas na cozinha Conteúdo da embalagem: 1 Mixer Philco PMX2000; 1 haste em inox; 1 copo de 1050 ml; 1 jarra de 1,2 litro; 1 batedor de claras; 1 manual de instruções Garantia: 3 meses contra defeitos de fabricação Prepare suas receitas com mais potência, praticidade e versatilidade usando um mixer completo para facilitar sua rotina na cozinha.', 344.9, 259.9, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/sg-11134201-82593-mqq9s19nqbkd20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F49564133457', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
