INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993624134', 'Lava Roupas Ola Coco 3,8L', 'A lavagem de roupas é uma tarefa doméstica comum na vida de todos. É preciso muita organização, cuidados com cada tipo de tecido e cor de roupa, conhecimento sobre quais produtos são importantes de serem usados. O Lava Roupas OLA é a sua escolha perfeita para o cuidado das suas roupas favoritas, com sua fórmula balanceada que não agride os tecidos finos e delicados, conservando-os como novos por muito mais tempo. Guardando e preservando momentos queridos, garantindo roupas limpas, macias e perfumadas. Agora com fragrância coco, ideal para roupas claras. Benefícios para você: Protege 20% mais contra o desbotamento dos tecidos para manter suas roupas como novas. Possui fórmula balanceada que não agride os tecidos conservando-os como novos por muito mais tempo.', 113.29, 70.2, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdvl-mc9ls7w2w1979b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F23993624134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
