INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41176891724', 'Romanos 1-7 | Série Estudando a Palavra | O Dom de Deus | Timothy Keller', 'Existe uma justiça que transforma e liberta cada aspecto da nossa vida. E nenhum de nós pode fazer por merecê-la ou mantê-la por si mesmo. Trata-se de uma justiça que procede de Deus. Romanos 1-7 trata justamente dessa justiça. Mostra-nos por que não a detemos, por que precisamos dela e como podemos recebê-la. É emocionante saber que “... o dom gratuito de Deus é a vida eterna em Cristo Jesus, nosso Senhor” (Rm 6.23). Os sete estudos deste volume da Série Estudando a Palavra o ajudarão a entender uma das partes mais lidas e comentadas da Bíblia. Eles o capacitarão a desembrulhar o precioso presente, ofertado pelo próprio Deus, da condição sem pendências ou dívidas diante dele e assim também transformarão seu coração, vida, identidade e perspectiva. 96 páginas 14x21cm', 21.9, 16.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8224q-mhpje7g3b4sh15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F41176891724', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12996030745', 'Leave-In Luxe Creations Extreme Repair 180Ml', 'Ajuda através de ação Termoativada a proteger os fios do calor durante a escovação facilitando a secagem. Contém filtro solar. Elaborado com alta concentração de ativos que combatem os sinais de envelhecimento capilar (cabelos opacos, fracos e desidratados), evitam o desbotamento da cor e recuperam rapidamente os fios mantendo-os hidratados, fortes, brilhantes e disciplinados. Ressecados, desidratados e opacos. Extrato de Pérola Negra e Aminoácidos Renovadores. Com ação termo ativada que protege os fios do calor durante escovação. Contém Filtro Solar e alta concentração de ativos que combatem os sinais de envelhecimento capilar, evitam o desbotamento da cor e recuperam os fios mantendo-os hidratados, fortes, brilhantes e disciplinados. Alta concentração de ativos reparadores; - Combate os sinais de envelhecimento capilar (cabelos opacos e quebradiços); - Elimina os danos acumulados e repara totalmente os fios; - Com Luxuoso Extrato de Pérola Negra que hidrata profundamente; - Evita o desbotamento da cor; - Fios fortes, hidratados, extra macios e com brilho intenso. Após o uso do Shampoo e Condicionador Extreme Repair, aplicar no cabelo molhado do comprimento dos fios até as pontas evitando a raiz. Não enxaguar. Finalize como de costume.', 70.08, 70.08, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-7rd3o-lx78xoku98jq2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F385388689%2F12996030745', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
