INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10042336441', 'Rolo para pintura Lã Topa Tudo 6MMx5CM c/cabo - Castor', 'O Rolo de Lã para pintura Topa Tudo 6 mm x 5 cm com cabo da Castor conta com tecnologia Não Respinga, desliza com suavidade deixando o acabamento perfeito e aveludado, tem uma boa absorção e retenção da tinta, é leve e fácil de manejar. Garante ótimos acabamentos, tudo para deixar seus ambientes com a aparência impecável. CARACTERÍSTICAS Superfície Indicada: Semirrugosas e Lisas Tipo de Tinta: Latéx PVA, Acrílicas, Esmaltes Sintéticos, Óleos, Vernizes e Zarcão. Acompanha Cabo: Sim Altura da Lã: 12 mm Instruções de Limpeza: Após o uso, retire o excesso de tinta em água corrente. Tintas látex pva ou acrílicas, lavar com água e sabão. Secar à sombra. Guardar em local arejado. Ambiente: sala de estar e jantar, quarto, hall, escritório e garagem. Código do fabricante: 530 FERRAMENTAS QUE TRANSFORMAM Transformar qualquer ambiente de forma rápida e sem muita sujeira, é isso que a linha de rolos para pintura da Castor traz para você. SEGURANÇA Compre com segurança! Nossa equipe de suporte estará à disposição caso tenha algum problema ou dúvida. Aguardamos seu pedido!', 20.71, 20.71, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-22110-htbnjzflvljv49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524472372%2F10042336441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892810796', 'Radiador para Kawasaki Ninja 650 Ex650 2012 2013 2014 2015 A 2016', 'Radiador para Kawasaki Ninja 650 Ex650 Original da marca Procooler Serve no meu veículo: Kawasaki Ninja 650 EX650 2012 a 2016 Marca: Procooler Código do Fabricante: PC10000108 EAN: 7899430249188 Peso: 1.5kg Medidas da Embalagem (a x l x p): 470x370x100mm O PRODUTO O radiador é um trocador de calor que tem como função dissipar o calor que circula no sistema de arrefecimento para manter a temperatura de funcionamento do motor num patamar ideal na casa dos 90 graus celsius. SOBRE A MARCA A PROCOOLER é uma marca especializada no desenvolvimento de componentes para sistemas de arrefecimento e climatização automotiva das linhas leve, pesada, agrícola e de construção civil. A marca oferece ao mercado de peças de reposição, produtos de alta performance e durabilidade, aliadas a qualidade exigida pelas montadoras. IMPORTANTE: - Produto Novo - Imagens Ilustrativas - Garantia de 6 meses pelo Fabricante - Indicamos que a instalação seja realizada por um profissional habilitado, mantendo a garantida do produto. - Atenção: Em caso de vendas para Pessoa Jurídica poderá haver incidência de ST (substituição tributária) que será calculada e cobrada a parte do cliente após o fechamento da compra, para então liberar o despacho da mercadoria. ATENÇÃO IMPORTANTE! Verifique com atenção as aplicações listadas na descrição deste anúncio e compare com as especificações do seu veículo, tais como: - Motorização - Ano de fabricação - Modelo - Câmbio manual ou automático - Com ou sem ar-condicionado - Tipo de combustível Aconselhamos comparar o código e as dimensões da peça anunciada com o código e as dimensões da peça original instalada em seu veículo. Se ainda assim ficar com dúvidas, nos mande uma pergunta.', 1039.96, 779.97, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/br-11134201-7r98o-macs2w869b4f19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F548632689%2F23892810796', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
