INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21798272711', 'Regata Feminina Canelado de Viscose Marialícia Vermelho', 'A Regata Marialícia é perfeita para composições leves e estilosas. Confeccionada em canelado de viscose, ela possui comprimento regular, modelagem ajustada e detalhe em recorte nas cavas, trazendo um toque diferenciado para o visual. Além disso, seu tecido canelado garante ótimo caimento e um toque moderno. Ideal para composições estilosas de trabalho ou para momentos de lazer, essa peça é a escolha certa para criar looks versáteis com personalidade!Modelo veste tamanho G1. Medidas da modelo: 99cm de busto; 124cm de quadril; e 84cm de cintura.', 89.9, 35.96, NULL, 'Women Clothes > Tops > Tanks & Camisoles', 'https://cf.shopee.com.br/file/sg-11134201-82597-mr1tj0tdvn5wcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F21798272711', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593740239', 'Calça Feminina Legging Marialícia Preto', 'A Calça Feminina Legging Marialícia é confeccionada em cotton, ideal para momentos de lazer e atividades físicas, proporciona liberdade de movimento e extremo conforto. Pode ser usada tanto para exercícios quanto para compor looks casuais, combinando perfeitamente com camisetas e tops. Aproveite o conforto e a praticidade dessa legging e adicione ao seu guarda-roupa peças versáteis e modernas.', 104.9, 104.9, NULL, 'Women Clothes > Pants & Leggings > Pants', 'https://cf.shopee.com.br/file/sg-11134201-825a3-mr1rllaz71tx45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F22593740239', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493168055', 'Harry Potter Meu Diário Mágico - Ciranda Cultural', 'Harry Potter Meu Diário Mágico - Ciranda CulturalO Harry Potter Meu Diário Mágico da Ciranda Cultural é um produto encantador que permite que você escreva sobre sua vida, família e amigos de forma única e especial. Com uma caneta especial com tinta invisível e uma luz para iluminar as páginas, você pode registrar todos os seus pensamentos e aventuras de forma secreta e divertida. Idade recomendada: A partir de 4 anos. Selo Inmetro: 5154/2022. Diferenciais:Caneta especial com tinta invisível para escrever de forma mágica. Luz para iluminar as páginas e revelar as mensagens. Perfeito para fãs de Harry Potter e para estimular a criatividade. Mais sobre o Produto:Com este diário mágico, as crianças podem escrever segredos e histórias de forma invisível e revelá-los apenas com a luz especial, criando uma experiência encantadora e cheia de mistério digna do universo Harry Potter. Perfeito para guardar memórias de um jeito único, ele estimula a imaginação e é um presente incrível para fãs de todas as idades, meninos e meninas a partir de 4 anos. Dicas de Uso:Use o diário para escrever sobre suas aventuras favoritas do mundo mágico de Harry Potter. Crie códigos secretos e mensagens especiais com a tinta invisível. Revele suas memórias iluminando as páginas com a luz na tampa da caneta. Presenteie um fã de Harry Potter com esse diário mágico e único. Ficha Técnica:Marca: Ciranda Cultural; Nome do produto: Harry Potter Meu Diário Mágico; Idade recomendada: A partir de 4 anos; Selo Inmetro: 5154/2022; Contém: 1 diário com cadeado e 1 caneta.', 29.99, 29.99, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdvh-ly54eulgs8yq14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F23493168055', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198135728', 'KIT Com 5 Bíblias Para Crianças | Histórias Do Antigo E Novo Testamento - 3 Palavrinhas', 'Conheça lindas histórias do Antigo e Novo Testamento! Junto da Turma de 3 Palavrinhas, você vai descobrir os ensinamentos de Jesus e aprender valores como bondade e compaixão. 14x21cm 128 Páginas', 54.9, 47.77, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mic2mv3ibpj618', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22198135728', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
