INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28039707170', 'Enxaguante Bucal Listerine Melancia & Hortelã sem Álcool 1L', '?que é e para que serve? Você sabia que os dentes são apenas 25% da sua boca? Por isso, apenas a escovação não garante uma limpeza completa. Adicione LISTERINE® Melancia & Hortelã Enxaguante Bucal Sem Álcool, 1L à sua rotina e limpe aonde a escova não alcança, eliminando até 99% dos germes* causadores de mau hálito, placa bacteriana e gengivite. Inclua LISTERINE® e limpe até 100% da sua boca. Benefícios e diferenciais - Refrescância Suave de Melancia & Hortelã - Sem álcool -Mais proteção contra mau-hálito, placa e gengivite*. *vs. somente escovação -Fórmula exclusiva com agentes antibacterianos -O enxaguante n°1 do mundo -Mata até 99,9% dos germes que causam os principais problemas bucais -Produto 100% reciclável (frasco e tampa) e feito com 50% de plástico reciclado -24 horas de proteção com o uso a cada 12 horas -Especialista em enxaguante bucal há mais de 140 anos', 48.19, 48.19, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdvl-mdaq4qr4x41jb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F28039707170', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12910599663', 'Protetor Solar Sundown Kids FPS 60 120mL', 'O protetor solar Sundown® Kids FPS60 proporciona proteção imediata UVA + UVB logo após a aplicação. Foi especialmente desenvolvido para pele delicada das crianças, com ativos calmantes que minimizam a ocorrência de alergias. Conta tripla proteção, ajuda a proteger a pele de elementos agressores como o sol, cloro e a água salgada do mar. Protege a pele de queimaduras solares dentro e fora d''água (9x mais resistente à água). Proteção completa (pode ser usado no corpo e rosto) para curtir a vida ao ar livre; uva + uvb balanceado; resistente à água por 8 horas; hidratação prolongada; fotoestável: mesma proteção durante todo o tempo de exposição ao sol', 118.29, 118.29, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/sg-11134201-23010-kb9f2qrga9lv44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F12910599663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
