INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599208080', 'Kit 10 Sachê Perfumado Sortidos Via Aroma - 10g', 'O Kit Sachê Perfumado 10g Via Aroma é prático e cheiroso, perfeito para perfumar todas as gavetas e armários da casa. Neste kit, leve com você 10 unidades de sachês com fragrâncias clássicas sortidas. Os produtos do kit não podem ser trocados ou escolhidos, serão enviadas 10 unidades sortidas para você conhecer ou descobrir novos favoritos. Modo de Uso: Nada mais simples que usar o nosso Sachê Perfumado: basta retirar o envelope de papel do plástico protetor e colocar no local escolhido, podendo ser usado em gavetas, armários, closets e muito mais. Tem uma duração aproximada de 45 dias, dependendo do ambiente e condições de uso. Cuidados: Manter fora do alcance de crianças e animais domésticos. Uso externo. Não ingerir ou inalar. Cuidado, inflamável! Deixe longe do fogo e superfícies aquecidas. Evite contato direto com móveis, plásticos, acrílicos e superfícies pintadas, pois pode manchar. Conserve em temperatura ambiente e protegido da luz.', 129.0, 128.9, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Air Fresheners & Home Fragrance', 'https://cf.shopee.com.br/file/sg-11134201-7rcf5-lsu00dbebpybd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545693995%2F19599208080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
