INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19097763390', 'Mascara de Cilios Rimel Infinity Volume Longa Durabilidade Ana Hickmann', 'A máscara de cílios Ana Hickmann Infinity conta com pincel grande de nylon e textura cremosa, que encorpa e dá aparência de mais volume para os cílios. Aplicador com pincel grande, encorpa os fios e dá volume Modo de uso: Aplique nos cílios da raiz em direção às pontas, em movimento de ziguezague. Para removê-la por completo, recomendamos o uso de demaquilante à base de óleo ou bifásico. Aqua/Água, Silica/Sílica, Copernicia Cerifera Wax/ Cera de Carnaúba, Propylene Glycol/Propileno Glicol, Microcrystalline Wax/Cera Microcristalina, Acrylates/Octylacrylamide Copolymer/Copolímero de Acrilatos/Octilacrilamida, Stearic Acid/Ácido Estárico, Steareth-21/Estearete-21, Dimethicone/Dimeticona, Polysorbate 80/Polisorbato 80, PVP/Poli Vinil Pirrolidona, Triethanolamine/Trietanolamina, Phenoxyethanol/Fenoxietanol, Chlorphenesin/Clorfenesina, os corantes CI 77499/Corante Preto 77499 e CI 77266/Corante Preto 77266.', 29.9, 29.9, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/br-11134207-820lo-mli6ok5knuvba2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F984347359%2F19097763390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
