INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20796995167', 'Cabideiro de Chão Multimóveis VCR35005', 'O Cabideiro de Chão Multimóveis é prático e cheio de estilo, se destaca em qualquer tipo de ambiente. Ele possui estrutura em MDP e acabamento em pintura UV e parte em BP. Suas principais características são versatilidade, design contemporâneo, e linhas simétricas, trazendo elegância e harmonia no ambiente desejado. Conteúdo da Embalagem: Cabideiro de Chão Manual de Montagem Kit Ferragem Dimensões do produto montado: Altura: 165,5cm | Largura: 43cm | Profundidade: 33cm *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 319.99, 279.99, NULL, 'Home & Living > Home Organizers > Hangers & Pegs', 'https://cf.shopee.com.br/file/sg-11134201-7reov-m90pt7d3cucicd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F20796995167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19476213004', 'Armário de Cozinha Completa de Canto Veneza Multimóveis V2052', 'O Armário de Cozinha Completa de Canto Veneza Multimóveis V2052 tem um excelente custo benefício e um amplo espaço interno. Produzido em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), pés retrô em polipropileno, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. Os módulos de canto podem ser montados dos dois lados (esquerdo ou direito), conforme a sua preferência. Esta cozinha conta, ainda, com balcão com tampo removível (compatível com pia de 120 cm), com 1 gaveta e 2 portas. Os módulos são individuais e você pode montar da maneira que se adaptar melhor ao seu ambiente. Para deixar sua cozinha mais bonita e organizada, possui vidro reflecta e compartimento especial para utensílios mais altos. Conteúdo da Embalagem: 1 (um) paneleiro 62cm 1 (um) armário aéreo de canto 90cm 1 (um) armário aéreo com portas de vidro 120cm 1 (um) armário aéreo 70cm 1 (um) balcão com tampo de canto 90cm 1 (um) balcão com tampo 120cm Dimensões do produto montado: Altura: 203cm | Largura: 152 x 242cm | Profundidade: 32cm (aéreos e paneleiro) - 53cm (balcão com tampo) *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 2609.9, 1799.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7repb-m90poz5q36s5a0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F19476213004', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18597727544', 'Cama Auxiliar para Colchão 78x188cm Cocadinha Multimóveis BB354', 'A Cama Auxiliar para Colchão 78x188cm Cocadinha Multimóveis BB354 é uma excelente solução para proporcionar conforto e praticidade ao receber amigos ou familiares em casa. Com design sofisticado, esta cama auxiliar é uma adição versátil e funcional para o seu ambiente. Ideal para transformar sua cama em bicama, proporcionando espaço extra para acomodar visitas de forma confortável. - Produzida em MDP 15mm, garantindo durabilidade e resistência. - Acabamento acetinado (cerca de 20% de brilho), proporcionando um toque sofisticado ao ambiente. - Suporta até 60kg, oferecendo conforto e segurança durante o uso. - Com rodízios que facilitam a movimentação do móvel. - Não acompanha colchão (tamanho indicado 188x78cm). Conteúdo da Embalagem: 1 (uma) Cama Auxiliar Manual de Montagem Kit Ferragem Dimensões do produto montado: Altura: 21,5cm | Largura: 189cm | Profundidade: 83cm *Você pode consultar as medidas detalhadas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Aqui na Loja Multimóveis, você pode concluir sua compra facilmente com toda segurança. A entrega é garantida e aqui você está em 1° lugar. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 359.99, 249.99, NULL, 'Mom & Baby > Nursery > Cribs & Cradles & Beds', 'https://cf.shopee.com.br/file/sg-11134201-7rd74-lwj40ne4e6ac8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F18597727544', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
