INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12437898377', 'Alto Falante Automotivo 4 Hurricane Frente Trás Gm Corsa', 'Kit 4 Alto Falante 5 e 6 Polegadas 260w Hurricane Agora você poderá curtir suas músicas favoritas com falante 5 e 6 Polegadas em alto e bom som com o kit de alto falantes originais Hurricane. Compatível com diversos modelos de carro, esse produto complementa o som no seu carro com potência e tamanho sob medida. Modelo: CM5 Diâmetro Nominal: 5 Potência RMS: 130 RMS Modelo Quadriaxial Na Cor Preta com Azul Bobina Simples Cone Injetado em Polipropileno Borda em Borracha Surround Tweeters Piezo Diafragma de Mylar Carcaça Injetada Fácil Instalação Características • Cone injetado em Polipropileno • Tweeters Piezo • Diafragma de Mylar • Altura Reduzida • Borda em Borracha Surround • Carcac¸a Injetada • Bobina de 1¿ em corpo de Alumi´nio • Modelo: Class CM6 • Diâmetro Nominal: 6 Polegadas • Potência RMS: 65W RMS (Cada) • Potência Wmax: 130W (Cada) • Impedância Nominal: 4 Ohms • Modelo Quadriaxial • Resposta de Frequência: 80Hz a 22Khz • Sensibilidade: 89dB • Na Cor Preta com Azul • Bobina Simples • Cone Injetado em Polipropileno • Borda em Borracha Surround • Tweeters Piezo • Diafragma de Mylar • Carcaça Injetada • Fácil Instalação', 251.7, 211.43, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/bae17b8715c34e907cc9c6882eaa97be', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F12437898377', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
