INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599444848', 'IMPACT - VONIXX - 1,5L', 'Impact é um limpador universal, ecologicamente correto e não-corrosivo, desenvolvido para limpezas difíceis de superfícies diversas. Sua fórmula exclusiva promove alta eficácia na eliminação de manchas produzidas pro impacto de insetos, gordura e encardidos. Diluição 1:1 - Para superfícies incrustadas; 1:10 - Para limpeza pesada; 1:30 - Para média intensidade; 1:50 - Para limpeza de manutenção; Até 1:60 - Para extratoras; Até 1:20 - Para tornadores Recomendações Impact é ideal para uso em rodas, motores, pneus, chassi, cromados, estofados, carpetes, tecidos, metais, caixas de rodas e pintura automotivas. Obs: Impact pode ser utilizado em extratora e tornador. Informações adicionais Impact não é recomendado para uso em plástico internos e externos. Não recomendamos uso do produto em bancos de couro. -Ultra concentrado -Remove ceras e selantes -Ecologicamente correto Modo de usar Rodas, motores, chassis, pneus, pinturas: 1. Dilua o produto na proporção conforme indicação de uso; 2. Com o auxílio de um pulverizador pulverize a solução na área a ser limpa; 3. Utilize um pincel, escova macia ou aplicador de espuma e realize movimentos até observar o desprendimento da sujeira; 4. Enxágue cuidadosamente a superfície com o auxílio de uma lavadora de alta pressão. Carpetes, estofados e tecidos: 1. Dilua o produto na proporção conforme indicação de uso; 2. Com o auxílio de um pulverizador pulverize a solução na área a ser limpa; 3. Utilize uma escova macia ou um aplicador de espuma e realize movimentos circulares até observar o desprendimento da sujeira; 4. Utilize um aspirador específico para remoção de água e aspire toda a sujeira; 5. Aguarde secar completamente.', 62.53, 62.53, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-81zwx-mn0i78g19p1dac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552415726%2F22599444848', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
