INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18203656722', 'Conjunto Colar e Brinco Coração Ponto De Luz 6mm Feminino', 'Kit conjunto colar e brincos ponto de luz em formato de coração 6mm em prata 925 Esse kit é excelente para mulheres, um conjunto charmoso, lindo e combina com qualquer estilo de roupa, podendo ser usado em qualquer evento como cultos, festas, reuniões e, inclusive, no dia a dia. Esse belíssimo conjunto é uma ótima escolha para uso próprio e também para presentear alguém especial. No kit contém uma corrente veneziana de 45cm com um pingente ponto de luz de 6mm e 1 par de brincos de 6mm também. Não se preocupe com a embalagem, enviamos a joia em uma linda caixinha para presentear e guardar, feita em veludo. Todas as nossas peças acompanham um certificado de garantia permanente do teor da prata Garantia: Não cobrimos oxidação, ou quebra do produto. Cobrimos apenas a prata 925. Como evitar o escurecimento da prata: 1. Evite utilizar a joia ao mexer com produtos químicos 2. Ao dormir, tire-a e enrole num papel higiênico 3. Armazene sua joia em um local seco e arejado 4. Não deixe a joia entrar em contato com cosméticos (perfumes, cremes, produtos ou procedimentos químicos do salão de beleza)', 59.9, 49.9, NULL, 'Fashion Accessories > Accessories Sets & Packages', 'https://cf.shopee.com.br/file/br-11134207-7r98s-lmriajegwq2eee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316436073%2F18203656722', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
