INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '2994033218', 'Shampoo Pantene Liso Extremo 400ml', 'Todas as fórmulas da Pantene contém um blend de nutrição para proporcionar cabelos lindos como nunca. A coleção Liso Extremo é elaborada com extrato de seda, óleo de amêndoas e Pro-vitaminas que ajudam a alinhar cada fio de cabelo, deixando-os extremamente lisos. Os shampoos apresentan uma nova tecnologia patenteada chamada lipídios de restauração, que fortalece os cabelos e os deixa preparados para enfrentar o estresse do dia a dia. Uma nova era na qual eles não apenas limpam como também possuem fórmulas que podem dar aos cabelos uma maciez extraordinária e muita força. Complemente os cuidados com o cabelo com os outros produtos da coleção: condicionador, condicionador 3 Minutos Milagrosos, máscara intensiva e creme para pentear. • Liso extremo desde o primeiro uso* • Ajuda a alinhar cada fibra para obter cabelos extremamente lisos • A coleção foi elaborada com extrato de seda, óleo de amêndoas e provitaminas • A fórmula exclusiva Pro-V da Pantene penetra nos cabelos por uma infusão de ingredientes naturais, vitamina B5 e antioxidantes que ajudam na reposição de lipídios • O extrato de seda é reconhecido pelas propriedades que conferem maciez e poder protetor • O óleo de amêndoas é rico em vitaminas A, B e E, o que o torna um dos óleos mais completos em termos de benefícios para o cabelo • *Usando o sistema Pantene', 39.29, 39.29, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/f4bcbd97581d486dd34f9b36ff63548f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F2994033218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40457316588', 'Mangá - Bakuman Vol. 10 - Novo/Lacrado', 'Bakuman Vol. 10 Dos mesmos criadores de Death Note, a saga para criar o melhor mangá de todos continua! Mashiro e Takagi enfrentam um novo desafio ao precisarem apresentar uma obra nova, feita do zero, para a reunião de escalação dos editores! Miura, preocupado com o avanço da dupla, pede dicas para Hattori sobre como trabalhar melhor com ''Muto Ashirogi''. Ao tentarem trabalhar dentro da zona de conforto, os dois autores conseguem criar algo tão bom quanto ''Grana e Inteligência'', mas um novo adversário dificulta o avanço daquilo em que eles melhor conseguem trabalhar! Nem mesmo a Equipe Fukuda consegue entender como Saiko e Shujin podem evoluir além de seus limites. E embora óbvia, a solução para o problema da dupla de muitos nomes é difícil de alcançar em sua posição atual. O único capaz de guiar a dupla até o futuro brilhante onde enfrentarão Eiji Niizuma no mesmo nível... é o veterano Hattori! Tipo de Produto: Revista Segmentos: Mangás Marcas: JBC Mangás Autor(es): Takeshi Obata, Tsugumi Ohba ISBN: 9786555949063, 978-65-5594-906-3 Check-List: Julho/2025 Classificação Etária: Livre Editora: JBC Gênero: Comédia, Romance Indicação: Jovens Adolescentes - Ensino Médio Número de páginas: 192 Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 30/07/2025 Idioma: Português Condição: Novo/Lacrado', 51.9, 51.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rdyu-mbrzc4395uw7af', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F40457316588', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
