INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999867184', 'Puzzle 1000 Peças Flores Radiantes - Castorland Importado 1039042', 'Os quebra-cabeças Castorland® são fabricados na Polônia pela Castor®, uma empresa reconhecida no mercado há mais de 30 anos. São muito populares e apreciados por sua excelente qualidade em mais de 50 países em todo o mundo. A Castor® sempre se destacou pela rigorosa seleção e processamento gráfico de seu estoque de imagens, bem como pela extraordinária riqueza de detalhes que quase salta aos olhos em cada peça. Você achará a coleção de quebra-cabeças Castorland inspiradora. Pensando de diversificação, a Grow traz para o Brasil uma coleção de Puzzles da marca CASTORLAND para os apaixonados por cada quebra-cabeças. Mais que um passatempo divertido, os quebra-cabeças desenvolvem o raciocínio, relaxam e se transformam num autêntico hobby. Puzzle Importado Fabricante: Castorland® Condição: NOVO/ LACRADO Quantidade de peças: 1000 peças Dimensões do puzzle montado: 68,0 × 47,0 cm Dimensões da embalagem: 35,0 × 25,0 × 5,0 cm', 199.99, 199.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdve-mdkh352u3z7g42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F20999867184', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
