INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799018865', 'Jogo Novo War II', 'No novo War II as grandes batalhas serão travadas agora no continente europeu. Com novas regras, o jogo será mais intenso e dinâmico! Vibre desenvolvendo estratégias para conquistar diferentes regiões e vença os exércitos inimigos em lances eletrizantes, que vão contar com todo seu raciocínio e... só com um pouco de sorte. Cada jogador terá três miniaturas de aviões que sobrevoam o campo de batalha e dão vantagens durante os combates. Utilize de forma estratégica seus aviões aumentando suas chances de vitória com o dado de oito lados para conquistar novos territórios ou proteger fronteiras importantes. Experimente a incrível sensação de comandar uma força aérea com seu exército, conquistando grandes vitórias como um verdadeiro general! A partir de 10 anos Participantes : 2 a 4 Tempo estimado de jogo : 120 minutos', 199.99, 199.99, NULL, 'Gaming & Consoles > Video Games > Xbox', 'https://cf.shopee.com.br/file/sg-11134201-824gs-mfmpky2pw4jzbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F22799018865', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
