INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294977497', 'Pipoca Microondas Manteiga com Sal Yoki', 'A Pipoca de Microondas Yoki sabor Manteiga com Sal é perfeita para aqueles momentos de descontração em frente à TV. Prática e rápida de preparar, basta colocar no micro-ondas e em poucos minutos você terá uma pipoca deliciosa e crocante. * Milho de alta qualidade * Sabor delicioso de manteiga com sal * Não contém glúten e lactose * Contém derivados de soja Modo de preparo: - Abra a embalagem e separe o pacote de milho de pipoca. Coloque apenas o pacote de milho no centro do micro-ondas com o lado indicado para cima. - Não use o botão de pipoca. Ajuste o seu micro-ondas na potência máxima por até 3min. Atenção: ouça atentamente e, assim que o intervalo entre os estouros for maior que 2 segundos, desligue o aparelho. - Retire o pacote com cuidado (o vapor é muito quente!) abra-o puxando pelos cantos superiores. Bom apetite! Mesmo após o preparo, é normal que alguns grãos permaneçam sem estourar. O produto não deve ser preparado por crianças sem a supervisão de um adulto. Não estoure novamente nem reutilize a embalagem.', 4.79, 4.79, NULL, 'Food & Beverages > Snacks > Popcorn', 'https://cf.shopee.com.br/file/sg-11134201-8258e-mqnel3d6lreqae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554792%2F22294977497', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
