INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899306687', 'Garrafa térmica Botijão 9 Litros - Incess Blue Invicta', 'Produto: Garrafa térmica Botijão 9 Litros - Incess Blue Marca: Invicta Descrição: A Garrafa térmica Botijão 9 Litros Incess Blue da Invicta é ideal para qualquer ocasião, seja em casa, no escritório ou em grandes eventos, este produto destaca-se não apenas pelo seu imenso volume, mas também por sua eficácia em manter a temperatura de suas bebidas, garantindo sempre o melhor sabor e frescor. Além de todas estas características, a Incess Blue vem em uma cor azul vibrante, adicionando um toque de estilo aos ambientes enquanto cumpre sua função de forma impecável. Características: • Tampa com trava de segurança: Garante um fechamento eficaz, prevenindo vazamentos e acidentes, mantendo suas bebidas seguras e na temperatura ideal; • Capacidade de 9 Litros: Perfeito para servir grandes grupos sem a necessidade de constantes recargas; • Fácil limpeza: Compatível com máquina de lavar louças, facilitando sua vida após o uso; • Tripé retrátil: Um diferencial exclusivo da Invicta, oferece estabilidade e facilidade no manejo e na hora de servir; • Sistema de Servir: Prático sistema de torneira, permite que as bebidas sejam servidas de forma simples e eficaz, reduzindo derramamentos e desperdícios. Especificações: Material: Plástico" Capacidade: 9 Litros Cor Predominante: Azul " " Sistema de Servir: Torneira." Dimensões (C x L x A): 27.50 x 27.50 x 35.50 centímetros Peso: 1.56 Kg', 203.39, 164.9, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-82599-mr3s4ilkxjb834', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F19899306687', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
