INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19333165074', 'Tinta Coral Rende Muito Acrílica Fosco 3,6 Litros', 'Nome : Tinta Acrílica Fosca Coral Rende Muito 3,6LMarca: CoralModelo: Rende MuitoTipo: AcrílicoVolume: 3,6LRendimento Acabado: 34m²Acabamento: FoscoSuperficie: ParedesBase: ÁguaTempo Secagem: 4HorasAerosol: NãoInflamavel: NãoAmbiente: Interno e ExternoCoral RENDE MUITO é a tinta concentrada que permite diluição superior aos produtos convencionais, graças à sua exclusiva tecnologia TIXOPLUSTM. O resultado é um rendimento muito maior, com ótima cobertura e baixo odor, para pintar muito mais com a qualidade que você já conhece e conﬁa. Sua exclusiva oferta de cores prontas pinta com 16L o mesmo que o branco 18L, assegurando rendimento superior em todas as cores. Rende até 170m² acabados por embalagem em todas as cores.Materiais de aplicaçãoRôlo de lã de pelo baixo ou pincel de cerdas macias.Saúde e SegurançaDurante a preparação, aplicação e secagem do produto, mantenha o ambiente ventilado. É recomendado usar luvas e óculos de segurança na hora de pintar. Para mais informações, consultar o rótulo e a Ficha de Segurança (FISPQ) do produto.AcabamentoFoscoRendimento-Secagem ao toqueAo toque: 30minEntre demãos: 4hFinal: 4hNúmero de demãos3Características do produtoMáximo rendimentoTinta super concentradaAlta cobertura', 133.27, 119.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rccw-m65mnw6xklez70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717380864%2F19333165074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18833166273', 'Verniz Fundo Isolante Knotting Sparlack 900Ml', 'Verniz Fundo Isolante Knotting 0,9L SPARLACK Sparlack Fundo Isolante isola a resina natural da madeira, evitando a surgimento de manchas e o retardamento da secagem. Pode também ser utilizado como protetor de madeiras durante o período de obras. Indicação: Indicado para madeiras em ambientes externos e internos, como ipê, maçaranduba, vinhático, cabreúva, entre outras. Diferenciais: É um verniz selador incolor de excelente elasticidade, transparência, poder de selagem e secagem rápida. Dados de aplicação: Diluente: Não aplicável Diluição: Não diluir o produto. Pronto para uso. Rendimento: Até 32 m²/Galão/demão Até 8 m²/¼ Galão/demão Variável conforme tipo de madeira e espessura da camada aplicada. Nº de Demãos: 2 ou 3 demãos. Acessórios de Pintura: Utilizar pincel ou trincha de cerdas macias, rolo de espuma ou do tipo pelo baixo para epóxi, pistola ou imersão. Secagem: Toque: 20 minutos; Manuseio: 1 hora; Entre demãos: 2 horas Final: 2 horas Recomendações: Evite a aplicação em dias chuvosos, temperatura abaixo de 10ºC ou acima de 40ºC e umidade relativa do ar superior a 85%.', 113.99, 113.99, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/fee1d0053ac30f5a3463034cf4116c8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717380864%2F18833166273', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23491385083', 'Cabo Interno da Maçaneta Dianteira Direita Uno 2 Portas 1.0 1.4 8v Flex Way Vivace 2011 A 2018 - Lado Passageiro', 'Similar ao original: 518.360.67 *** NÃO SERVE NO MODELO 4 PORTAS - SOMENTE 2 PORTAS *** Usamos Fotos REAIS EM TODOS NOSSOS ANUNCIOS Produto com a qualidade Peças Premium Todos os nossos produtos acompanham nota fiscal Para compras com CNPJ de fora do Estado de São Paulo, o valor do imposto, (ST) Substituição Tributária NÃO ESTÁ INCLUSO NO VALOR DO PRODUTO ANUNCIADO, caso deseje comprar com CNPJ, após a emissão da nota fiscal, será calculado o valor do imposto de (ST), Substituição Tributária, que será COBRADO separadamente e antecipadamente. LEMBRANDO QUE O VALOR DO IMPOSTO, (ST) É COBRADO PELO ESTADO DE DESTINO e mercadoria só poderá ser despachada após o recolhimento antecipado. Peças Rápidas - O seu shopping de auto peças online!', 27.5, 27.5, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134201-7qukw-lhhwevi02v4tcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F513651190%2F23491385083', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
