INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15585773939', 'Saco de Dormir Acampamento Camping Pesca Retiro Com Zíper - Emcompre', 'Saco de dormir com zíper de enchimento em poliéster. Pode ser levado para qualquer lugar e ocupa pouco espaço por ser pequeno e fácil de guardar. A hora de dormir em suas viagens vai ser bem mais relaxante com o Saco de Dormir! Características: Enchimento: 100% Poliéster Tecido: 100% Polipropileno Com zíper Dimensões: Aberto: 192 cm x 75 cm x 3 cm Fechado: 40 X 20 cm (enrolado)', 128.7, 99.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m1e6cy6p8w5c29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F15585773939', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
