INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892509943', 'Par/Un Farol Dianteiro Fiat Uno 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 Fiorino 1ªLinha Novo', 'Par / Un Farol Dianteiro Fiat Uno 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 DESCRIÇÃO DO PRODUTO Os faróis, sejam de luz baixa ou alta, tem como função iluminar o caminho de um veículo. Nesse sentido, é importante que os condutores saibam como fazer a regulagem correta dos faróis, pois um farol desregulado não ilumina adequadamente a rodovia ou ainda pode causar ofuscamento, perda de visão momentânea, no condutor do veículo que transita em sentido contrário. ESPECIFICAÇÕES DO PRODUTO: - Lente de Acrílico - Carcaça de Plástico - Mascara Cromada - Encaixe de lâmpada H4 (Não acompanha lâmpadas) Compatível com: - Fiat Uno 2004 - Fiat Uno 2005 - Fiat Uno 2006 - Fiat Uno 2007 - Fiat Uno 2008 - Fiat Uno 2009 - Fiat Uno 2010 - Fiat Uno 2011 Way - Fiat Uno 2012 Way - Fiat Uno 2013 Way - Fiat Fiorino 2004 - Fiat Fiorino 2005 - Fiat Fiorino 2006 - Fiat Fiorino 2007 - Fiat Fiorino 2008 Especificação Técnica: • Suporta Lâmpadas até 55W • Regulagem de Foco Manual O QUE VEM NA EMBALAGEM Conteúdo da Embalagem: • 02 Faróis Principais ( Direito e Esquerdo ) OU • 01 Farol Principal ( Escolha o Lado ) FINALIZAÇÃO As imagens representam o real estado de conservação dos produtos. Mais detalhes e funcionalidades podem ser obtidos no chat! Compare o produto anunciado com o seu modelo de referência. Postaremos a sua mercadoria dentro de algumas horas após a confirmação da compra. Não esqueça! Tire todas as suas dúvidas conosco antes de comprar o seu produto. Auto Peças Nova Kennedy Agradece sua preferência!', 149.9, 109.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-820l8-mqwaghne3e2u37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F494312426%2F23892509943', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097689917', 'Chuteira Futsal Penalty Max 300 Y-1', 'A Chuteira Futsal Penalty Max 300 Y-1 é uma opção de alta performance projetada especificamente para jogadores de futsal.Com um design moderno e materiais de alta qualidade, oferece conforto, durabilidade e excelente desempenho em quadra. Benefícios: Desempenho Superior em Quadra. Conforto. Durabilidade. Resistência. Alguns diferenciais técnicos :A Chuteira Futsal Penalty Max 300 Y-1 conta com as tecnologias Non-Marking, Hiper Flex, Rotate e Ultra Grip, que proporciona aderência excepcional, tração multidirecional e movimentos ágeis, melhorando o desempenho durante as partidas.Além disso, a Chuteira Futsal conta com entressola Neo Cushion e a palmilha PU Conformada, que oferecem amortecimento eficaz contra impactos, proporcionando conforto durante todo o jogo e reduzindo a fadiga.Esses recursos combinados fazem da Chuteira Futsal Penalty Max 300 Y-1 uma escolha ideal para jogadores que buscam alta performance, conforto e durabilidade em suas partidas de futsal.', 225.99, 225.99, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/br-11134207-820m2-mnkgfdys7401cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F20097689917', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253197468', 'BIODERMA ATODERM GEL DOUCHE 1LT', 'Gel de banho antirressecamentopara os tipos de pele, inclusive as mais secas e sensíveis. Bioderma Atoderm Gel Douche limpa e hidrata profundamente, proporcionando uma sensação imediata de calma e combatendo o ressecamento. Deixa a pele aveludada e suave após o banho. O Gel de Banho Bioderma Atoderm Gel Douchefoi criado para limpar suavemente, suavizar o toque e aumentar a tolerância da pele. Seu complexo patenteado DAF™ (Dermatological Advanced Formulation) aumenta o limite de tolerância da pele, promovendo uma pele mais saudável e resistente. Contém ingredientes 100% naturais, incluindo Glicerina, Sulfato de Cobre, Girassol e Coco, que tratam, purificam, restauram o filme hidrolipídico e recuperam a barreira protetora da pele. Além disso, alivia a coceira e ajuda a eliminar o desconforto. Fórmula hipoalergênica e livre de sabão, corantes e parabenos. Produto levemente perfumado. Como usar: Indicado para uso diário, com aplicações entre uma ou duas vezes por dia. Aplique Atoderm Gel Douche na pele umedecida e espalhe o produto até formar espuma. Enxágue bem e seque suavemente. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 207.9, 207.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-82616-mjfu4fop1csk2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58253197468', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253174230', 'Lola Cosmetics Xapadinha - Máscara Capilar Disciplinante 100g', 'Máscara capilar disciplinante. Lola Cosmetics Xapadinha deixa as madeixas 55% mais disciplinadas e com redução de até 40% do frizz, tudo isso com efeito instantâneo. A Máscara Capilar Lola Cosmetics Xapadinha conta com um complexo ativo inovador, que protege o cabelo, alinha as fibras, restaura e oferece o cuidado que os fios necessitam. Ideal para garantir o liso brilhante e saudável que você tanto busca! Como usar: ​Aplique uma pequena quantidade nos fios limpos e úmidos. Distribua uniformemente em todo comprimento e pontas. Deixe agir por 2minutos e enxágue bem. Use semanalmente. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 27.9, 27.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8260p-mjyi0qzb5pmt15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58253174230', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7278359059', 'Prato Cristal 40cm Três Triângulos', 'Com um design sofisticado, o prato cristal Três Triângulos é ideal para servir os alimentos com muita elegância. E por conta da sua beleza, eles também podem fazer parte da decoração de festas e eventos. Prato Cristal 40 cm Ref.: 3T00311 Disponibilidade: Pronta Entrega – Fabricado com material de qualidade; – Produto resistente; – Acabamento de alto brilho e design moderno; – Pode ser usado em casa, festas e eventos. Peso: 306g Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 26.99, 26.99, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m51t5fvea2q8b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F7278359059', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
