INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55457168520', 'Furadeira de Impacto Reversível 1/2" (13mm) 710W Dewalt', 'PRODUTO PRONTA ENTREGA COM ENVIO IMEDIATO Furadeira de Impacto Dewalt 710W | Força, Precisão e Durabilidade Profissional A Furadeira de Impacto Dewalt é a ferramenta indispensável para quem busca alta performance tanto em reformas domésticas quanto em canteiros de obras. Com um motor robusto de 710W, ela entrega a potência necessária para perfurações em madeira, metal e alvenaria com extrema facilidade. Seu sistema de impacto de 44.200 IPM garante agilidade ao furar concreto e tijolos, poupando tempo e esforço. Este modelo conta com velocidade variável e reversível, permitindo um controle total sobre a rotação (0 a 2.600 RPM) — ideal para iniciar furos com precisão ou para ser utilizada em tarefas de parafusamento. Com um design ergonômico e peso equilibrado de apenas 1,8 kg, ela proporciona um manuseio confortável, minimizando a fadiga mesmo após longas horas de trabalho. Destaques do produto Potência Profissional: 710W de puro desempenho para aplicações severas. Velocidade Variável e Reversível: Controle eletrônico no gatilho para se adaptar a diferentes materiais. Função Impacto: Alta taxa de percussão para perfuração rápida em alvenaria e concreto. Capacidades de Perfuração: Perfura até 25mm em madeira e 13mm em aço ou alvenaria. Ergonomia e Controle: Acompanha empunhadura lateral 360° e limitador de profundidade para furos padronizados. Disponibilidade de Voltagem: Modelo disponível em 127V ou 220V (selecione a voltagem desejada antes de finalizar a compra). Informações técnicas Marca: Dewalt Potência: 710 W Tensão: 127V ou 220V (Escolha no anúncio) Mandril: 1/2" (13 mm) Rotações por Minuto: 0 - 2.600 RPM Impactos por Minuto: 0 - 44.200 IPM Capacidade Madeira: 25 mm Capacidade Aço/Alvenaria: 13 mm Peso do Produto: 1,8 kg Cabo de Energia: Com fio (Corded) Conteúdo da embalagem 1 Furadeira de Impacto 710W Dewalt; 1 Empunhadura Lateral; 1 Limitador de Profundidade; 1 Chave de Mandril; Manual de Instruções. Garantia:3 meses Eleve o nível do seu trabalho com a confiança e a tradição que só uma Dewalt oferece!', 554.9, 414.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8262n-mls4awxy483s15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F55457168520', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
