INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793667140', 'TINTA POLIÉSTER CINZA SCANDIUM MET 2004 FIAT 900ML LAZZUDUR', 'TINTA AUTOMOTIVA POLIÉSTER 900ML LAZZUDUR A tinta automotiva à base Poliéster da Lazzuril é indicado para pintura geral, parcial e retoques de veículos automotivos, nacionais e importados, fácil de usar e aplicar. Disponível em sistema mixing machine ( lisas, metálicas e perolizadas). Possui secagem rápida, excelente resistência às intempéries naturais e agentes químicos. Padrão Original Base Poliéster Pronta para Uso Requer aplicação de verniz automotivo após a aplicação da tinta. Conteúdo: 900ML TINTA POLIÉSTER CINZA SCANDIUM MET 2004 FIAT 900ML LAZZUDUR', 101.82, 101.82, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7rbkd-m5khf2lik7ha4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343260914%2F22793667140', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
