INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298310874', 'Fonte Carregador Para Notebook Lenovo Ideapad 310S-15IKB', 'Fonte Carregador compatível com Lenovo Ideapad 310S-15IKB 20V 3.25A 65W A fonte para Lenovo Ideapad 310S-15IKB foi aprovada em rigorosos testes de qualidade e atende todas as exigências do seu equipamento. Possui tecnologia exclusiva de proteção contra excessos de corrente, superaquecimento e curto-circuito. Todas as fontes bringIT possuem 36 meses de garantia contra defeitos de fabricação. E contam com seletor automático de tensão, que permite funcionamento em 110V e 220V. Atenção: Essa é uma fonte bringIT, portanto não é um produto original da fabricante Lenovo. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Para evitar problemas de compatibilidade, por favor verifique as especificações da sua fonte. OUTPUT: DC 20V 3.25A 65W Plug: 4.0mm x 1.7mm Caso você não possua a fonte original, você pode encontrar esta informação em seu notebook indicada como INPUT. Itens inclusos: cabo de 1,20m Marca: bringIT Modelo: 310S-15IKB Referência: FW133-CAT-0001 Atenção: Para que essa fonte seja compatível com seu notebook, deverá ter pino e voltagem iguais e a amperagem igual ou maior que a do anúncio. Esse produto é compatível com os notebooks: S145, 330-15IKB, 3-15ITL6, S145-15IIL, 510S, ADLX65CLGU2A, S145-15IWL, V15 82UM0002BR, 3I-15IGL, ADLX65CLGB, 15ALC6, 310, B330-15IKBR, 15IML05, 82C3001WSP, S145-15API, 310S-15IKB, ADL45WCH, 15IGL05, S145-15IKB Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 107.89, 79.9, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-8259r-mqsm8qtqu4gbf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1097013207%2F23298310874', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26542465702', 'Mochila Esportiva Flamengo Bagaggio Suporte de Bola 20L - Preto e Vermelho', 'A Mochila Esportiva Flamengo é ideal para os torcedores apaixonados pelo clube e que buscam praticidade no dia a dia. Com um design moderno e funcional, ela é perfeita para transportar materiais esportivos e itens essenciais com estilo, exibindo o escudo do Flamengo com orgulho. A mochila traz o escudo oficial do Flamengo bordado em destaque, reforçando o orgulho pelo time em qualquer ocasião. Possui compartimento frontal em tela é perfeito para carregar uma bola de futebol, oferecendo praticidade para quem pratica esportes, bolsos laterais que são ideais para transportar garrafas de água ou outros itens de uso rápido durante a prática esportiva, o compartimento principal oferece amplo espaço para transportar uniformes, chuteiras, materiais escolares ou itens do dia a dia e alças acolchoadas e ajustáveis poporcionam mais conforto durante o uso prolongado, sendo ajustáveis para maior praticidade e ergonomia. Garanta já a sua!', 499.9, 239.9, NULL, 'Women Bags > Backpacks', 'https://cf.shopee.com.br/file/sg-11134201-824je-mf9s9u2urr4b63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F26542465702', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57450919490', 'Camisa Flamengo Zico Retrô Libertadores Masculina - Preto e Vermelho', 'Produzida em poliéster leve e respirável, a camisa do Flamengo, modelo Zico Retrô, é a pedida certa para os torcedores vestirem sua paixão pelo Mengão. O design apresenta a cor preta como predominante e traz recortes em vermelho nos ombros, nuca e mangas. Além disso, o escudo do time marca presença bordado do lado esquerdo do tórax. Do lado oposto, conta com a assinatura do jogador Zico e o ano de 1981, fazendo referência à época que o time conquistou a Libertadores da América. Por fim, possui o nome e o número do craque estampados na parte traseira. Peça já a sua!', 249.9, 199.9, NULL, 'Women Clothes > Tops > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mk85tt6su77k64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F57450919490', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
