INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257306496', 'Multimídia Mp5 H-tech Ht-7428 Carplay/android 4/128gb', 'A Multimídia HT-7428CA 2DIN de 7 polegadas é a escolha ideal para quem busca modernidade, conectividade e alta performance no sistema do veículo. Com tela em vidro e painel IPS, proporciona imagens mais nítidas, cores vivas e excelente ângulo de visão, elevando a experiência ao dirigir. Equipada com processador Quad-Core, 4GB de memória RAM e 128GB de armazenamento interno, garante rapidez nas respostas e ótimo desempenho na execução de aplicativos. Conta com conectividade completa, incluindo GPS e Wi-Fi integrados, além de compatibilidade com espelhamento de smartphone, CarPlay e Android Auto (com e sem fio, conforme versão), permitindo acesso facilitado a navegação, músicas e aplicativos. O modelo oferece potência de 4x60W RMS, entregando um som forte e limpo. Possui Bluetooth para chamadas e reprodução de músicas, além de diversas opções de conectividade como entradas USB, entrada para câmera de ré e frontal, entrada de áudio e vídeo, microfone externo e saída dedicada para subwoofer. Seu design é moderno e personalizável, com 7 opções de cores de iluminação do painel e diferentes layouts de interface, adaptando-se ao estilo do usuário e ao interior do veículo. Também conta com suporte para comandos de volante (SWC), permitindo configurar até 10 funções para mais praticidade e segurança ao dirigir. Especificações Técnicas: * Tela: 7 polegadas * Resolução: 1024x600 * Painel: IPS com vidro * Processador: Quad-Core * Memória RAM: 4GB * Memória Interna: 128GB * Potência: 4x60W RMS * Bluetooth: chamadas e música * GPS: integrado * Wi-Fi: integrado * Espelhamento: compatível com CarPlay e Android Auto (consulte versões) * Entradas: 2 USB, câmera traseira, câmera frontal, áudio e vídeo, microfone * Saída: Subwoofer * Comando de volante (SWC): até 10 funções programáveis * Iluminação: 7 cores de painel * Layout: múltiplas opções Dimensões do produto: * Altura: 23 cm * Largura: 20 cm * Comprimento: 8 cm * Peso: 0,875 kg Ideal para quem deseja unir tecnologia, conectividade e qualidade sonora em um único equipamento, tornando o dia a dia no trânsito muito mais prático e agradável.', 943.57, 868.09, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-823ph-mpcpw0uizrim77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F329035577%2F58257306496', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49506148614', 'Bota Infantil Menina Country Preta Bordado Floral Com Franja Babado Boiadeira 22 Ao 27', 'TABELA DE MEDIDAS 22 - 15 cm 23 - 15,5 cm 24 - 16 cm 25 - 16,5 cm 26 - 17 cm 27 - 17,5 cm DESCRIÇÃO A Bota Infantil Country Preta é perfeita para meninas que amam estilo e conforto. Com design inspirado no modelo western, ela possui lindos bordados florais delicados e detalhe em franja na parte frontal, trazendo charme e personalidade ao visual. Produzida com material resistente e acabamento de qualidade, conta com solado antiderrapante que garante mais segurança ao caminhar. Ideal para passeios, festas, eventos escolares e para compor looks modernos e estilosos no dia a dia. DESTAQUES - Modelo infantil estilo country - Cor preta com bordado floral colorido - Detalhe em franja frontal - Solado resistente e antiderrapante - Fácil de calçar - Numeração disponível: 22 ao 27', 129.9, 99.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Boots', 'https://cf.shopee.com.br/file/br-11134207-820lp-mq7py70m34ld36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296584125%2F49506148614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
