INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798769777', 'Violão Eletroacústico Strinberg Sd301hcr Galaxy com Efeito para destros', 'Somos a RCK AUDIO, sua loja virtual de Instrumentos Musicais e Áudio Profissional - Há mais de 10 anos no mercado - Mais de 150.000 clientes atendidos - Todos os produtos com Nota Fiscal - Revenda autorizada oficial do produto - Criterioso processo de embalagem e expedição ; Violão Eletroacústico Strinberg SD301HCR para destros A Strinberg nasceu na década de 90 com o intuito de oferecer aos músicos uma linha de instrumentos de cordas diferenciada e com estilo próprio. Seguindo os padrões de qualidade exigidos pelo mercado americano, a marca possui em sua alma a essência da musicalidade brasileira. Especificações: - Modelo: SD301HCR - Tipo: Violão Eletroacústico - Cor: Mahogany Satin (MGS) - Acabamento: Fosco - Formato do Corpo: Folk Half Cutaway com Arm Rest - Encordoamento: Aço .011 / .048 - Número de Cordas: 6 - Madeira de Braço: Nato - Madeira de Tampo: Sapele Laminado - Madeira da Lateral: Sapele Laminado - Madeira de Fundo: Sapele Laminado - Cavalete: Indian Laurel - Escala: Indian Laurel - Tensor: Sim. Bilateral - Nut (Capo Traste): 43mm - Número de Trastes: 20 - Marcações de Escala: Dots - Tarraxas: Blindadas Cromadas - Escudo: N/A - Utilização/Mão: Destro - Pré: Galaxy (com efeitos de ambiência e modulação) - Captação: Piezo / Microfone Interno / Auto falante de 1 Polegada para reprodução de efeitos acusticamente - Alimentação: Bateria Lithium 3.7 volts recarregável - Jack de Saída: P10 - Controles do Pré: Volume Master, Volume Mic., Tonalidade, Ajuste Reverbs Room / Hall (On / Off dos efeitos via push button), Ajuste Delay / Chorus (aciona o Afinador Cromático via push button) Porta USB C para carregamento de bateria, Check Bateria. - Autonomia da Bateria: - Plugado, sem os efeitos acionados: 168 horas - Plugado, com os efeitos acionados: 18 horas - Desplugado, com os efeitos acionados: 17 horas - Tempo de recarga, com a bateria totalmente esgotada: Aproximadamente 3 horas', 2126.99, 2126.99, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7rdxf-mcqpz5vt2lknfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F313967528%2F22798769777', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
