INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23736026062', 'Kit 4 Peças Moletom Minimalista Bebê Menino Baby Neném Blusa e Calça Manga Longa Roupa de Frio Inverno Masculino', 'Kit de 2 Conjuntos de Moletom para Meninos! 🧥❄️ Perfeito para garantir conforto e estilo ao seu pequeno durante o outono e inverno! ✅ Conjunto Completo: 2 casacos e 2 calças. ✅ Tecido Confortável: 60% algodão e 40% poliéster, garantindo maciez e conforto. ✅ Ajuste Perfeito: Ribana nos punhos e na barra para maior proteção contra o frio. ✅ Moletom Peluciado: Conforto e aquecimento extra nos dias frios. ✅ Estampas variadas e encantadoras: Muita praticidade e estilo em uma única compra. Sugestão de Tamanho por Idade: Tamanho 1: Indicado para 6 meses a 1 ano Tamanho 2: Ideal para 1 ano Tamanho 3: Ótimo para 2 anos Tamanho 4: Excelente para 3 anos Tamanho 6: Ideal para 4/5 anos Tamanho 8: Perfeito para 6/7 anos Tamanho 10: Excelente para 8/9 anos Os tamanhos podem variar de acordo com o biotipo/tamanho de cada criança. 👉 Consulte a tabela de medidas nas imagens, ou na guia de tamanho da Shopee. IMPORTANTE! ⚠️ Não há opção de escolha dos modelos. ⚠️ Os modelos enviados serão sortidos conforme a disponibilidade em estoque. ⚠️ Na compra de 4 kits do mesmo tamanho, pode haver repetição de cor ou estampa. Envios em 24 horas 🚛 - Para todos os pedidos realizados antes das 13h. Garanta já o seu kit e proporcione o máximo de conforto e estilo para seu príncipe!', 100.0, 44.99, NULL, 'Baby & Kids Fashion > Baby Clothes > Sets', 'https://cf.shopee.com.br/file/br-11134207-820lk-mn0gxqnjoirk00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341167297%2F23736026062', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493526305', 'Retífica Pneumática De 1/4 Polegada Chiaperini Ch R-25', 'Retífica Pneumática De 1/4 Polegada Chiaperini Ch R-25 Descrição: - Retífica pneumática de 1/4” para uso profissional e industrial em linha de montagem, marcenarias, serralherias, nos acabamentos de superfícies soldadas, alargamento de furos acabamento em moldes, matrizes e muito mais! Desenvolvida com rotor de 4 palhetas, rolamentos industriais, desenho compacto e com cabo ergonômico a retífica realiza trabalhos com menor vibração e maior precisão na hora de fazer o acabamento no seu trabalho. Características: - Acionamento rápido e prático; - Saída de ar na parte traseira da máquina; - Ergonômica; - Compacta; - Leve. Dados Técnicos: - Marca: Chiaperini; - Referência: CH R-25; - Pinça: 1/4"; - Rotação s/ carga: 25000rpm; - Consumo de ar médio: 4 pcm; - Pressão de trabalho: 90 psi; - Entrada de ar: 1/4"; - Dimensões: 170 x 70 x 45mm; - Peso: 0,400kg. Dicas de Segurança: - É obrigatório o uso de filtro regulador lubrificador, manter a pressão em 90 libras com a máquina em funcionamento, evitar umidade nas partes internas da máquina, utilizar somente óleo MFP 10W, próprio para ferramentas pneumáticas, lubrificar os martelos de acordo com a necessidade com graxa de preferência e utilizar mangueiras com 7 metros de comprimento no máximo. Itens Inclusos: - Conector de engate rápido; - Pinça de 1/4"; - Manual de Instruções.', 239.0, 239.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7renm-m2cv0xjh2x5i4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397583038%2F22493526305', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
