INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23399152039', 'Blusa Cropped Juvenil Menina Estampa Puff Beats Preto', 'Peça-chave para o dia a dia teen, a Blusa Elian Beats em meia malha possui comprimento cropped e modelagem mais soltinha, garantindo um toque moderno ao visual. Suas mangas curtas alongadas e ombros deslocados oferecem leveza à peça, enquanto a estampa frontal em puff com comidinhas traz um ar descontraído para os looks das teens. Ideal para curtir um fim de semana com muito estilo, aposte nesse item indispensável para o closet teen!Detalhes da peça: • Feita em meia malha • Possui comprimento cropped • Possui mangas curtas • Possui estampa frontal com detalhe em puff • Ideal para curtir o fim de semana', 59.9, 23.96, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-8257y-mr1tox3toyyuba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F23399152039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
