INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797506464', 'Produto Para Limpar Cinto De Segurança Sintra Fast Vonixx', 'SINTRA FAST 500ML - LIMPEZA INTERNA DE VEÍCULOS DESCRIÇÃO: Sintra Fast é um multilimpador flotador universal, bactericida e germicida de pH balanceado, indicado para limpeza de painéis, laterais e cantos de portas, bancadas de couro, carpetes e estofados. MODO DE USO: Em painéis, laterais, cantos de portas e bancos de couro: 1. Pulverizar o produto na superfície a ser limpa e desinfetada 2. Utilizar pincel, escova macia ou aplicador de espuma e realizar movimentos circulares até observar o desprendimento total da sujeira 3. Remover o excesso com auxílio de toalha de microfibra úmida. Secar em seguida com uma toalha de microfibra seca', 49.92, 49.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvbtqyfiwyjc4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F22797506464', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
