INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209475448', 'Limpador para Limpeza Pesada Cloro Ativo Embalagem Econômica Veja', 'Novo Veja Limpeza Pesada Cloro Ativo X-14 2 em 1: branqueia¹ e desinfeta². Sua fórmula com Cloro Ativo X-14 limpa, possui ação desinfetante e branqueadora, eliminando germes e bactérias e removendo sujeiras escuras (limo) que se formam entre os pisos. Ao diluir em água, rende até 62 litros na limpeza do dia a dia. ¹Branqueamento proporcionado na limpeza do limo (Aspergillus Niger). ²Bactérias testadas: Salmonella choleraesuis e Staphylococcus aureus.', 22.49, 22.49, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8259l-mqnekwmnybyb31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554958%2F58209475448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
