INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593569448', '1 Million Elixir Paco Rabanne Perfume Masculino Eau de Parfum Intense', 'A icônica barra de ouro 1 Million, mais ousada, distinta e sofisticada, agora, no Perfume Importado Masculino 1 Million Elixir, Eau de Parfum, de Paco Rabanne. Uma joia artesanal que reflete as diferentes facetas da fragrância. Sinal de uma nova força: sólida, intensa e enigmática. O frasco, cuidadosamente, elaborado, encapsula a alma e a essência de 1 Million, com uma a profundidade infinita nesta nova criação olfativa. O auge da intensidade absoluta. 1 Million Elixir EDP, mais rico do que nunca, para sensações emocionantes: os ingredientes escolhidos a dedo, Rosa Damascena Turca, Osmanthus e Fava Tonka, sem dúvida, fazem esta composição, uma obra-prima a se destacar pela extrema qualidade de suas matérias-primas. Profundamente sensual, o licoroso Davana vibra com o poder da madeira e das sementes pretas de baunilha. A suprema sensualidade encontra o poder absoluto de longa duração.', 846.99, 829.99, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7rbnk-lpqs46dg5yka91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F602117686%2F23593569448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21997607386', 'Camisa Básica Masculina Polo Gola Esporte E Bolso Piquet', 'Camisa Polo Básica Malwee confeccionada em piquet stretch. Modelo possui modelagem tradicional, que acompanha as linhas do corpo com muito conforto, mangas curtas, gola esporte em retilínea e fechamento por peitilho com 2 botões. As camisas polo Malwee são atemporais e indispensáveis no guarda-roupa masculino por serem versáteis, confortáveis e feitas para durar, já que possuem a melhor durabilidade do mercado. O tecido piquet stretch possui ótima aparência, toque macio e agradável de se vestir, além de ser respirável e fácil de cuidar. Combine com bermuda de moletom Malwee e sapatênis. Modelagem: TradicionalGola: Esporte', 99.9, 89.91, NULL, 'Men Clothes > Tops > Polo Shirts', 'https://cf.shopee.com.br/file/sg-11134201-7rblx-lqkuz6z6vvd040', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939838662%2F21997607386', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792796721', 'Kit Esmalte Impala Transparente Top Pop (5 unidades)', 'Esmalte Impala: Duradouro, Brilhante e Inspirado nas Últimas Tendências Descrição: O Esmalte Impala é a escolha perfeita para quem busca unhas impecáveis e duradouras. Com sua fórmula inovadora, o esmalte proporciona brilho prolongado e ação duradoura, mantendo suas unhas lindas por dias. Inspirados nas últimas tendências, os Esmaltes Impala possuem uma ampla variedade de cores e acabamentos para você escolher. Desde tons clássicos até cores vibrantes e ousadas, há um esmalte Impala para cada ocasião e estilo. Com fácil aplicação e secagem rápida, os Esmaltes Impala são a escolha ideal para quem busca unhas perfeitas sem esforço. Modo de usar: 1. Prepare as unhas limpando-as e retirando qualquer resíduo de esmalte anterior. 2. Aplique uma camada base para proteger as unhas e garantir melhor aderência do esmalte. 3. Em seguida, aplique uma ou duas camadas do esmalte Impala, de acordo com a intensidade desejada. 4. Finalize com uma camada de top coat para prolongar a duração do esmalte e adicionar brilho extra. Com os Esmaltes Impala, suas unhas estarão sempre lindas e bem cuidadas, dando aquele toque final de elegância e estilo ao seu visual. Kit contem : 05 unidades do Esmalte Impala Transparente Top Pop', 38.45, 38.45, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbka-lqm1f3y9uds58b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22792796721', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998186058', 'Kit Elseve Liso Dos Sonhos AHA + Queratina Vegetal Shampoo 200ml + Condicionador 200ml + Creme Pentear (3 produtos)', 'Kit Contém: -Shampoo Elseve Liso Dos Sonhos AHA + Queratina Vegetal 200ml-Condicionador Elseve Liso Dos Sonhos AHA + Queratina Vegetal 200ml -Creme de Pentear Elseve Liso Dos Sonhos AHA + Queratina Vegetal 250ml Shampoo Elseve Liso Dos Sonhos AHA + Queratina Vegetal 200ml O Shampoo Super Alinhador limpa e fortalece a fibra preparando os fios para um liso de longa duração e com frizz controlado. Condicionador Elseve Liso Dos Sonhos AHA + Queratina Vegetal 200ml O Condicionador Efeito Liquid Hair sela e restaura a superfície da fibra para um liso com efeito liquid hair: Desmaiado, com movimento super fluido e brilho intenso. Creme de Pentear Elseve Liso Dos Sonhos AHA + Queratina Vegetal 250ml O Creme para pentear Exterminador Frizz desembaraça e combate a umidade para um liso com frizz controlado por até 72h, desde a primeira aplicação.', 89.13, 89.13, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rbl0-m62jx6a8jmiy65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23998186058', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792472501', 'Tonalizante Color Affair 3.0 Castanho Escuro', 'O Kit Tonalizante Color Affair Elisafer é composto por 17 tons e não contém amônia em sua composição. Colore os cabelos com uma excelente cobertura dos fios brancos. Possui tecnologia que faz com que os pigmentos contidos no produto venham em tamanho reduzido. O que permite a entrada de maneira mais fácil e em maior quantidade na fibra capilar, tornando a cor mais uniforme e intensa. Principais ativos: Semi Di lino Benefícios: Cores vibrantes e brilho luminoso. Indicado: Cabelos naturais, coloridos, descoloridos, alisados, relaxados ou com escovas progressivas. ​ Modo de uso: Aplicar e deixar agir por 40 minutos. (Vide embalagem interna do produto) Dica: Realize sempre o teste de mecha. PROVA DE TOQUE: Prepare um pouco desse produto como se fosse utilizá-lo, aplique no antebraço ou atrás da orelha e deixe agir por 30 minutos, lave o local e aguarde 24 horas e se nesse período surgir irritação na pele, coceira ou ardência no local ou na sua proximidade, fica provada a hipersensibilidade da pessoa ao produto e portanto não deve ser utilizado.', 49.27, 49.27, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rbkx-lm6hb8g0ajm8c3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23792472501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42931400169', 'Tampa Protetora De Prato Para Microondas 26cm Electrolux', 'Tampa para Micro-ondas Electrolux – Praticidade e Limpeza no Dia a Dia A Tampa para Micro-ondas Electrolux é ideal para aquecer alimentos com mais segurança, higiene e praticidade. Produzida em plástico próprio para uso em micro-ondas, ajuda a evitar respingos de gordura e molho durante o aquecimento, mantendo o interior do aparelho sempre mais limpo. Com design simples e funcional, pode ser utilizada para cobrir pratos e recipientes, auxiliando no aquecimento uniforme dos alimentos e reduzindo a sujeira após o uso. É um acessório original Electrolux, novo, com excelente acabamento e compatível também com micro-ondas de outras marcas, desde que respeitadas as dimensões do produto. Principais Características: • Ideal para tampar alimentos ao aquecer • Evita respingos dentro do micro-ondas • Ajuda a conservar a limpeza do aparelho • Material próprio para micro-ondas • Produto novo e com nota fiscal Especificações: • Marca: Electrolux • Material: Plástico especial • Dimensões: 26,5 x 26,5 x 7 cm • Peso suportado: Não aplicável • Uso indicado: Micro-ondas Electrolux e outras marcas compatíveis', 47.99, 38.9, NULL, 'Home Appliances > Kitchen Appliances > Microwaves', 'https://cf.shopee.com.br/file/br-11134207-820lg-mozuvat0nytib9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402450553%2F42931400169', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21098131495', 'Vassoura Bola CONDOR PELO NATURAL Cerdas Crina Uso Interno Não Risca Chão Porcelanato Teto Com Cabo', 'Vassoura Uso interno REF V-2 Vassoura com um mix de cerdas naturais e cerdas sintéticas macias. Com cabo angulado e ideais para pisos delicados. Garantem a limpeza perfeita sem danificar os pisos de cerâmica, porcelanato, madeira e laminados. Cerdas laterais em 360o, com design perfeito para proteger os móveis e limpar os rodapés durante a limpeza. Cor: Vermelho Largura: 32cm Altura com cabo: 124cm', 75.88, 45.53, NULL, 'Home & Living > Home Care Supplies > Brooms', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9ectjm2y1q1ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F21098131495', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13731884803', 'SANDA Relógio Masculino à Prova D''água Relógio Esportivo Camuflagem Relógio Masculino De Luxo Digital 3099', 'Marca: SANDA Número do modelo: SD2 / 3099 Relógio original SANDA Tipo de projeto: relógio digital LED Características: anti-choque, exibição semanal, à prova d''água, cronômetro, alarme, luminosa, exibição semanal, alarme, cronógrafo, exibição mensal, calendário, indicação de 24 horas Movimento: Quartzo Estilo: moda casual, esportivo, militar, empresarial, luxuoso Selo 100% novo e de alta qualidade 5ATM / 50M à prova d''água (suporta chuveiro de água fria e natação, não opera o relógio debaixo d''água, não suporta água quente); Material da caixa: resina Material da pulseira: borracha Pulseira de borracha de alta qualidade Especificações Diâmetro do mostrador: 50 mm Espessura da caixa: 15 mm Comprimento do relógio: 24,5 cm Largura de banda: 25 mm Incluído no Pacote: 1 x relógio SANDA 1 x manual de instruções', 299.0, 56.0, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/ed26bf07a337668ff7cf1fa2ae2f47d1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F240260535%2F13731884803', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698555494', 'Traqueia Bovina Desidratada Mordedor Petisco 100% Natural para Cães Brupet 5 unidades', 'Petisco Natural BRUPET – Traqueia Bovina Desidratada (05 unidades) Surpreenda seu pet com este irresistível petisco natural, ideal para cães de todos os portes. Uma combinação perfeita que oferece muito mais que diversão: promove a saúde bucal, alivia o estresse e mantém seu cão entretido por horas. A Traqueia Bovina BRUPET é um petisco 100% natural, feito apenas com miúdos desidratados, sem adição de conservantes, aromatizantes ou corantes. Um mimo perfeito para cães de todos os portes e idades, ideal para ser oferecido como recompensa, agrado ou estímulo no dia a dia. Por que escolher um petisco desidratado? A desidratação é um processo natural que remove a umidade do alimento sem a necessidade de aditivos químicos. Isso garante: - Maior durabilidade do produto sem uso de conservantes - Preservação dos nutrientes e sabor original - Textura crocante que auxilia na saúde bucal do pet - Um petisco seguro e saudável para todas as fases da vida - Contribui para a saúde dental do seu pet - A mastigação da Traqueia bovina auxilia na remoção de tártaro e placa bacteriana, promovendo uma limpeza natural dos dentes. - Além disso, fortalece a mandíbula e proporciona alívio do estresse, principalmente para cães que gostam de roer. Características do Produto: - Produto mastigável - Natural e saudável - Sem ingredientes artificiais - Não substitui a alimentação completa Modo de uso: Inicie a oferta com pequenas quantidades por dia e aumente gradativamente, de acordo com a aceitação do seu pet. Deve ser fornecido sob supervisão, sempre como complemento e em momentos de interação ou adestramento. Composição: Miúdos desidratados. E nada mais! Informações Importantes: Contraindicado para alimentação de gatos Uso proibido na alimentação de ruminantes Após aberto, consumir em até 7 dias Manter em local seco, fresco e arejado A variação de cor é natural e não compromete a qualidade do produto', 39.8, 39.8, NULL, 'Pets > Pet Food > Dog Treats', 'https://cf.shopee.com.br/file/br-11134207-7r98o-maenrk60sc8p17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F288347041%2F23698555494', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897420028', 'Shampoo Wella Professionals Fusion 1L', 'Shampoo para cabelos danificados. Wella Professionals Fusion Shampoo auxilia na reparação dos danos para devolver a força e a maciez dos fios extremamente fragilizados. Wella Professionals Fusion Shampoo possui fórmula suave que realiza uma limpeza saudável, que não compromete a saúde da fibra capilar. Além disso, sua fragrância combina nove aromas que remetem à sofisticação com seus toques de madeira florestal e notas de base quentes, como cedro e sândalo. Ações Fusion Silksteel: Fusão de aminoácidos da seda e lipídios micronizados que penetram no interior do córtex para recuperar a condição ideal do fio e deixar o cabelo até 95% mais resistente. Tecnologia EDD: Age na camada externa do fio para remover as impurezas com sua ação antioxidante. Modo de uso: Aplique o shampoo sobre a raiz do cabelo molhado e massageie até formar espuma. Puxe o produto para a extensão e pontas. Enxágue. Se necessário, repita o procedimento. #html-body [data-pb-style="646BA66211F72"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA66211F87"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 357.9, 357.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rbkg-lmf4rwbws7ph9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F21897420028', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492947603', 'Rolo Espaguete Liso 100 Metros', 'Código: DM907002 | DM907003 | DM907004 | DM907005 | DM907006 | DM907007 | DM907008 | DM907009 | DM907010 | DM907011 | DM907012 Descrição: Rolo de Espaguete Liso Fabricado em material PVC, o que facilita a introdução de chicotes. Aplicações automobilísticas toda linha de chicotes, partes eletrônicas, sonorização, ar condicionado, preparações em geral. A utilização do espaguete valoriza o trabalho e oferecer ao cliente um acabamento perfeito, sem fio aparentes ou emendas a mostra, sem fita isolante e sem abraçadeiras plásticas Produto fornecido em embalagens com rolo de 100 metros. (Valor referente ao rolo de 100m) Marca: DM Auto Peças ***ATENÇÃO*** COMPARE AS NUMERAÇÕES E DESCRIÇÃO DO ANÚNCIO COM A SUA PEÇA OU INFORMAÇÕES. EM NOSSO ANÚNCIO CONSTAM A MAIORIA DOS NÚMEROS DE CONVERSÃO PARA COMPARAR. CASO NÃO TENHA A NUMERAÇÃO QUE PROCURA, FAÇA UM PERGUNTA PARA QUE POSSAMOS LOCALIZAR A PEÇA EQUIVALENTE. EQUIPE DL AUTO PARTS.', 54.7, 54.7, NULL, 'Home & Living > Home Organizers > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lz8zfsba3291dd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F662883696%2F23492947603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
