INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46260740651', 'Painel Digital LED com Velocímetro para Titan 150 (até 2008) CG 150 / Fan 150 (2009 a 2013) Moderno', '?️ Painel Digital LED para Honda TITAN150 / CG150 / FAN150 Atualize sua motocicleta com um painel de instrumentos digital moderno e eficiente, compatível com os modelos Honda TITAN 150, CG 150 e FAN 150 nacionais. Com display LED de fácil visualização, oferece todas as informações essenciais em um só lugar: velocímetro, odômetro e tacômetro integrados. ⚙️ Especificações Técnicas Compatibilidade: Honda TITAN150 / CG150 / FAN150 (modelos brasileiros) Funções: Velocímetro, odômetro, tacômetro Display: LED digital de alta visibilidade (cor da luz: verde) Velocidade Máxima Exibida: Até 199 km/h Quilometragem ODO (Total): Até 99.999 km Quilometragem TRIP (Parcial): Até 999,9 km Unidades: Alternância entre sistema métrico e imperial Botão: Alterna entre ODO e TRIP, com função de reset no TRIP Material: ABS resistente Cor do Produto: Preto ? Fiação e Conexões Verde: Polo negativo Preto: Polo positivo Laranja: Seta esquerda Amarelo com branco: Medidor de combustível Azul claro: Seta direita Azul escuro: Farol alto Verde com branco: Neutro Azul com branco: Fio de velocidade (redondo) ? Conteúdo da Embalagem 1x Painel Velocímetro Digital LED para Moto *IMAGENS MERAMENTE ILUSTRATIVAS* *ITENS A PRONTA ENTREGA* *AS CORES NAS FOTOS PODEM VARIAR DE ACORDO COM A RESOLUÇÃO E BRILHO DA SUA TELA*', 299.99, 159.99, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Panel and Speedometer', 'https://cf.shopee.com.br/file/sg-11134201-822wl-modnxqobqgb2b9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F791248992%2F46260740651', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699380802', 'Luva Futebol De Campo Poker Training Basic Junior - Infantil', 'Luva Futebol de Campo Poker Training Basic Junior - Infantil Luva Futebol de Campo Poker Training Basic Junior - Infantil Equipe seu pequeno goleiro com a Luva Campo Infantil Poker Training Basic Junior, a escolha ideal para quem está começando no mundo do futebol. Esta luva unissex é perfeita para crianças que jogam em diferentes tipos de terreno, como grama natural, grama sintética, e piso abrasivo. O fechamento com tira autocolante e elástico no punho oferece um ajuste seguro, garantindo conforto e estabilidade durante o jogo. O corte com costuras internas proporciona um ajuste justo e melhor contato com a bola, essencial para defesas precisas. Com tecnologias avançadas como o Amateur Resistance Grip, que utiliza látex sintético para maior resistência e durabilidade, e a Palma 3.0 com espessura de 3.0mm, esta luva oferece excelente amortecimento. Além disso, a Espuma 2.0 com 2.0mm de espessura assegura conforto adicional. Classificada como luva de training, é ideal para goleiros iniciantes que precisam de um equipamento confiável para melhorar suas habilidades. A composição do dorso é de 100% poliéster e da palma é de 100% algodão, garantindo leveza e durabilidade. Especificações do Produto Nome: Luva Campo Infantil Poker Training Basic Junior Gênero: Unissex/Infantil Indicado para: Goleiro Fechamento: Tira autocolante, possui elástico no punho Indicações de uso: Grama natural, Grama sintética, e Piso/Abrasivo Detalhes: Corte com costuras internas que proporcionam um ajuste muito mais justo e melhor contato com a bola Tecnologias: Amateur Resistance Grip, Palma 3.0, Espuma 2.0 Classificação de Luva: Training: Modelos Training utilizados por goleiros iniciantes Composição: Manta dorso: 100% Poliéster. Manta Palma: 100% Algodão Contém: 1 Par', 79.9, 79.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-7rdxq-m01lgsi3nnc7fb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F19699380802', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
