INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093397437', 'Velas de Ignição Comet 250 / Ninja 300 / Versys 300 Ngk Cr8e', 'Velas de Ignição NGK A principal função da vela de ignição é conduzir a corrente elétrica gerada no transformador até a câmara de combustão, e transformá-la em centelha elétrica de alta tensão, o que dará início a combustão, ou seja, é um item responsável pela correta queima da mistura ar/combustível. Conteúdo da Embalagem: 02 Velas de Ignição NGK Compatível com: DAFRA Maxsym 400i / 33,3cv Gasolina Desde 2015 Citycom 300i / 23cv Gasolina 2011 a 2016 Citycom S 300i / ( 28cv ) Gasolina Desde 2016 Next 300 / (27cv) Gasolina Desde 2018 Next 250 / (25cv) Gasolina 2012 a 2017 KASINSKI Comet 650R Gasolina Desde 2007 Comet GT 650R Gasolina Desde 2012 Mirage Power Gasolina Desde 2007 CR8E Comet GT-R Gasolina Desde 2009 CR8E Comet Phase 2 Gasolina Desde 2005 Mirage 250 Gasolina KAWASAKI Ninja 300 / 39cv Gasolina Desde 2013 Versys-X 300 ( 40cv ) Gasolina Desde 2018 Versys-X 300 Tourer ( 40cv ) Gasolina Desde 2018 D-Tracker X / 22cv Gasolina Desde 2010 KLX 250 Gasolina KX 250F (KX250TE000001->) Gasolina 2006 a 2008 Ninja 250R Gasolina Desde 2008 SUZUKI Burgman 650 / ( 55cv ) Gasolina Desde 2006 GSX 650 F / GSX (86cv) Gasolina Desde 2008 V-Strom 650 ( 68cv ) Gasolina 2008 a 2009 DR 400E Gasolina DR-Z 400E Gasolina GSR 125 / Carburador ( 10,8cv ) Gasolina 2013 a 2016 GSR 125S Gasolina 2013 a 2016 Intruder 125 / OHC Gasolina Desde 2007 Intruder 125 Cargo Gasolina Desde 2007 YES -EN 125 / Cargo Gasolina Desde 08/2004 TRIUMPH Grizzly / Raptor / 700 (Quadriciclo) Gasolina Desde 2007 YFM 700R (Quadriciclo) Gasolina Desde 2007 YAMAHA WR 450F Gasolina 2003 a 2008 WR 450F Gasolina 2014 WR 450F Gasolina Desde 2018 YFZ 450 (Quadriciclo) Gasolina Desde 2007 YZ 450F Gasolina 2005 YZ 450F Gasolina Desde 2003 WR 426F Gasolina