INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693721923', 'Climatizador de Ar Cadence CompactAr 8,4L', 'O Climatizador CompactAr Cadence é um aparelho compacto, desmontável e fácil de transportar, ideal para uso doméstico. Ele oferece 3 funções em um só equipamento: climatizar, ventilar e umidificar, com baixo consumo de energia (60W). Conta com 3 velocidades, função oscilante para melhor distribuição do ar e sistema de resfriamento natural por evaporação (pad cooling), que pode ser potencializado com gelo no reservatório. Possui filtro de ar, tanque de 8,4L para uso prolongado e base com rodinhas e alça para facilitar o deslocamento. Características: Modelo: CLI530 3 em 1: Climatiza, ventila e umidifica 3 Velocidades Base com rodinhas Alça para transporte Tanque de água removível Capacidade do tanque: 8,4 litros Potência: 60W Função oscilar Resfriamento natural por evaporação Dimensões: Altura: 60 cm Largura: 23 cm Profundidade: 25 cm Peso: 4,64 kg Garantia do fornecedor de 12 meses', 499.9, 399.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rcet-m6cljxhh6imia1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F22693721923', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192833307', 'Chicote do Painel Pollak Mercedes 6 Vias Fêmea Macho Mini Fit - R7 - ETE5826/06', 'Chicote automotivo: a solução para problemas elétricos O chicote automotivo é um conjunto de cabos elétricos que conectam os componentes elétricos do seu carro. Ele é responsável por transmitir energia e informações entre esses componentes, garantindo o funcionamento correto do seu veículo. Se o seu chicote automotivo estiver danificado, ele pode causar uma série de problemas elétricos. Por isso, é importante manter o chicote automotivo em boas condições. Aqui estão alguns dos benefícios de manter o chicote automotivo em boas condições: Melhora o desempenho do veículo Aumenta a segurança Reduz os custos de manutenção Se você está procurando um chicote automotivo de alta qualidade, aqui é a melhor opção. Oferecemos uma ampla variedade de chicotes automotivos para vários tipos de carros e caminhões. Veículos Mercedes Benz Pollak Painel', 54.43, 54.43, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rbnj-lpsgi3c0q6lab8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1005342012%2F23192833307', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
