INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993239954', 'Mochila Motoboy Impermeável Bag para Fazer Entregas Delivery com Isopor', 'A mochila bag térmica é ideal para entregas de alimentos e bebidas, mantendo a temperatura e garantindo praticidade no transporte. Perfeita para motoboys, iFood, 99Food, restaurantes e lanchonetes. Fabricada em nylon reforçado e com isopor interno, oferece resistência, durabilidade e excelente conservação térmica no dia a dia. Características do produto: Capacidade de 45 litros Parte interna com isopor branco térmico Material em nylon reforçado e impermeável Capacidade para até 7 pizzas Bolsos laterais para até 4 refrigerantes Bolso superior para garrafa tipo vinho Compartimento com zíper para máquina de cartão Frente com visor plástico para logomarca Fechamento com zíper resistente Especificações: Altura 35 cm Largura 45 cm Profundidade 42 cm Itens inclusos: 1 Mochila bag térmica 45L com isopor interno', 140.09, 140.09, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Backpacks', 'https://cf.shopee.com.br/file/sg-11134201-81zvr-mn26u61s6uip38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F374241455%2F22993239954', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
