INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399309055', 'Chumbinho Strike Diabolo - Calibre 4,5 Mm - Com 500 Unid -', 'O chumbinho Strike Diabolo de calibre 4,5 mm da Technogun possui cabeça arredondada, é muito estável, preciso e veloz. Embalagem com 500 unidades. Os chumbinhos da Technogun são formados em alta pressão por um sistema único e patenteado pela Pesca Brasil, propiciando um balanceamento centrífugo uniforme e preciso. Os chumbinhos são compostos por uma liga de chumbo, estanho e outros metais, o que propicia uma dureza adequada para as mais exigentes armas. O chumbinho Strike Diabolo de calibre 4,5 mm da Technogun possui cabeça arredondada, é muito estável, preciso e veloz. Especificações Técnicas Marca: Technogun Modelo: Strike Diabolo Calibre: 4,5 mm Peso: 0,55 g Conteúdo: embalagem com 500 unidades', 62.16, 62.16, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rdwt-ly74it9t56p464', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078949207%2F18399309055', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
