INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42903484611', 'Kit Layering - Edição 2: Lady Money 15ml + Gabriela 15ml | Perfumes Femininos Amakha Paris', 'Kit Layering 2 - Lady Money 15ml + Gabriela 15ml | Perfumes Femininos Amakha Paris 💖 Duas fragrâncias poderosas em um único kit, para você combinar, ousar e criar o seu próprio aroma exclusivo! ✨ Lady Money (Inspirado em Lady Million) Elegância e sofisticação em cada borrifada! Um perfume floral frutal que exala feminilidade e glamour. Notas Olfativas: • Topo: Framboesa, Néroli, Limão de Amalfi • Corpo: Jasmim, Flor de Laranjeira Africana, Gardênia • Fundo: Mel Branco, Patchouli, Âmbar ✔ Ideal para dia e noite ✔ Ocasiões elegantes ou sociais ✔ Perfeito para mulheres comunicativas e detalhistas. ✨ Gabriela (Inspirado em Gabriela Sabatini) Força, determinação e confiança com um toque sofisticado! Um perfume floral amadeirado envolvente e marcante. Notas Olfativas: • Topo: Aldeídos, Notas Frutadas, Bergamota, Mandarina, Limão • Corpo: Jasmim, Madressilva, Flor de Laranjeira, Heliotrópio, Lírio-do-Vale, Rosa • Fundo: Baunilha, Âmbar, Fava Tonka, Sândalo, Almíscar, Musgo de Carvalho, Patchouli ✔ Ideal para a noite ✔ Ocasiões sociais ✔ Para mulheres comunicativas e confiantes. 🔹 Como usar: • Separado: Aplique cada perfume em suas áreas preferidas do corpo. • Layering: Use Lady Money como base e sobreponha Gabriela em pontos estratégicos; o calor da pele une as notas e cria um perfume único e sofisticado. 🎁 Kit contém: 1 Lady Money 15ml - Feminino 1 Gabriela 15ml - Feminino', 100.0, 65.0, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7ravd-maoljcjwcy1u02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1454161052%2F42903484611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
