INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21640744673', 'Gel Antirressecamento Dermachem Rosa Mosqueta 100g', 'Descrição: O Gel Antirressecamento Dermachem Rosa Mosqueta e descubra uma pele hidratada, nutrida e macia. Sua fórmula única uniformiza a pele e resgata sua vitalidade. Potencialize os resultados com a linha completa Dermachem Laboratory e transforme sua rotina de cuidados com a pele. MODO DE USAR: 1 - Aplicar com movimentos circulares na pele limpa, duas vezes ao dia, uma de manhã e outra à noite. Não é necessário retirar. USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 100g. Composição: Água, Glicerol, Edetato Dissódico, Hidróxido de Sódio, Corante Vermelho de Azorrubina, Pantenol, Butil-Hidroxitolueno, Hialuronato de Sódio, Decametilciclopentasiloxano, PEG-400, Lactato de Amônio, Oléo do Fruto de Rosa- Mosqueta, Carbômer, Perfume, Colágeno Hidrolisado, Fenoxietanol, Etilhexilglicerina. #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 16.99, 16.99, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rdwx-m0t3cuyd4ghwa7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F21640744673', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
