INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23992539554', 'FIltro Ar Condicionado HOGGAR 2010/2014 - 37178 - AKX35157', 'FIltro Ar Condicionado HOGGAR 2010/2014 (X-Line / XR) - Motor 1.4 16v Flex /(Scapade) - 1.6 16v Flex - (Mecânico) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 30.87, 30.87, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-823ox-mok2uadzrfv365', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23992539554', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698000395', 'Tensor Correia Ar condicionado FIESTA 1999/2007 - 45743 - VT8134', 'Tensor Correia Ar condicionado FIESTA 1999/2007 Motor 1.0/1.6 8v - (72 x 52,8 x 25) Tensor correia alternador: Aplica-se na parte de fora do motor. Sua função é aplicar carga/pressão constante na correia, com a finalidade de evitar que a mesma se solte do sistema de polias, compensar eventuais folgas ou tensões excessivas que possam prejudicar o sincronismo do motor e o funcionamento dos acessórios do veículo.', 173.58, 173.58, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbk1-lmqjpzs1jo40e4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23698000395', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998364342', 'Par Suporte Barra Tensora Morcego Celta 2012 Original Cofap', 'PAR SUPORTE BARRA TENSORA ORIGINAL COFAP Conteúdo: 01 Suporte '''' Morceguinho '''' da Barra tensora Dianteira - Lado Direito 01 Suporte '''' Morceguinho '''' da Barra tensora Dianteira - Lado Esquerdo Original COFAP Aplicação: Prisma todos modelos ( exceto New Prisma ) Celta todos modelos Corsa/Classic Todos Modelos (Exceto Frente Montana) Qualidade: PRODUTO NOVO ORIGINAL VALOR REFERENTE AO KIT CONTENDO 02 PEÇAS STC04127M COFAP STC04126M COFAP Garantia de 90 Dias mediante apresentação do certificado de garantia. Imagens meramente ilustrativas. Instalação deve ser realizada por um profissional especializado. Não nos responsabilizamos por má instalação, uso inadequado do produto ou adaptações que não são compatíveis com a aplicação correta do produto segundo o fornecedor.', 162.8, 162.8, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m86isgcuu60ha9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1463823458%2F23998364342', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098025928', 'Fechadura Banheiro Taco Golf Inox 823010 Stam', 'A Fechadura Stam Taco Golf Inox 823010 é ideal para portas de banheiro, oferecendo segurança, suavidade no manuseio e design moderno. Possui acabamento em inox, maçaneta móvel ergonômica e padrão de instalação compatível com a maioria das portas residenciais. Detalhes do Produto: Distância de broca: 40 mm Maçaneta móvel Acabamento em inox Indicado para portas de banheiro', 303.9, 110.9, NULL, 'Home & Living > Safety & Security > Door Hardware & Locks', 'https://cf.shopee.com.br/file/sg-11134201-7rd6o-lwd7tz5i8hntab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F965617276%2F23098025928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
