INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259448619', 'Tirinhas de Frango Perdigão', 'As tirinhas de frango da Perdigão são empanados feitos com carne de frango, cortados em um formato prático de tirinhas. Elas são perfeitas para petiscar ou como acompanhamento em suas refeições, trazendo praticidade e sabor para o seu dia a dia. Experimente as tirinhas de frango Perdigão e desfrute de um petisco delicioso e fácil de preparar!', 11.99, 11.99, NULL, 'Food & Beverages > Fresh & Frozen Food > Frozen Processed Food', 'https://cf.shopee.com.br/file/sg-11134201-825aj-mqneku3x3hfx9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58259448619', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493532314', 'Reparo Bico Injetor Vw Golf 2001 a 2008 - 187857 - 1249', 'Reparo Bico Injetor Vw Golf 2001 a 2008 187857 1249 1.6 8v Gasolina/Flex - (Multi Point) (Sistema Bosch/Rochester) (4 Ponteiras + 4 Filtros + 8 O''rings) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 43.02, 43.02, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7reno-m2f1hw53hsdm63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22493532314', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497029942', 'Tubo Água MERIVA 2003/2012 - 31739 - VC427', 'Tubo Água MERIVA 2003/2012 Motor 1.8 8v Gasolina/Flex - (Tubo do Fluxo D''Água do Motor) O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 45.49, 45.49, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rauk-mb6tb5wjyezm86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22497029942', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209469874', 'Chamyto Big Leite Fermentado', 'Chamyto Big é um leite fermentado delicioso e nutritivo, ideal para o lanche da tarde ou para complementar a alimentação das crianças. Cada embalagem contém 6 unidades de 120g, perfeito para levar na escola ou para um piquenique. * Contém lactose * Não contém glúten * Aromatizante natural * Sem corantes', 12.99, 12.99, NULL, 'Food & Beverages > Beverages > Dessert Drink', 'https://cf.shopee.com.br/file/sg-11134201-8258s-mqnelemvzima7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58209469874', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209464617', 'Desodorante Antitranspirante Roll-On Dove Original', 'O Desodorante Antitranspirante Roll-On Dove Original oferece 48 horas de proteção eficaz contra o suor e o mau odor, mantendo suas axilas frescas e protegidas. Sua fórmula contém ¼ de creme hidratante com óleo protetor, contribuindo para a hidratação diária da pele, deixando as axilas macias, suaves e ajudando a reduzir a irritação causada pela depilação. Dermatologicamente testado e sem álcool etílico.', 14.79, 14.79, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-825a9-mqnektqcffgvb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555057%2F58209464617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
