INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18097706845', 'Interruptor Cebolao Radiador DUCATO 2000/2005 - 21656 - 7259297', 'Interruptor Cebolao Radiador DUCATO 2000/2005 MOTOR 2.8 8V TURBO DIESEL (C/ACD) (92°/97ºC) No trânsito é importante o acionamento da ventoinha do radiador. A peça responsável por isso é o Interruptor Térmico. São comutadores (Liga-Desliga) que acionam diversos produtos no sistema de arrefecimento em função da temperatura. Localizado no radiador, aciona a ventoinha quando a temperatura ultrapassa a temperatura ideal de trabalho, evitando assim o superaquecimento do motor.', 107.87, 107.87, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6h-lujhthilgsgt0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18097706845', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
