INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899336341', 'Yves Saint Laurent Y Perfume Masculino Eau de Parfum', 'Y Eau De Parfum é o retrato do homem totalmente realizado. Capaz de superar qualquer desafio, ele nunca considera nada como garantido e insistentemente continua a seguir o caminho que almejou. Ousado, sensual, determinado, carismático, e sempre pronto para enfrentar qualquer desafio, Lenny Kravitz é a personificação dos valores Y. Nesta nova campanha, Kravitz compartilha conosco sua própria história. Naquele momento em que ele perguntou a si mesmo e ao mundo', 899.99, 764.99, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m44k5mm5lanpd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F602117686%2F18899336341', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45903542040', 'Sache Chá Gengibre 13g - CHAMEL', 'O Chá de Gengibre carrega a força de uma raiz ancestral, presente em culturas ao redor do mundo há séculos. Seu sabor marcante e levemente picante aquece os sentidos, trazendo uma sensação de energia, vigor e bem-estar. É a escolha perfeita para quem busca uma infusão que desperta, revigora e acompanha a rotina com calor e vitalidade. Benefícios: ✅ Sabor intenso com toque picante característico ✅ Sensação de energia e aquecimento do corpo ✅ Aroma estimulante e envolvente ✅ Ideal para momentos de cansaço ou para começar o dia ✅ Ótima opção para dias frios ou para uma pausa revigorante ✅ Pode ser consumido sozinho ou combinado com outras ervas Ficha Técnica: ✅ Produto: Chá de Gengibre ✅ Indicação: Energia, vitalidade, vigor e bem-estar ✅ Modo de preparo: Infusão em água quente ✅ Consumo ideal: Pela manhã, antes de atividades ou em momentos que pedem estímulo', 10.29, 10.29, NULL, 'Food & Beverages > Beverages > Tea & Tea Bags', 'https://cf.shopee.com.br/file/sg-11134201-81zv7-mily5mwa9amebb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2F45903542040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498905449', 'Cama Box com Colchão de Espuma D33 Ortobom Airtech 100 Solteiro 88cm', 'Buscando um colchão com conforto firme e suporte robusto? Nosso colchão de espuma D33 é ideal para quem precisa de um suporte consistente para o corpo. Com capacidade para suportar até 120 kg por pessoa, ele oferece a firmeza necessária para uma noite de sono reparadora, mantendo a coluna alinhada e reduzindo pontos de pressão. O colchão misto com a tecnologia do EPS oferece estabilidade estrutural para o seu colchão, proporcionando uma melhor sustentação para a camada de conforto em espuma, oferecendo noites de descanso mais tranquilas. Ortoluc: Uma linha exclusiva da Ortobom e Lucas Home, proporcionando uma experiência de sono única. Complementando este colchão, a base box é feita de madeira tratada e revestida, suportando até 150 Kg por pessoa. Ela não só eleva seu colchão a uma altura ideal para fácil acesso, mas também estabiliza seu sono com uma fundação sólida e confiável. Esta combinação não apenas maximiza seu conforto, mas também a funcionalidade do seu espaço de descanso. Especificações Técnicas do Colchão: - Proteções: Antiácaro, Antialérgico, Antifungo, Antimofo; - Revestimento: Em malha (Conforto térmico); - Tipo: Espuma D33; - Sistema One Face: Tecnologia No Turn(permite girar o colchão); - EPS Poliestireno Expansível(Suporte adicional): Possui; - Tipo de conforto: Firme(Ortopédico); - Peso máximo recomendado: até 120Kg (por pessoa); - Garantia: 12 meses; - Dimensões (larg. x comp. x alt.) 88x188x18cm. Especificações Técnicas Base Box: - Marca: Lucas Colchões; - Material: Madeira tratada; - Peso máximo recomendado: até 150 Kg (por pessoa); - Altura da base: 27cm; - Altura dos pés: 12cm; - Revestimento: Tecido Sintético; - Garantia: 3 meses; - Dimensões (larg. x comp. x alt.) Solteiro: 88x188x39cm; Importante: as cores podem variar conforme a tela; Não oferecemos montagem; recomendamos profissionais qualificados. Confira as dimensões para transporte em elevadores e passagens. Não transportamos por meios especiais. Por se tratar de um produto de uso íntimo e pessoal, só aceitaremos devoluções por arrependimento apenas se a embalagem do produto não for violada.', 1417.7, 918.07, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-820me-mn4k9qgxwhz820', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208859337%2F22498905449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393104752', 'Cama Box com Colchão de Espuma D45 Ortobom Iso 150 Casal 138cm', 'Está buscando por um colchão que te auxilie com sua saúde e de excelente custo-benefício? O Iso 150 é a escolha ideal.! Sua base possui a leve e tecnológica placa de poliestireno expandido, que oferece perfeito suporte a camada de conforto em espuma D45 Pró Aditivada de Alta Performance, ideal para pessoas com até 120 quilos. O tampo é bordado em Matelassê, que entrega uma camada extra de conforto. Seu revestimento é em Viscopoli com tratamento antialérgico e antiácaro. Proporcionando conforto extra firme, o que traz firmeza suficiente para preservar a sua coluna durante o sono sem comprometer o seu conforto. Complementando este colchão, a base box é feita de madeira tratada e revestida, suportando até 150 Kg por pessoa. Ela não só eleva seu colchão a uma altura ideal para fácil acesso, mas também estabiliza seu sono com uma fundação sólida e confiável. Esta combinação não apenas maximiza seu conforto, mas também a funcionalidade do seu espaço de descanso. Especificações Técnicas do Colchão: - Marca: Ortobom; - Proteções: Antiácaro, Antialérgico, Antifungo, Antimofo; - Acabamento: Viscopoli e bordado em matelassê; - Matéria prima: Espuma; - Sistema One Face: Tecnologia No Turn (permite girar o colchão); - Densidade: D45; - EPS Poliestireno Expansível (Suporte adicional): Possui; - Tipo de conforto: Extra Firme; - Peso máximo recomendado: até 120Kg (por pessoa); - Garantia: 12 meses; - Dimensões do produto (larg. x comp. x alt.): 138x188x18cm. Especificações Técnicas Base Box: - Marca: Lucas Colchões; - Material: Madeira tratada; - Peso máximo recomendado: até 150 Kg (por pessoa); - Altura da base: 27cm; - Altura dos pés: 12cm; - Revestimento: Sintético; - Garantia: 3 meses; - Dimensões (larg. x comp. x alt.) Casal: 138x188x35cm. Importante: As cores podem variar conforme a tela; Não oferecemos montagem; recomendamos profissionais qualificados. Confira as dimensões para transporte em elevadores e passagens. Não transportamos por meios especiais. Por se tratar de um produto de uso íntimo e pessoal, só aceitaremos devoluções por arrependimento apenas se a embalagem do produto não for violada.', 1697.9, 1416.7, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-821dj-mh9rswth12j3f0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208859337%2F22393104752', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
