INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293107715', 'Kit 2 Pneu General by Continental Aro 15 195/55r15 85v Fr Al', 'Aplicação Aplicação ALFA ROMEO 145 155 CITROEN SAXO XANTIA XSARA ZX FIAT BRAVA TEMPRA FORD FIESTA KA KA SEDAN HONDA CIVIC HYUNDAI MATRIX KIA RIO MAZDA PROTEGE MERCEDES BENZ A 160 A 190 PEUGEOT 206 306 VOLKSWAGEN FOX GOL PARATI POLO SAVEIRO SPACEFOX VOYAGE VOLVO S40 V40 Conteúdo Da Embalagem 2 Pneu 195/55r15 Largura do Pneu 195 Perfil 55 Volkswagen Spacefox Fox Gol Parati Polo Saveiro Voyage Alfa Romeo 145 Citroen Saxo Xantia Xsara Zx Fiat Tempra Ford Fiesta Ka Honda Civic Kia Rio Mazda Protege Observação Letras Pretas Peugeot Peugeot 206 Peugeot 306 Tipo de Veículo para Carros Toyota Matrix Volvo S40 V40 Marca A General Tire foi fundada em 1973 e oferece pneus robustos e duráveis, aliás, esta é uma das principais características dos pneus General com a sua herança americana. Ao longo destes quase 100 anos oferece produtos nos quais você pode confiar para as pequenas aventuras da vida cotidiana ou para momentos em que você está explorando territórios desconhecidos. Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de garantia: 5 Anos a partir da emissão da nota fiscal por defeito de fabricação. Valor do kit. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa - A quantidade de sulcos pode variar de acordo com a medida do pneu, a imagem ilustra apenas o desenho da banda de rodagem. Alguns carros podem sair de fábrica com mais de uma medida de pneu. Por favor, verifique sempre no veículo qual é a medida exata Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 Indice Velocidade V (240km/h) Indice Carga 85 (515 Kg) Código do Fabricante 15549030000 Aro 15 Garantia 60 meses Câmara de Ar Sem Treadwear 420 Tração A Temperatura A Tipo de Desenho Assimétrico', 946.9, 843.37, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-8260q-mj7bqt24chl342', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1197031273%2F22293107715', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493121089', 'Puzzle 1000 peças Central Park Nova York - Imp. Castorland', 'Os quebra-cabeças Castorland são fabricados na Polônia pela Castor, uma empresa reconhecida no mercado há mais de 30 anos. São muito populares e apreciados por sua excelente qualidade em mais de 50 países em todo o mundo. A Castor sempre se destacou pela rigorosa seleção e processamento gráfico de seu estoque de imagens, bem como pela extraordinária riqueza de detalhes que quase salta aos olhos em cada peça. Você achará a coleção de quebra-cabeças Castorland inspiradora. Pensando de diversificação, a Grow traz para o Brasil uma coleção de Puzzles da marca CASTORLAND para os apaixonados por cada quebra-cabeças. Mais que um passatempo divertido, os quebra-cabeças desenvolvem o raciocínio, relaxam e se transformam num autêntico hobby. Puzzle Importado Fabricante: Castorland Condição: NOVO/ LACRADO Quantidade de peças: 1000 peças Dimensões do puzzle montado: 68,0 47,0 cm Dimensões da embalagem: 35,0 25,0 5,0 cm', 199.99, 199.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rd57-lx9vr8za028c5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F23493121089', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
