INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093521593', 'Perfurador de Solo à Gasolina sem Broca Vonder 52CC PSV520', 'Ref. Fornecedor: 6837520000 Marca: Vonder Conteúdo Embalagem: 1 Perfurador de solo. Acompanha: 1 kit de ferramentas para manutenção (1 chave de fenda, 1 chave fixa, 1 chave combinada para vela x ponta phillips e 3 chaves allen) e 1 reservatório para mistura da gasolina e do óleo 2 tempos. Aplicações e dicas de uso: Equipamento profissional indicado para área florestal e agropecuária. Ideal para perfuração de solo nos trabalhos de colocação de cercas e estacas, para plantio de mudas de árvores e na coleta de materiais para análise de solo. Indicado para solos isentos de pedras, raízes, metais, entre outros. Destaques e diferenciais: Possui sistema de partida de fácil acionamento (Easy-start), proporcionando maior suavidade no acionamento do retrátil ao dar a partida. Em operação, oferece maior rendimento com o menor esforço do operador. Características Técnicas: Linha: Profissional Tipo de motor a combustão: Monocilindro - 2 tempos, refrigerado a ar Potência do motor a gasolina: 2,0 cv (1,4 kw) - 52 cm³ (cc) Torque do motor: 2,1 N·m Rotação mínima do motor: 3200 /min Rotação máxima do motor (rpm): 7500 /min Tipo / medida do encaixe da broca: Por pino - 20 mm Medida do pino trava da broca: 8 mm x 45 mm Diâmetro da broca do perfurador: 60 mm a 300 mm Altura da broca: 800 mm Direção de rotação: Sentido horário Capacidade do tanque de combustível: 1 L Sistema de partida do motor: Manual retrátil Combustível: Gasolina comum com óleo 2 tempos Tipo de ignição: CDI Tipo do carburador: Com diafragma e regulagem Nível de ruído (7 metros de distância): 110 dB(A) Cor do perfurador: Preto e amarelo', 1328.9, 1328.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-1113420