INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793135911', 'VIOLAO GIANNINI N14 BK+CAPA SIMP CLAS+3 PALETAS', 'Suporte ao aprendizado de violão. O Start chega para complementar a já conhecida linha estudante GCX15. Além disso, o violão também é excelente para quem já toca e quer um instrumento leve para deixar no carro, levar para cima e para baixo, animar as rodas de amigos, tocar suas músicas em casa, ou qualquer lugar que você vá. Modelo: Violão Nylon Tampo: Linden Faixa e fundo: Linden Tarraxas: Pino grosso niqueladas Braço: Catalpa Escala: Maple Escurecido Trastes: 19 em Alpaca Acabamento: Verniz brilhante Cor: Preto. Itens inclusos : 1 Violão 1 Capa 3 Palhetas', 531.0, 531.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/br-11134207-81zts-ml3udezkp4oze3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F22793135911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41659468454', 'Relógio Smartwatch Condor Rose Gold Digital 1 Ano Garantia', 'Procurando um presente perfeito? Encontrou! Dê o moderno Condor Smartwatch de presente para você mesmo, ou para alguém querido! *1 ANO DE GARANTIA CONDOR - Produto com NOTA FISCAL* O novo Condor Smartwatch oferece a melhor combinação de design moderno e tecnologia atual! Tem um processador de alto desempenho, caixa durável e sofisticada, e uma incrível pulseira de silicone que garante total conforto no seu pulso e que podem ser trocadas de acordo com a sua vontade. O Condor Smartwatch vem com inúmeras funções inteligentes para facilitar o seu dia a dia. Ideal para práticas esportivas ou para quem precisa monitorar informações importantes como medidor de distância, contador de passos ou frequência cardíaca, por exemplo. O Condor Smartwatch ajuda até a localizar o seu celular e tirar aquela selfie! Baixe o APP Condor Smart no Google Play ou App Store e habilite todas as funções como notificações de redes sociais e e-mails. Atuamos somente com produtos 100% ORIGINAIS! Leve em um especialista de sua região para comprovar. Ficha Técnica PROVA D''ÁGUA: Resistente a água MATERIAL DO VIDRO: Cristal mineral resistente a riscos MAQUINÁRIO: Digital MATERIAL DO RELÓGIO: Aço inoxidável. MOSTRADOR: Touch COR DO FUNDO: Preto Medidas TAMANHO DA CAIXA (mostrador): 3,9 cm (39 mm) ESPESSURA DA CAIXA (mostrador): 1,1 cm (11 mm) LARGURA DA PULSEIRA: 1,9 cm (19 mm) CIRCUNFERÊNCIA DA PULSEIRA: 22 cm Todas as funções do relógio estão presentes na imagem 8 do anúncio :) Acompanha Relógio Condor, carregador, caixa original Condor, manual de instruções em português, certificado de garantia e nota fiscal. Nossos produtos são todos tratados com máximo cuidado, profissionalismo e atenção. Enviamos o seu relógio em uma embalagem reforçada, protegida por dentro e por fora. COMPRE COM SEGURANÇA Revendedor autorizado Condor', 399.87, 299.9, NULL, 'Watches > Women Watches', 'https://cf.shopee.com.br/file/sg-11134201-7rdw8-mci7tj78js0j64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463371489%2F41659468454', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
