INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898899088', 'Etiqueta termocolante Branca com 20 unidades Pimaco', 'As etiquetas termocolantes brancas da Pimaco são ideais para identificar roupas e tecidos de forma simples, prática e duradoura. Sua aplicação é feita com o calor do ferro de passar, garantindo fixação firme e resistência às lavagens, sem comprometer o tecido. O pacote contém 20 unidades em cor branca, permitindo personalização manual com caneta de tecido ou marcador permanente. São perfeitas para uniformes escolares, roupas de esportes, peças de uso diário, toalhas e outros tecidos que precisam de identificação discreta e eficiente. Especificações Técnicas: Produto: Etiqueta termocolante Cor: Branca Quantidade: 20 unidades Aplicação: Com ferro de passar (calor) Material: Adesivo especial resistente a lavagens Uso: Identificação de roupas, toalhas, uniformes e tecidos em geral Uma solução prática e versátil para manter as roupas sempre bem organizadas e personalizadas. Indicado o uso de caneta esferográfica, hidrográfica ou permanente. Não recomendado uso de caneta em gel!', 53.1, 42.48, NULL, 'Stationery > Notebooks & Papers > Labels & Stickers', 'https://cf.shopee.com.br/file/sg-11134201-82621-mlqkewaqxclec2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1350081126%2F22898899088', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593548068', 'Pincel marca texto Pima Marker Amarelo Pimaco', 'Deixe suas criações mais vibrantes com o Pima Marker Neon Amarelo! Cores intensas e fluorescentes que garantem destaque imediato, seja para suas anotações, projetos de arte ou personalizações. Com tinta de alta qualidade, esses marcadores são a escolha perfeita para quem quer adicionar energia e visibilidade aos seus materiais. Detalhes: - Cor intensa - Amarelo neon', 14.61, 11.5, NULL, 'Stationery > Writing & Correction > Highlighters', 'https://cf.shopee.com.br/file/sg-11134201-8261c-mlql2wvt0lxgd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1350081126%2F23593548068', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
