INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997657814', 'Kit 3 Sérum Clear Clareador 30ml Dermachem', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - APRESENTAÇÃO: Kit com 3 Unidades - - - - - DESCRIÇÃO: O Sérum Clear Dermachem Laboratory foi desenvolvido com associação de Niacinamida, ácido mandélico, ácido hialurônico e Íons silício que promovem clareamento e uniformidade da pele. Além disso, tem ação antirrugas e previne envelhecimento precoce. O resultado é uma pele incrível, radiante e viçosa. - - - - - MODO DE USO: ROTINA DIURNA: 1º PASSO: Pela manhã, limpe bem o rosto com o sabonete de limpeza da Linha DERMACHEM. 2º PASSO: Aplique de 1-2 gotas do Sérum no rosto, pescoço e colo. Faça uma massagem com movimentos circulares para melhor absorção do produto. 3º PASSO: Aplique o protetor solar de sua preferência. 4º PASSO: Ao longo do dia repita esse cuidado. - - - - - ROTINA NOTURNA: Á noite, com a pele limpa e seca aplique novamente o Sérum. Utilize o Sérum 3x ao dia. Não enxaguar. - - - - - Enviamos o seu pedido o quanto antes possível! Obrigado pela preferência.', 68.0, 43.9, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/br-11134207-820mh-mopt6mst1csl9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F20997657814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
