INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20771867646', 'Bola Futsal Penalty Rx 500 XXIII', 'Chegou a hora de treinar suas habilidades com a Bola de Futsal Penalty RX 500, recomendada para competições a partir de 14 anos. Com camada de amortecimento interno, ela oferece muito mais conforto e maciez, reduzindo o impacto no corpo e garantindo uma performance superior em quadra. Por ser sem costuras, a RX 500 garante menor absorção de água, ideal para partidas em quadras molhadas. Além disso, recebe tratamento térmico, que proporciona resistência, uniformidade e estabilidade ao longo dos jogos. Benefícios Maciez e conforto durante as partidas. Maior esfericidade para melhor controle de bola. Menor absorção de água, mesmo em quadras molhadas. Sem costuras: mais resistência e durabilidade. Diferenciais Técnicos Tecnologia de Dupla Colagem: reforço extra na junção dos gomos para maior vida útil. Câmara 6D: equilíbrio total da bola com 6 discos simétricos. Cápsula SIS: miolo lubrificado que impede o contato da agulha com a câmara de ar, evitando danos. Faixa etária: adequada para competições a partir dos 14 anos.', 139.99, 139.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-81zuq-mimr85w8wkjle5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F919401703%2F20771867646', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8738405037', 'Filtro De Ar Condicionado Captiva 2008 TODOS CES1304', 'Aplicação: CAPTIVA 2008 em diante Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar.', 22.99, 22.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820m1-mn1rr4plhyww77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F8738405037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399587427', '2 Pulseiras Ajustáveis Autismo Infantil - Quebra Cabeça', 'Por favor leia a descrição com atenção! Lindas Pulseiras p/ Autismo/autistas, são uma ótima opção para presentear alguém ou a si mesmo(a)! As pulseiras de identificação para autistas é uma ferramenta importante que oferece segurança e tranquilidade a indivíduos com autismo e suas famílias. Nossas pulseiras, discretas e confortáveis, servem como um meio eficaz de comunicação, tornando mais fácil para os outros entenderem e respeitarem as necessidades especiais do usuário. Especificações: - Tamanho: 19,5x1,5cm - Material: Borracha de alta qualidade. - Peso aproximado: 10g Anúncio referente a 2 unidades. Garantia do vendedor: 7 dias', 19.99, 19.99, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Jewelry', 'https://cf.shopee.com.br/file/br-11134207-820la-mpxncxfc3xfl2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F19399587427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6184896930', 'Filtro De Ar Condicionado 307 C3 C4 CES 1905', 'Filtro de ar condicionado para C3 e C4 Pallas Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar.', 22.99, 22.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lyzi2kspucklfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F6184896930', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200185836', 'Parafusadeira Furadeira de Impacto Bateria 18V com Carregador e Maleta 74pçs DHP490WVX1 MAKITA', 'Parafusadeira e Furadeira de Impacto a Bateria 18V com Carregador e Maleta DHP490WVX1 — MAKITA A Parafusadeira e Furadeira de Impacto 18V DHP490WVX1 MAKITA é uma ferramenta profissional projetada para oferecer máximo desempenho, autonomia e durabilidade. Equipada com o motor BL (Brushless) sem escovas, garante maior eficiência energética, reduz o atrito interno e aumenta a vida útil do equipamento — ideal para uso contínuo e intenso em obras e oficinas. Com tecnologia XPT (Extreme Protection Technology), a DHP490WVX1 é resistente à poeira e respingos de água, permitindo o uso em ambientes exigentes e com alta produtividade. O mandril de aperto rápido facilita a troca de acessórios, enquanto o controle de duas velocidades mecânicas e os 20 níveis de torque proporcionam ajustes precisos para diferentes tipos de materiais. A ferramenta também conta com iluminação LED integrada, rotação reversível, velocidade variável e freio instantâneo, oferecendo total controle e segurança ao operador. Compacta e ergonômica, é perfeita para trabalhos em carpintaria, construção civil, marcenaria e metal mecânica. Características técnicas Bateria: 18V (2,0Ah BLB182 inclusa) Motor: Brushless (BL) sem escovas Proteção: Tecnologia XPT – resistente à poeira e água Mandril: Aperto rápido 1,5 – 13 mm Torque máximo: 65 N·m Torque (junta rígida): 50 N·m Torque (junta flexível): 27 N·m Rotação (baixa): 0 – 500 rpm Rotação (alta): 0 – 1.900 rpm Impactos por minuto (baixa): 0 – 7.500 ipm Impactos por minuto (alta): 0 – 28.500 ipm Capacidade de perfuração: Aço: 13 mm | Concreto: 13 mm | Madeira: 38 mm Dimensões da Parafusadeira (C x L x A): 17,2 x 8,1 x 23,7 cm Peso: 1,4 kg Peso Bruto:4,5 kg Iluminação: LED integrada Funções: Velocidade variável, reversível, freio instantâneo Garantia: 12 meses Marca: MAKITA Modelo: DHP490WVX1 Conteúdo incluso 1 Parafusadeira/Furadeira de Impacto DHP490WVX1 MAKITA 18V 1 Bateria 18V 2,0Ah BLB182 1 Carregador rápido DCB18WA 1 Maleta plástica exclusiva Conjunto de Pontas e Brocas: Bits Torx: T10, T15, T20, T25, T27, T30, T40 Pozidrive: PZ0, PZ1, PZ2, PZ3 Philips: PH0, PH1, PH2, PH3 Fenda: SL4, SL4.5, SL5, SL5.5, SL6.5 Allen: H3, H4, H5, H6 Brocas para madeira: 4, 5, 6, 8, 10 mm Brocas para metal: 3, 3.5, 4, 4.5, 5, 5.5, 6, 6.5 mm Brocas para concreto: 4, 5, 6, 8, 10 mm Brocas chatas: 16 e 18 mm Pontas sextavadas: 8 mm, 10 mm, 12 mm, 13 mm 1 adaptador e 1 escareador Tecnologias e recursos Motor BL (Brushless): maior autonomia e durabilidade XPT: proteção contra poeira e respingos de água Indicador de carga: exibe o nível da bateria Freio instantâneo: segurança e precisão ao parar Iluminação LED: melhora a visibilidade em locais escuros Segmentos e aplicações Segmentos: Carpintaria, Construção Civil, Marcenaria, Metal Mecânica Materiais compatíveis: Alumínio, alvenaria, azulejo, cerâmica, bambu, barra roscada, chapa de aço, metais finos, concreto, drywall, MDF, madeira, plástico e tijolo maciço Usos: Perfuração, impacto e parafusamento em diversos tipos de materiais Benefícios Eficiência profissional: motor BL oferece mais torque e vida útil prolongada. Resistência extrema: tecnologia XPT protege contra poeira e água. Precisão e controle: 20 níveis de torque e 2 velocidades mecânicas. Iluminação LED: perfeita para locais de baixa visibilidade. Kit completo: acompanha pontas, brocas, bateria, carregador e maleta plástica. A Makita DHP490WVX1 combina potência, tecnologia e praticidade em um único equipamento. Ideal para profissionais que exigem desempenho superior em obras, montagens e reformas, garantindo resultados precisos e confiáveis em qualquer superfície. *Imagens meramente ilustrativas', 1111.9, 1029.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821fk-mggw2mac5wjx9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1287093777%2F58200185836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398812149', 'Colchão King Lux Molas Ensacadas + Base 193x203x66', 'Colchão King Molas Ensacadas Lux com Box 193x203x66 Bom PastorExperimente o máximo em conforto e durabilidade com o Colchão King Molas Ensacadas Lux com Box Bom Pastor. Com dimensões generosas de 193x203 cm e altura total de 66 cm, este conjunto é ideal para quem busca noites de sono tranquilas e restauradoras. Seu interior conta com molas ensacadas individualmente, que oferecem suporte anatômico e reduzem a transferência de movimento, garantindo mais estabilidade e conforto. A espuma D33 selada proporciona firmeza e resistência, enquanto a camada de EPS contribui para maior durabilidade e suporte. O box é produzido com madeira 100% reflorestada, reforçando o compromisso com a sustentabilidade e a qualidade. Produto entregue direto da fábrica, com alto padrão de fabricação e excelente custo-benefício. Ideal para quem valoriza bem-estar, espaço e materiais de qualidade superior. Especificações: • Tecido em malha construída com multifilamentos de poliéster o que proporciona uma malha resistente e com toque macio aumentando a durabilidade do seu colchão. • Estrutura em molas ensacadas individualmente e borda lateral em espuma de alto resiliência. • Bordado em Matelassê. Proporcionando maior maciez e mais volume ao colchão. • Altura: 66 cm (Base 30 cm, Colchão: 24 cm, Pés: 12 cm) Observações importantes: Produtos podem apresentar diferenças de tonalidades entre a foto na tela e o produto real, devido a calibração de cor da tela. Os objetos decorativos que ambientam as fotos não são vendidos e não acompanham o produto. O aspecto ou proporção do colchão vai variar de acordo com o tamanho escolhido (Solteiro, Casal, Queen, King). A foto serve apenas de referência para visualização de acabamento e detalhes estéticos