INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497319076', 'Kit 6 Meias Mash Social Cano Longo Algodão Lisa Masculina 231.05', 'kit 6 meias mash social cano longo algodão lisa masculina 231.05 meia social cano longo algodão lisa masculina, se você está em busca de uma meia social com cano longo, então precisa conhecer as peças da mash. a nossa marca possui inúmeros modelos deste tipo de peça, sendo que todos eles oferecem total conforto no momento de usá-los. elas são perfeitas para serem utilizadas com sapatos sociais durante um dia longo de trabalho ou um evento fino. o material utilizado para fabricar este tipo de produto é ideal para permitir que os pés respirem sem dificuldade, mesmo quando estão dentro de calçados quentes, como os de couro. além disso, o suor também é retido pela meia, o que evita o desconforto que ele pode causar. atenção : o kit é enviado com todas as peças somente em uma cor, não é possivel a alteração de cor ou tamanho. características marca: mash modelo: cano longo material: algodão design: lisa punho: sim gênero: masculino / adulto estilo da peça: casual cuidados: recomendamos seguir as instruções de lavagem anexadas a etiqueta. garantia do fabricante: até 90 dias com a apresentação do documento fiscal. embalagem: kit composição: 100% algodão sobre a mash presente no dia a dia do homem brasileiro há mais de 50 anos, a mash é referência na categoria de moda íntima masculina não apenas pela tradição, mas também pela alta qualidade, design diferenciado e inovação em tecidos e produtos.', 111.54, 111.54, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/sg-11134201-7rbnf-llw8laeriiw325', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F764761342%2F18497319076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
