INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394385255', 'Chuteira Tênis Infantil Futebol Futsal Escolar Resistente Borracha Criança Confortável Resistente', 'CARACTERÍSTICAS: Cabedal: Sintético com espessura de 1.5 mm Forro: 100% Poliéster dublado com 3 mm Solado: Borracha bicolor antiderrapante Estabilizador: Moldado a quente no calcanhar Indicação: Futsal, futebol de salão, quadras indoor Design: Exclusivo, ideal para crianças A Chuteira Infantil Flyboy foi desenvolvida especialmente para acompanhar os pequenos atletas nas atividades esportivas de maior impacto. Com cabedal em material sintético de alta resistência e forro interno dublado, proporciona conforto, estabilidade e excelente performance durante o uso. Seu solado em borracha bicolor entrega maior segurança nas movimentações, além de ser ideal para diferentes tipos de quadra, como taco, cimento ou borracha. O design moderno aliado ao estabilizador moldado a quente garante máxima firmeza aos pés das crianças, mesmo em treinos intensos ou jogos na escolinha de futebol. BENEFÍCIOS: Resistência: Material sintético robusto para suportar impactos e uso intenso Estabilidade: Forro dublado e estabilizador que proporcionam mais segurança Versatilidade: Pode ser usada tanto em treinos quanto no dia-a-dia DIFERENCIAIS TÉCNICOS: Estabilizador moldado a quente: Garante maior firmeza nos movimentos durante partidas e treinos O QUE ESTÁ INCLUSO? 1 Chuteira Infantil Flyboy Futsal Clique em "MAIS ANÚNCIOS DO VENDEDOR" e veja também outros modelos disponíveis. O pedido acompanha nota fiscal? Todo pedido efetuado segue acompanhado de nota fiscal emitida para o CPF/CNPJ informado na compra. Não efetuamos vendas sem emissão de nota fiscal. Precisa de ajuda? Utilize o campo de perguntas e esclareça suas dúvidas diretamente com um de nossos atendentes', 173.2, 100.69, NULL, 'Sports & Outdoors > Sports Footwear > Kid''s Sport Shoes', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meu1wekobkea48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F23394385255', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
