INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257758225', 'O FILHO PERFEITO', 'Da mesma autora de A empregada. Uma história perturbadora e provocante que testa os limites da lealdade de uma família. Erika Cass tem um marido perfeito. Uma vida perfeita. Até que, em uma noite tranquila, dois policiais batem à sua porta. “Gostaríamos de fazer algumas perguntas ao seu filho sobre a garota que desapareceu hoje de manhã.” Uma adolescente sumiu do bairro pacato onde moram, e a polícia suspeita do pior. O filho mais velho de Erika, Liam, foi a última pessoa a vê-la com vida. Erika sempre percebeu algo... diferente em Liam. Ele pode ser lindo, carismático e inteligente, mas coração de mãe não se engana. Ela sabe que há algo perverso em seu filho preferido, algo muito além das aparências. Mais que tudo, Erika quer acreditar na inocência dele. Porém, conforme as evidências se somam, fica impossível ignorar que Liam pode ter feito algo impensável. amos de fazer algumas perguntas ao seu filho sobre a garota que desapareceu hoje de manhã.” Uma adolescente sumiu do bairro pacato onde moram, e a polícia suspeita do pior. O filho mais velho de Erika, Liam, foi a última pessoa a vê-la com vida. Erika sempre percebeu algo... diferente em Liam. Ele pode ser lindo, carismático e inteligente, mas coração de mãe não se engana. Ela sabe que há algo perverso em seu filho preferido, algo muito além das aparências.Mais que tudo, Erika quer acreditar na', 59.9, 59.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-8260c-mmbrrummivwv0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F58257758225', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
