INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294230499', 'FOFURAS ENCANTADAS – LIVRO DE COLORIR FLUFFY TIMES – LIVRO 5', 'FOFURAS ENCANTADAS – LIVRO DE COLORIR FLUFFY TIMES – LIVRO 5 Mergulhe no mundo mágico dos livros de colorir da coleção Fluffy Times, uma celebração dos momentos de conforto do dia a dia. Neste passeio você vai encontrar fofuras como capivaras saindo de férias, o gatinho Vermelho passeando no bosque e uma ovelhinha da lâmpada pronta para realizar desejos, tudo com muitos detalhes delicados e uma atmosfera repleta de ternura. Todas as cenas foram pensadas para transmitir uma sensação de comunidade, alegria e aconchego – ideal para que pessoas de todas as idades apreciem a beleza que existe nas pequenas coisas e se deleitem com os prazeres mais simples. Para que sua experiência seja ainda mais reconfortante, este livro inclui: • Folha de acetato para proteger as páginas • 40 ilustrações originais com verso em branco (não se esqueça de colocar o acetato por baixo!) • Gabarito para testar cores e texturas • Gramatura adequada para evitar manchas de tinta no verso e danos ao papel', 49.9, 49.9, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyd-mc25u3z7stzs6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F22294230499', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993490206', 'Balcão de Canto Reto 1 Porta com Tampo Luciane Yara 80cm', 'O Balcão de Canto 1305 faz parte da Cozinha Luciane Yara, uma linha que oferece qualidade e beleza. O módulo é produzido em MDP com revestimento em pintura UV, o que garante maior resistência e durabilidade à peça. Além disso, o balcão possui 1 porta com amplo espaço interno, para você organizar louças e outros utensílios. Características do Produto: Marca: Luciane Móveis Modelo: Yara Matéria-prima: MDP Revestimento: Pintura UV Acabamento: A caixaria é Fosca e as frentes são Brilho. Tampo: Acompanha Portas: 1 Dobradiças: Metálicas Puxadores: Alumínio Pés: Plásticos Altura dos pés: 15 cm Dimensões do Produto: Altura: 89,50 cm Largura: 80 cm Profundidade: 53 cm Peso: 33 kg Garantia: 3 meses ⚠️ Observações Importantes: As imagens são meramente ilustrativas e não acompanham objetos de decoração e eletros; Pode haver alguma diferença de tonalidade entre a imagem e o produto, por conta do tratamento de imagens e a calibração de cores da sua tela; Confira as dimensões do produto no momento da compra e certifique-se de que passará normalmente por elevadores, portas, escadas e/ou corredores, evitando assim futuros desagrados ou imprevistos com a entrega do produto; A Lojas MM não se responsabiliza por montagens e instalações dos produtos.', 499.9, 499.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7reo8-m1yi8yex1motc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F23993490206', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693820715', 'Torre Simples 5 Portas Allure Linea Brasil', 'Nossa torre de cozinha é sua solução prática para maximizar o espaço .Feita completamente em MDF de alta qualidade, esta torre oferece durabilidade e funcionalidade. Ideal para organizar utensílios, mantimentos ou até mesmo pequenos eletrodomésticos. Marca: Linea Brasil Altura: 230 cm Largura: 70cm Profundidade: 52cm Peso Bruto: 66,45 kg Material: MDF Portas: 5 Portas, sendo 4 de Abrir e 1 Basculante Prateleiras: 2 Prateleiras em MDF Puxador: 2 puxadores de alumínio Pés: 4 Pés de Plásticos com sapatas niveladoras Nicho : 5 Recomendações de Uso, Manutenção e Limpeza: Realizar a limpeza com um pano levemente umedecido em água. Itens Inclusos: manual de montagem e kit ferragens Obs: As tonalidades das imagens podem variar conforme as configurações de cor, brilho e o modelo da tela do dispositivo. Dúvidas Frequentes: 1) Sobre a montagem do produto, o mesmo vem montado? O produto vai desmontado e quanto a montagem do mesmo, a Linea Brasil não possui tais serviço. Todos os produtos acompanham manual de montagem. 2) Quais são os itens inclusos do produto? As decorações são meramente ilustrativas e não acompanham o produto. 3) Esse produto é de fácil montagem? Recomendamos que seja montado por um profissional para melhor satisfação. 4) Qual o prazo de entrega? O prazo de entrega é estipulado de acordo com os prazos da transportadora parceira e CEP de destino. A consulta deverá ser realizado no próprio anúncio do produto. 5) O produto é enviado para todo o Brasil? Sim, entregamos em todo o Brasil, através de transportadoras parceiras.', 1229.0, 1139.0, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rd4h-m7axy57i0lbq8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%