INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899587610', 'Saia Feminina Floral Miudo Marialícia Rosa', 'A Saia Feminina Floral Miudo Marialícia é confeccionada em tecido de viscose estampada. Traz um ar feminino e delicado ao guarda-roupa, com sua estampa floral suave e encantadora. A modelagem midi é ideal para quem gosta de um estilo romântico e atemporal, podendo ser usada tanto em eventos diurnos, como passeios e almoços, quanto em ocasiões noturnas mais descontraídas. O tecido leve e de toque macio proporciona uma experiência confortável durante o uso, além de conferir um caimento perfeito. Combine com blusas fluidas e sandálias delicadas para um look romântico e sofisticado. Uma peça indispensável para quem deseja um visual leve e charmoso. Modelo veste G1 - Altura: 1,72 | Busto: 114cm | Cintura: 92cm | Quadril: 122cm', 129.9, 51.96, NULL, 'Women Clothes > Skirts', 'https://cf.shopee.com.br/file/sg-11134201-82585-mr1sx7f62r5w20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F18899587610', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
