INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798398652', 'Melatonina Catarinense 20ml 0,21mg/gt Maracuja', '*Produto Original* *Atenção:* Venda exclusiva para pessoa física. Pedidos com CNPJ serão cancelados. Melatonina 0,21mg/gota Catarinense Nutrição 20ml – Sabor Maracujá O suplemento alimentar Melatonina Catarinense Nutrição é apresentado em frasco de 20ml com gotejador, contendo 0,21mg de melatonina por gota. Possui sabor maracujá e é indicado para adultos a partir de 19 anos. Fácil de dosar com frasco gotejadorSabor maracujá0,21mg de melatonina por gotaFrasco com 20mlUso adulto (a partir de 19 anos)Não contém glútenCategoria de alimento dispensado de registro (RDC 27/2010) Modo de uso: Ingerir 1 gota ao dia antes de dormir, ou conforme recomendação profissional. Gotejar com o frasco na vertical e bater levemente no fundo para iniciar o gotejamento. Este produto não é um medicamento. Não exceder a recomendação diária. Manter fora do alcance de crianças. Inclua Melatonina Catarinense em sua rotina com praticidade e sabor leve.Adquira agora mesmo.', 26.11, 26.11, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rdx5-mc6yacwn13uob8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1458515228%2F23798398652', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
