INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206238835', 'Kit 2 Mamadeira Anticólica Buba Easy Flow 120ml e 270ml', 'KIT = MAMADEIRA 120ML BUBA+ MAMADEIRA 270ML BUBA MAMADEIRA EASY FLOW BUBA A Mamadeira Easy Flow Anticólica da Buba conta com um sistema de duas válvulas que evitam a formação de gases e cólicas causadas pela ingestão de ar. Possui bico em silicone ultrasoft, super macio e com textura sedosa, que se assemelha ao bico do seio da mãe. - Bico Ultrasoft: Silicone super macio e com textura sedosa que se assemelha ao bico do seio. - Sistema anticólica que evita gases: Duas válvulas que reduzem a ingestão de ar, evitando a formação de gazes e prevenindo as cólicas. - Design Ergonômico: Confortável de segurar e ideal para as mãozinhas pequenas do bebê. - Vedação Segura: Evita vazamentos, mesmo que seja virada de cabeça para baixo. - Higiênica e livre de BPA: Com bocal largo e cantos arredondados que facilitam a higienização. - Vai à lava louças e ao micro-ondas, e pode ser esterilizada. * Informações: - Contém: 1 mamadeira 120ml, 1 mamadeira 270ml - Indicado: +0 meses (mamadeira 120ml), +2 meses (mamadeira 270ml) - Fluxo: Tamanho 1 (mamadeira 120ml), tamanho 2 (mamadeira 270ml) - Composição: Polipropileno e Silicone - Garantia: 90 dias - Produto novo - Original', 57.89, 57.89, NULL, 'Mom & Baby > Feeding Essentials > Bottle-feeding', 'https://cf.shopee.com.br/file/sg-11134201-82603-mlfaj8dm6fwh6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58206238835', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
