INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54363781704', 'Bomba de Ar De Mão Vertical Plástica 30cm Fertak', 'Bomba de Ar de Mão Vertical Plástica 30cm Fertak CARACTERÍSTICAS: - Garantia: 3 Meses - Tipo: Bomba de Ar Manual Vertical - Material: Plástico - Altura: 30 cm - Acionamento: Manual - Formato: Vertical - Compatibilidade: Válvula fina (Presta) e válvula comum (Schrader) - Acompanha Adaptadores: Sim - Quantidade de Bicos: 2 - Aplicação: Inflagem de pneus e infláveis - Marca: Fertak DETALHES: - A Bomba de Ar de Mão Vertical Fertak foi desenvolvida para oferecer praticidade, eficiência e facilidade na inflação de pneus e diversos produtos infláveis. - Seu design compacto e leve facilita o transporte e o armazenamento, sendo ideal para manter em casa, no carro, na bicicleta ou levar durante passeios e viagens. - Possui estrutura em plástico resistente, proporcionando maior durabilidade e excelente desempenho para o uso diário. - O sistema de acionamento vertical permite uma inflação mais rápida e confortável, exigindo menor esforço durante o bombeamento. - Acompanha dois bicos adaptadores, permitindo o uso em válvulas finas (Presta) e válvulas comuns (Schrader), oferecendo maior versatilidade. - Indicada para encher pneus de bicicletas, motocicletas, automóveis, além de colchões infláveis, piscinas, brinquedos infláveis, bolas esportivas e diversos outros itens. - Seu tamanho de 30 cm proporciona ótimo equilíbrio entre portabilidade e eficiência, tornando o equipamento fácil de transportar e utilizar em qualquer lugar. - Ferramenta indispensável para situações de emergência, passeios, atividades esportivas, camping e uso doméstico. - Produto prático, resistente e de fácil operação, oferecendo excelente custo-benefício para quem busca uma bomba manual versátil. DIFERENCIAIS: - Estrutura leve e resistente - Design compacto e portátil - Sistema de bombeamento vertical - Fácil de transportar - Compatível com válvulas Presta e Schrader - Acompanha 2 bicos adaptadores - Ideal para pneus e infláveis - Fácil de utilizar - Excelente para emergências - Ótimo custo-benefício CONTEÚDO DA EMBALAGEM: - 1 Bomba de Ar de Mão Vertical 30 cm Fertak - 2 Bicos adaptadores', 24.9, 13.9, NULL, 'Home & Living > Tools & Home Improvement > Air Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-8259g-mqhzzh7czc3w02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844004880%2F54363781704', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
