INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8803739822', 'Gloss Efeito Volume Bruna Tavares Bt Plump Angel', 'Descrição: O BT Plump Angel da Bruna Tavares é um gloss labial que aumenta seus lábios, isso enquanto hidrata e dá a sensação de frescor. Tem efeito imediato o BT Plump ajuda a preencher os sulcos dando a sensação de lábios mais volumosos. Possuí ativos que proporcionam lábios mais fortes firmes e hidratados, o uso continuo aumenta a produção de colágeno e elastina nos lábios. Reduz os vincos e defini o contorno labial, proporcionando um efeito de preenchimento e volume. Levemente pigmentado, transparente com leve fundo de cor. Caracteristicas: - Aumenta seus lábios dia após dia. - Lábios firmes e hidratados. - Preenche os vincos labiais. - Efeito Plump de preenchimento. Informações: MODO DE USAR: Aplique sobre os lábios deslizando o aplicador do centro para as laterais. Você pode utilizar o produto sozinho ou antes de seu batom. Precauções: USO EXTERNO. MANTENHA FORA DO ALCANCE DAS CRIANÇAS. Conteúdo da embalagem: 6ml. Composição: Butylene/Ethylene/Styrene Copolymer, Stearalkonium Hectorite, Phenoxyethanol, Propylene Carbonate, Pentaerythrityl Tetraisostearate, Caprylyl Glycol, CI 77891, BHT, Vanillyl Butyl Ether, Spilanthes Acmella Flower Extract, CI 77492, CI 77491, CI 15850 Benzotriazolyl Dodecyl p-Cresol, Aqua, CI 77002, Alcohol, Tris (tetramethylhydroxypiperidinol) Citrate #Imagem ilustrativa. Cor do produto poderá variar dependendo da configuração do monitor ou celular.', 44.99, 44.99, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/423a05963d819c02512f8b54ddb7a5b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322432427%2F8803739822', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
