INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257724933', 'Frigobar Duplex 117L Philco Iluminação em LED PFG12A', 'O Frigobar Duplex Philco PFG12A é a escolha ideal para quem busca praticidade, eficiência e organização em um único produto. Com capacidade total de 117 litros, sendo 91 litros destinados ao refrigerador e 26 litros ao freezer, ele permite armazenar e conservar alimentos e bebidas com muito mais comodidade no dia a dia. Seu sistema duplex com freezer separado facilita o controle de temperatura e a melhor disposição dos itens, enquanto os 7 níveis de potência de refrigeração garantem ajustes precisos conforme a necessidade. As 3 prateleiras em acrílico super resistente, sendo duas reguláveis e uma gaveta com controle de umidade, oferecem versatilidade e melhor aproveitamento do espaço interno. Com classificação energética A++, o Frigobar Philco proporciona maior economia de energia. A iluminação interna em LED branco não gera calor e melhora a visualização dos alimentos, enquanto o gás ecológico R600a utilizado não agride o meio ambiente. Sem falar nos pés com regulagem de altura para adaptação perfeita a qualquer ambiente. Conte com o Frigobar Duplex 117L Philco PFG12A e tenha mais praticidade para armazenar alimentos e bebidas. Classificação energética A++ Frigobar duplex com freezer separado do refrigerador Capacidade de 117L Gás R600a 7 Níveis de potência de refrigeração 3 Prateleiras em acrílico super resistente Iluminação em LED branco 2 pés com regulagem de altura', 1849.9, 1849.9, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-824hc-mpmp6864rl6z11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1276145502%2F58257724933', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
