INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51160575168', 'Chinelo Kenner NK6 Preto - Masculino', 'O equilíbrio perfeito entre potência, estilo e conforto! Chinelo Kenner NK6 Preto - Masculino Parte superior do formulário Ficha Técnica: Marca: Kenner Gênero: Masculino Cor: Preto com detalhes em prata Indicação: Uso diário, praia e dia a dia Cabedal: Nova tira zigue-zague na cor preta Palmilha: EVA extramacia na cor preta Solado: Tratorado de borracha vulcanizada, antiderrapante na cor preta Bico: Arredondado amplo e confortável, não sendo pontudo ou estreito Tira frontal: Duas tirar largas no peito do pé Formato: Forma padrão Tecnologias: Solado anatômico com alta tração, estrutura durável e confortável (reduz atrito com a pele) Detalhes: Identificador bimetal K em prata Se você busca um chinelo com visual imponente, conforto de alto nível e tecnologia aplicada, o Kenner NK6 é a sua escolha definitiva. Com nova tira frontal zigue-zague que garante um encaixe firme e estiloso, ele entrega performance para o dia a dia com solado tratorado antiderrapante Por que investir: O Kenner NK6 foi projetado para quem vive com intensidade, precisa de estabilidade e exige design moderno. Seu acabamento com identificador bimetal, somado ao conforto do solado anatômico, faz dele uma peça premium com excelente custo-benefício Conteúdo da embalagem: 1 Chinelo Kenner NK6 Preto - Masculino', 149.99, 93.99, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-822ym-mo9nri8neuby48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F51160575168', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
