INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998275764', 'Espuma Vonixx - Aplicador de Alta Qualidade com Células Fechadas para Condicionamento de Plásticos e Pneus', '>>>>>>APLICADOR DE ESPUMA VONIXX<<<<<< Conteúdo da Embalagem: 01 (Um) Aplicador de Espuma; Aplicador de Espuma Vonixx; **Imagens e vídeo do anúncio são reais. Desenvolvido com células fechadas de alta qualidade e criado especialmente para aplicação de ceras, hidratantes para couro, limpadores, renovadores de plásticos, polidores, produtos para pneus e etc. Seu formato anatômico permite fácil manuseio. Devido a sua construção à base de poliéster pré-soft, esse produto traz algumas características importantes como: resistência ao rasgo, resistência a solventes e maciez extrema. IDEAL PARA REALIZAR APLICAÇÃO DE PRODUTOS PARA CONDICIONAMENTO DE PLÁSTICOS E PNEUS', 14.9, 12.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd5j-m72d3bv9fkdu27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1273324128%2F23998275764', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193743597', 'Mangueira Radiador Superior IDEA 1.4 8v 2007 Ate 2017 - 88361 - 8241', 'Mangueira Radiador Superior IDEA 1.4 8v 2007 Ate 2017 Motor 1.4 8v - (Superior)O liquido entra no radiador pela "mangueira superior", em geral conectada na parte de cima do radiador. A medida que o liquido desce, ele passa por canais no radiador resfriados por meio de passagem do ar pelas aletas de refrigeração entre os canais. Depois ser resfriado, o liquido sai do radiador pela "mangueira inferior". Em geral, há uma mola dentro dessa mangueira para evitar que ela quebre quando a bomba de agua puxa o liquido do radiador.', 31.72, 31.72, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8259d-mr21g6dr4paaaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23193743597', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298260657', 'Carrinho De Praia Infantil Menino Beach Play', 'CHEGOU PARA ENCANTAR – O CARRINHO DE PRAIA BEACH PLAY Carrinho com design exclusivo e acessórios incríveis para garantir a diversão das crianças na praia ou no parque! Com cores vibrantes e muito estilo, o Carrinho de Praia Beach Play vai estimular a criatividade enquanto as pequenas constroem castelos de areia e se aventuram ao ar livre. Além de divertido, é super fácil de transportar, ideal para brincadeiras que desenvolvem habilidades motoras e a imaginação. PERGUNTAS FREQUENTES: 1 – Qual o tamanho do carrinho? O produto possui 23,5 cm de altura. 2 – O produto é original? Sim! Produto original de fábrica. 3 – Acompanha acessórios? Sim, acompanha 4 forminhas, pá e rastelo. BENEFÍCIOS Estimula o raciocínio lógico Desenvolve a criatividade e o imaginário Promove a socialização entre as crianças Trabalha a coordenação motora Incentiva a comunicação e o faz de conta Contribui para o desenvolvimento emocional e afetivo CARACTERÍSTICAS Produzido com plástico resistente e de alta qualidade Estampa vibrante e charmosa da linha Beach Play Acessórios ideais para brincar na areia FICHA TÉCNICA Marca: Usual Brinquedos Coleção: Beach Play Tamanho (C x A x L): 37 x 23,5 x 23,5 cm Peso Aproximado: 0,720 kg Material / Composição: Plástico Recomendado para: Crianças a partir de 03 anos Referência: 854 Número de Registro: 001204/2019 CONTEÚDO DA EMBALAGEM: 1 CARRINHO DE PRAIA BEACH PLAY 4 FORMINHAS 1 PÁ 1 RASTELO SOBRE A USUAL BRINQUEDOS Com mais de 200 itens em seu catálogo, a Usual Brinquedos se destaca pela qualidade, segurança e criatividade de seus produtos. Todos são certificados pelo INMETRO e fabricados com matéria-prima virgem de primeira linha. Cada detalhe é pensado com carinho, sempre com foco no desenvolvimento saudável e criativo das crianças. GARANTIA Garantia de 90 dias contra defeito de fabricação. GARANTA JÁ O SEU E LEVE A DIVERSÃO PARA ONDE FOR!', 159.99, 149.9, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-7ra2c-mbfjl3pd1z6e81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547749545%2F21298260657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203854923', 'Trator Brinquedo Miniatura Infantil New Holland T8 Com Carretinha Cor Tora Usual Brinquedos', 'Apresentamos o Trator Brinquedo Miniatura Infantil T8 com Carretinha, uma réplica perfeita para os pequenos entusiastas de máquinas agrícolas. Este modelo, em escala 1:30, é uma fiel representação do veículo New Holland, conhecido por sua robustez e eficiência no campo. A miniatura é feita de plástico resistente, garantindo durabilidade e segurança durante a brincadeira. O design inclui uma cabine translúcida e pneus emborrachados, que adicionam um toque de realismo ao brinquedo. Acompanha uma carretinha, permitindo que a criança expanda as possibilidades de jogo, transportando pequenos objetos ou outros brinquedos. Este produto é indicado para crianças a partir de 3 anos, estimulando a imaginação e o desenvolvimento de habilidades motoras finas. Além de ser um item divertido, este trator também serve como peça de coleção, pois é considerado colecionável. Não possui partes móveis, o que o torna uma excelente opção para colecionadores que desejam manter a integridade do modelo. A Usual Brinquedos, fabricante do produto, é reconhecida por sua qualidade e atenção aos detalhes, o que é evidente neste trator miniatura. Ideal para ser dado como presente, o Trator Brinquedo Miniatura Infantil T8 com Carretinha promete ser o centro das atenções em qualquer coleção de brinquedos ou como uma peça encantadora na prateleira do quarto das crianças. Com ele, os pequenos podem criar suas próprias aventuras agrícolas, desenvolvendo a criatividade e o amor pelo universo rural.', 120.0, 109.99, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjsqxcy7xh4zfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547749545%2F58203854923', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258741782', 'Spray Acabamento Metálico 395ml Metallic Rust-Oleum - Cores', 'Descubra a magia do Spray Acabamento Metálico Ouro da Rust-Oleum! Este spray é a escolha perfeita para transformar qualquer objeto decorativo com um brilho metálico deslumbrante. Ideal para molduras, castiçais e enfeites, ele proporciona um acabamento que brilha com autenticidade. Características Principais: - Brilho Metálico: As partículas brilhantes garantem um efeito metálico genuíno. - Versatilidade: Pode ser usado em madeira, metal, cerâmica não esmaltada, alvenaria e gesso. - Aplicação Flexível: Pinte em qualquer ângulo, sem complicações. - Secagem Rápida: Retome o uso dos seus objetos em breve tempo. - Uso Interno: Perfeito para projetos em ambientes internos. Transforme seus objetos com facilidade e estilo. O Spray Acabamento Metálico Ouro é a solução para um toque decorativo sofisticado e prático.', 199.9, 49.99, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-820lq-mn07qmj40mwy2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717380864%2F58258741782', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
