INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892523987', 'Filtro Combustível Fiat Stilo 2002 a 2007 - 505597 - FCI1660', 'Filtro Combustível Fiat Stilo 2002 a 2007 505597 FCI1660 (Connect) Motor 1.8 8v /(Connect/Schumacher)Motor 1.8 16v /(Abarath) Motor 2.4 20v – (Gasolina) (Mecãnico) (Plástico) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 27.11, 27.11, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbkb-lmqg46balhr74b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22892523987', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
