INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793742361', 'Cebolinha do Óleo SANDERO 2016/2024 - 92826 - 3305', 'Cebolinha do Óleo SANDERO 2016/2024 1.0 12V/ 2.0 16VIndicar anomalia na pressão do óleo lubrificante. O interruptor de pressão do óleo é normalmente localizado no bloco do motor próximo a bomba de óleo, a pressão gerada pela bomba passa pelo interruptor acionando uma mola interna do mesmo fechando assim contato elétrico, enviando um sinal para o painel de instrumentos. Se a pressão for maior do que a especificada o interruptor libera a passagem do óleo de volta para o cárter. Vida Útil: Substituir a cada 40.000 Km (consultar manual do veículo)', 101.56, 101.56, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd5a-m6tvdoyod7x020', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23793742361', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097035180', 'FIltro Ar Condicionado CORSA 2003/2008 - 37089 - AKX35159', 'FIltro Ar Condicionado CORSA 2003/2008 (Hatch / Premium / Maxx / SS) - Motor 1.8 8v Flex Power - (Mecânico) (Abas Laterais) Os filtros do ar para cabine são produzidos com fibras carregadas eletrostaticamente. Este filtros possuem camadas protegidas de um lado por um pré-filtro para reter partículas maiores. Do lado oposto possui uma camada de proteção a danos ao filtro.A função do meio filtrante é remover a maior quantidade possível de contaminantes do sistema do ar, oferecendo o mínimo de restrição ao fluxo de ar.', 31.66, 31.66, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rat5-maovddrx9q35e4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22097035180', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45152491465', 'Organizador Duplo De Gavetas Porta Talheres Extensível Universal Com 9 Divisórias Cor Branco Arthi', 'Organizador Duplo de Gavetas Porta Talheres Extensível – Branco Arthi Mantenha sua cozinha sempre arrumada e funcional com o Organizador Duplo Extensível da Arthi! Com design inteligente e adaptável, ele se ajusta a diferentes tamanhos de gaveta e oferece muito mais espaço para organizar talheres e utensílios do dia a dia. Especificações Cor: Branco Modelo: Organizador Duplo Extensível Material: Plástico resistente Marca: Arthi Indicado para: talheres e utensílios de cozinha Ajustável para vários tamanhos de gaveta Por que escolher este organizador? ✔ Otimiza o espaço interno da gaveta ✔ Mantém talheres separados e fáceis de encontrar ✔ Evita bagunça e desperdício de espaço ✔ Produto durável, prático e elegante Garantia: 90 dias contra defeitos de fabricação. Loja do Primo Variedades.', 71.5, 55.9, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/br-11134201-820l7-mqy6wgxjz0g4bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402450553%2F45152491465', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297995452', 'Lâminas para Serra Tico Tico de Bancada TSTTB120 - Kit com 3 Unidades', 'Lâminas para Serra Tico Tico de Bancada TSTTB120 - Kit com 3 UnidadesDescubra a eficiência e a qualidade das Lâminas para Serra Tico Tico de Bancada TSTTB120, um kit essencial para profissionais e entusiastas do DIY. Com um design robusto e materiais de alta qualidade, essas lâminas são perfeitas para cortes precisos em diversos tipos de madeira e outros materiais. A escolha ideal para quem busca desempenho e durabilidade em suas ferramentas de trabalho. Atributos do ProdutoMarca: Tander Modelo: 201018628 Altura: 1 cm Baterias necessárias? Não Certificação de teste externa: Não aplicável Componentes incluídos: Ferragens de montagem Cor: Preto Dimensões do item (L x A): 1 cm x 1 cm EAN: 7899646116403 Exige montagem: Sim Fabricante: Tander Largura: 7 cm Peso: 0 kg Peso do pacote: 0.12 kg Quantidade de itens: 1 Tamanho: Tamanho especial Por que Escolher as Lâminas TSTTB120?As lâminas TSTTB120 são projetadas para oferecer cortes limpos e precisos, garantindo que seus projetos sejam executados com a máxima eficiência. O material de alta qualidade proporciona resistência ao desgaste, aumentando a vida útil do produto. Além disso, a montagem é simples e prática, permitindo que você inicie seus trabalhos rapidamente. Aplicações e UsabilidadeIdeal para uso em madeiras, plásticos e outros materiais, o kit de lâminas é uma excelente adição ao seu arsenal de ferramentas. Seja para projetos profissionais ou para hobby, a versatilidade das lâminas TSTTB120 atende a diversas necessidades, facilitando o corte em ângulos e formatos variados. Adquira Já o Seu Kit!Não perca a oportunidade de otimizar seus cortes com as Lâminas para Serra Tico Tico de Bancada TSTTB120. Invista em qualidade e eficiência para seus projetos. Faça seu pedido agora e transforme sua experiência de trabalho!', 25.0, 25.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rep5-m1wsuttg73p205', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F23297995452', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251689047', 'Cabine Jateamento de Areia 100l Bivolt de Bancada', 'Cabine de Jateamento de Areia 100L Bivolt de Bancada – NCJDA100L – NAGANO Mais produtividade, acabamento profissional e ambiente limpo na hora de preparar superfícies metálicas. A Cabine de Jateamento de Areia Nagano 100L – NCJDA100L foi desenvolvida para oferecer uma solução prática, segura e eficiente para limpeza, remoção de tinta, ferrugem e resíduos em peças metálicas. Seu sistema totalmente fechado evita a dispersão de poeira e abrasivo, mantendo o ambiente de trabalho mais limpo e protegido. Com visor protegido em múltiplas camadas, luvas integradas de alta resistência, iluminação interna embutida e pistola de jateamento inclusa, a cabine garante excelente visibilidade, ergonomia e controle durante o processo. Perfeita para oficinas, funilarias, serralherias, auto centers e manutenção industrial, a NCJDA100L é uma aliada fundamental para quem busca qualidade de acabamento e agilidade no retrabalho de peças. Benefícios do produto Ambiente mais limpo e seguro: estrutura fechada que reduz a dispersão de poeira e abrasivo. Excelente visibilidade de trabalho: visor com múltiplas camadas de proteção (moldura + acrílico + vidro + filme PE) e iluminação interna embutida. Maior controle e conforto: luvas integradas de alta resistência, permitindo manusear peças com segurança. Capacidade de 100 litros', 1632.8, 1632.8, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-822yt-mi1t62iikefc8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F58251689047', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897152715', 'Kit de Pintura Não Respinga: Faça Você Mesmo', 'Se você está procurando uma forma prática e econômica de dar uma cara nova à sua casa, o Kit para Pintura Não Respinga Premium é a solução ideal. Esse kit contém tudo o que você precisa para fazer pequenos reparos e pinturas com qualidade e versatilidade. Você vai se surpreender com o resultado! CARACTERISTICAS O Kit Pequenos Reparos é composto por: 1 Bandeja de 1000 ml 1 Rolo Lã Microfibra Seda 10 mm x 23 cm 1 Cabo com Bucha para Rolo 23 cm 1 Rolo de Espuma Poliéster 9 cm 1 Lixa para massa grão 100 - A293 Trionite 225x275mm 1 Trincha 1" Cerda Gris Série 200 1 Trincha 1 1/2" Cerda Gris Série 200 1 Espátula Plástica 7 cm 1 Desempenadeira Mini 07 x 16 cm Tipos de superfícies indicadas: É indicado para paredes Lisas, Ásperas e Semirrugosas, Gesso e Drywall. OS CONJUNTOS DE FERRAMENTAS ESSENCIAIS As mais variadas combinações que atendem desde pequenos reparos até trabalhos maiores, com qualidade, economia e versatilidade. As melhores ferramentas, os melhores resultados. Tudo para facilitar a sua vida! SEGURANÇA Compre com segurança! Nossa equipe de suporte estará à disposição caso tenha algum problema ou dúvida.', 57.26, 57.26, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rbk9-logt43pi7pkvc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524472372%2F23897152715', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
