INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18459419408', 'Cadeado Elleven Corrente 3.5x80cm', 'Cadeado Elleven Corrente 3,5x80cm O Cadeado 3,5x80cm da Elleven oferece muito mais segurança e proteção para sua bike. Conta com fechamento em chaves e cabo em corrente, com 3,5cm de expessura, garantindo sua tranquilidade enquanto estiver distante de sua bicicleta. Fabricado com material de alta qualidade, o Cadeado em corrente 3,5cmx80cm assegura toda a segurança necessária, além de muito mais resistência e qualidade garantida pela marca Elleven. O Cadeado Elleven de corrente conta com revestimento externo em material plástico resinado, que gera muito mais resistência contra a umidade e atritos derivados do uso, garantindo muito mais durabilidade de uso. Especificações do Cadeado Elleven Corrente 3,5x80cm - Corrente especial com 3,5mm de espessura - assegura toda a segurança, resistência e qualidade; - Revestimento compacto e flexível - permite que possa prender sua bicicleta em objetos fixos variados; - Revestimento de proteção - impede que o cadeado cause danos a pintura, ou a outras partes da bike; - 02 Chaves - segredo e miolo com desenhos diferenciados para maior segurança; - Medidas aproximadas: Comprimento 80cm X Diâmetro 3,5cm.', 34.02, 34.02, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/ce9c2a4cb196bc3a4474e6836f45b0b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F18459419408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
