INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297456473', 'Rolamento 6202 Traseira/Dianteira Titan 125 150 160 Ybr 125 Ed Factor', 'Descrição Descrição do produto: Par Kit 2 Peças 6202 Rolamento Trase/dian Ybr 125 Ed Factor Recomendações: Antes de efetuar a compra, verifique se realmente é esta peça que deverá ser trocada. Aplicação: Roda TRASEIRA E DIANTEIRA - Yamaha YBR 125 E K 2000 a 2008; - Yamaha YBR 125 ED 2000 a 2008; - Yamaha YBR 125 Factor E K 2009 a 2015; - Yamaha YBR 125 Factor ED 2009 a 2015; Aplicação: Roda Traseira - Honda CG 125 Titan ESD 2004 a 2004 TRASEIRO - Honda CG 125 Fan 2004 a 2004 a 2008 TRASEIRO - Honda CG 150 Titan KS 2004 a 2008 TRASEIRO - Honda CG 160 Titan KS 2004 a 2023 TRASEIRO - Honda CG 150 Titan KS/ES/ESD 2004 a 2014 TRASEIRO. -MUITAS OUTRAS MOTOS NA RODA DIANTEIRAS -BLINDAGEM DE BORRACHA Produto de ótima qualidade . Desde já Agradecemos a preferencia . Shopping da Motobike.', 59.9, 47.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lu3s0q2hbu5c7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F531303273%2F23297456473', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50850023302', 'Sapatênis Rafarillo Alth Toronto Aumenta 7cm Original 93051 Preto', '👞 Sapatênis Rafarillo Alth Toronto Masculino Aumenta Até 7cm Original 93051 👞 Estilo, conforto e elegância em um só calçado! O Sapatênis Rafarillo Alth Toronto 93051 Original foi desenvolvido para homens que valorizam o visual moderno sem abrir mão do bem-estar. Com tecnologia Alth, ele proporciona aumento de até 7 cm na altura, de forma discreta e natural — ideal para quem quer mais confiança e presença em qualquer ocasião. Seu design minimalista combina perfeitamente com jeans, sarja ou alfaiataria, sendo uma escolha versátil para o dia a dia, trabalho ou momentos casuais. Temos também esse modelo disponível em outras cores, acesse o link para conferir: https://shopee.com.br/product/324536294/41175512116/ 🌟 Benefícios Exclusivos: 👞 Aumenta até 7 cm na altura com conforto total 💪 Palmilha anatômica que absorve o impacto e oferece estabilidade 🕶️ Design moderno e sofisticado, fácil de combinar 🌬️ Forro interno respirável que mantém os pés secos 💼 Ideal para o uso diário e eventos sociais 📋 Ficha Técnica: Marca: Rafarillo Modelo: Alth Toronto 93051 Tipo: Sapatênis Masculino Material Externo: Couro legítimo Forro: Tecido respirável Palmilha: Anatômica e macia Solado: Borracha antiderrapante Fechamento: Cadarço Estilo: Casual / Social / Urbano Altura interna: Até +7 cm Numeração: 37 ao 44 📏 Tabela de Medidas (cm): 37 – 25,0 cm 38 – 25,6 cm 39 – 26,3 cm 40 – 27,0 cm 41 – 27,6 cm 42 – 28,3 cm 43 – 29,0 cm 44 – 29,6 cm 🧼 Dicas de Limpeza e Conservação: 🧽 Limpe com pano úmido e sabão neutro. 🚫 Não utilize produtos químicos ou escovas duras. 🌤️ Deixe secar naturalmente, à sombra. 👞 Aplique creme hidratante próprio para couro para preservar o brilho e a durabilidade. 💼 Por que escolher Rafarillo: ✅ Tecnologia de aumento interno com conforto e discrição ✅ Couro legítimo de alta qualidade ✅ Visual moderno que combina com qualquer look 👔 Rafarillo Alth Toronto — elegância e confiança em cada passo.', 389.9, 249.9, NULL, 'Men Shoes > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg6l3aqarnyc6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F50850023302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
