INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299298175', 'LANTERNA TRAS - BROS 160 2015 a 2017', 'Fundada em 1995, a VALPLAS iniciou suas atividades produzindo Piscas para motocicletas que desde o princípio se diferenciam por sua qualidade.Com o passar dos anos, novos produtos foram sendo agregados e assim nasceu a Linha Valplas de Piscas, Lentes e Lanternas.Investimentos em tecnologias e em recursos humanos no decorrer destes 22 anos, resultaram em um crescimento no segmento de Motocicletas, que levou a uma reestruturação desta área e a mudança para um espaço ainda maior em Bragança Paulista, a 100 km de SP, onde hoje é a sede da VALPLAS, com uma área de aproximadamente 10.000 metros.LANTERNA TRAS - BROS 160 15/17', 67.37, 67.37, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rd41-lwncxmtssdid60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F362325018%2F20299298175', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
