INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260145327', 'Cachaça Cristalina Sagatiba', 'Sagatiba é a busca pela reinvenção da cachaça e do Brasil. A Cristalina é multidestilada em coluna de aço, o que garante uma bebida livre de impurezas e de alta qualidade. Ideal para a preparação de caipirinhas e outros drinks.', 47.49, 47.49, NULL, 'Food & Beverages > Alcoholic Beverages > Liquor & Spirits', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mqnelyvzqdxfcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554774%2F58260145327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
