INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9662644265', 'Nagaraku Mix 7~15mm Cílios Individuais Cílios De Seda Falso Cílios Mink Colorido', 'Descrição do produto: Marca NAGARAKU Nome: Misturar Marrom Cílios Material: Mistura Sintética Capacidade: 16 linhas uma bandeja Cor da Caixa: Marrom Cachos: B C D Espessura da grossura: 0,07 mm, 0,10 mm, 0,10 mm, 0,15 mm Comprimentos do Mistura de 7mm-15mm Usamos um material especial que é macio, leve e natural como cabelo humano. Tira fácil de pegar, sem hierarquia e resíduos no suporte para cílios. Padrão de cacho forte estável. Usado para festa, dançar ou até mesmo vida diária. Adotamos um papel de parede de combinação amigável ao ambiente de papel e folha de papel. Nosso material foi certificado pela SGS e MSDS, é seguro para todos.', 22.56, 15.35, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/cn-11134207-820l4-mp23tbubcjdac3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349433484%2F9662644265', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252845949', 'Faca de Handstripping Com 57 Dentes Para Remoção de Pelos Cachorro Gato', 'Faca de Handstripping de Madeira - 57 Dentes Faca de stripping para remoção precisa de pelos mortos, ideal para cães com pelagem dura e média. Formato ergonômico, com cabo de madeira, proporcionando conforte e controle no manuseio. Com dois lados dentados, ele proporciona o procedimento completo de handstripping. Com mais dentes e fechados, é ideal para a retirada de pelos de forma mais precisa. Remoção do subpelo: Segure a faca como se fosse fazer uma escovação e use suavemente na direção do crescimento do pelo. Se necessário, repita esse procedimento, até que todo o pelo morto seja removido. Escovação profunda e mais pesada deve ser evitada, pois pode acabar irritando a pele do animal. Se a pele mostrar vermelhidão, suspenda o uso do produto imediatamente. Medidas: Comprimento: 16cm Largura: 2,5cm Profundidade: 1cm.', 126.0, 118.44, NULL, 'Pets > Pet Grooming > Hair Care', 'https://cf.shopee.com.br/file/sg-11134201-8261f-mj71xcxzywhxc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688030691%2F58252845949', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198714238', 'Caminha Pet Redonda Cachorros E Gatos 47cm Urban Pet Azul', 'Caminha Redonda para Cães e Gatos – Conforto, Estilo e Proteção - Urban Pet! Seu pet merece todo cuidado e carinho, e nada melhor do que oferecer uma caminha confortável, segura e com design sofisticado! Ideal para dias frios e ambientes úmidos, a nossa caminha possui fundo 100% impermeável e antiderrapante, protegendo seu animalzinho contra o frio e a umidade do chão. Recomendada para pets de até 12kg Tecido Poliéster com Manta – super macio. Enchimento reforçado nas laterais e conta com almofada central removível. Design moderno e aconchegante Dimensões: Diâmetro: 47cm Conteúdo: 01 cama', 89.9, 89.9, NULL, 'Pets > Pet Accessories > Pet Furniture', 'https://cf.shopee.com.br/file/sg-11134201-7rdxr-mbs4nyzdx1uv1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F740995429%2F22198714238', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41076876889', 'Carrinho Recarregável Controle Remoto Acrobata Gira 360 Graus Dinossauro Com Luzes Infantil Kizumba', 'Carrinho Recarregável Controle Remoto Acrobata Gira 360 Graus Dinossauro Com Luzes Color Efeitos Especiai Colorido Brinquedo Encantado Infantil Menina Kizumba Leve a magia dos para a brincadeira das crianças com este Carrinho Recarregável! Com design encantador, luzes coloridas que iluminam o ambiente e efeitos sonoros divertidos, este brinquedo é perfeito para entreter os pequenos com segurança e alegria. Ideal para meninas e meninos que adoram brilho e fantasia, o carrinho possui rodas com giro automático, permitindo movimentos inesperados e surpreendentes que encantam durante a brincadeira. Com bateria recarregável e corpo resistente, é um presente incrível que estimula a imaginação e garante sorrisos! Especificações Técnicas: • Idade recomendada: A partir de 3 anos • Tipo de alimentação: Bateria recarregável e Pilhas para Controle (Não Inclusas) • Luzes LED multicoloridas • Movimento automático com função bate e volta • Material: Plástico resistente Dimensões: • Comprimento: 13,5 cm • Altura: 12 cm • Largura: 11 cm FAQ – Perguntas Frequentes: 1. O carrinho funciona com pilhas? Não. Ele possui bateria recarregável inclusa com cabo USB. 2. O brinquedo possui botão liga/desliga? Sim, há um botão de controle fácil para ativar luzes, som e movimento. 3. As luzes são fortes? Podem ser usadas no escuro? Sim! As luzes LED iluminam com intensidade, criando um efeito incrível no escuro. Conteúdo da Embalagem: • 01 Carrinho • 01 Controle Remoto • 01 Cabo USB para Recarga Importante: Valor Unitário. Imagens Meramente Ilustrativas. Não nos responsabilizamos pelo mau uso do produto.', 149.9, 69.0, NULL, 'Hobbies & Collections > Toys & Games > Remote Control Toys & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-82257-mhnr73ewl2iw50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F281898655%2F41076876889', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45109934966', 'Copo Canudo Flip Princesas 500ml Zona Criativa - 10026559', 'Depois de um dia de brincadeiras, o seu filho precisa de uma pausa para repor as energias? A gente te ajuda! Com 500ml de capacidade e design ergonômico projetado para o encaixe perfeito da mão da sua criança, com uma alça para ajudar a carregar, esse copo é a companhia perfeita para a pausa entre as brincadeiras! Não importa se é pique esconde ou pega-pega, esse copo te acompanha em todas as suas aventuras!O copo é importado, com detalhes incríveis que vão fazer você e seu filho se apaixonarem! Se você precisa de um copo que entre no ritmo das brincadeiras da sua criança, o copo flip é a companhia perfeita! Com 500ml de capacidade, feito em plástico, com BPA free e uma tampa rosqueável que possui canudo, vai acompanhar os passos do seu filho da hora que ele acordar, até a hora de dormir! Além de possuir um aplique 3D do personagem favorito da sua criança! Não importa se é leite ou suco, esse copo te acompanha em todas as suas aventuras!EspecificaçõesAltura 20cm| Largura 10cm| Comprimento 10cm| Capacidade 500ml| BPA Free| Material Plástico PP, AS e PVC Cuidados e recomendações de usoNão preencha com líquidos até a superfície, deixe pelo menos 1,5cm de espaço para poder fechar o copo.Choques ou quedas podem trincar ou quebrar o produto.Não é a prova de pequenos vazamentos, carregue o produto apenas na posição vertical e não coloque em bolsas ou mochilas.Lavar com água, esponja macia e sabão neutro.Não recomendado colocar no freezer. Características:- Marca:Zona Criativa- Modelo:10026559*Imagens Meramente Ilustrativas*Conteúdo da Embalagem: - 01x COPO CANUDO FLIP 500ML PRINCESAS', 72.94, 65.65, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Bags & Luggage', 'https://cf.shopee.com.br/file/sg-11134201-820ok-mnu24qwww004b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F45109934966', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12815007434', 'Alto Falantes Pioneer 6 Polegadas TS-1790BR 120W RMS 4 Ohms Triaxial Bobina Simples', 'ALTO-FALANTES TS-1790BR O TS-1790BR traz maior fidelidade ao seu sistema de som automotivo. Seu midrange com conjunto magnético de neodímio e cone moldado em policarbonato faz desse alto-falante triaxial de 6 polegadas a escolha certa para quem busca precisão e suavidade nas faixas médias e agudas. Aliando potência e design, ele se destaca ainda pela capacidade de trabalhar com potência RMS 60 W. Informações: - Marca: Pioneer - Modelo: TS-1790BR Características principais: - Woofer com cone de IMPP (Polipropileno moldado por injeção) - Midrange de Ø30 mm com diafragma de policarbonato moldado - Suspensão boleada - Midrange com conjunto magnético de neodi?mio - Bobina de voz resistente ao calor - Tweeter piezoelétrico de Ø11 mm em PET Especificações: - Potência: 60W RMS - Resposta em frequência: 40 Hz a 20.000 Hz - Sensibilidade (1 W / 1 m): 86 dB - Impedância: 4 ohms Dimensões e peso: - Altura: 14 cm - Largura: 18 cm - Profundidade: 18 cm - Peso: 1,36 Kg Conteúdo da embalagem: - 1 par de alto-falantes - 8 parafusos - Certificado de garantia - Lista de postos de assistência técnica', 240.69, 240.69, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/4f896009aa84e400bec3ff5b601138fb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F12815007434', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46750627218', 'Smilingoods | Salmos | Livro Para Colorir', 'Smilingoods | Salmos | Livro Para Colorir Carismáticos, criativos, envolventes! Os personagens do Smilinguido e sua turma ganharam um livro para colorir cheio de contornos e detalhes inspirados no livro bíblico de Salmos. Um passatempo relaxante e edificante para todas as idades! Mergulhe em 20 ilustrações inéditas, com páginas serrilhadas - fácil para guardar e presentear, papel especial e traços únicos da formiguinha mais amada do Brasil!', 28.32, 28.32, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821ey-mghxo0c0prm6e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F46750627218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
