INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598739698', 'Líquido para Máquina de Fumaça 5 Litros Neutro Nevoa - Profissional', 'O Líquido Fog para Máquina de Fumaça da Névoa Líquidos, sinônimo de excelência, é o líquido de alta qualidade que você precisa para o seu evento! Próprio para Máquina de Fumaça, o Líquido Fog é totalmente seguro, sendo não inflamável e não tóxico, além de ser compatível com qualquer modelo de máquina de fumaça. Em embalagem resistente de 5 litros, o Líquido Fog é incolor e sua linha Profissional com o aroma Neutro é ideal para dar um tom agradável ao seu evento! Pronto para uso e perfeito para aniversários, festas de casamentos, DJ’s e demais eventos, não precisando ser diluído ou combinado com outros materiais. Com sua fumaça de alta densidade o Líquido Fog é excepcional para profissionais Light Designers como um meio para tornar visíveis os feixes de luz durante os eventos! Desenvolvido para proporcionar excelentes efeitos visuais, tornando a experiência do evento ainda mais impactante e divertida! Limite de 4 unidades por compra devido ao limite de peso. Caracteristicas Técnicas - Marca: Névoa Líquidos - Linha: Profissional - Modelo: Líquido Fog - Cor: Incolor - Quantidade: 5 Litros - Aromas: Neutro - Fumaça de alta densidade - Compatível com qualquer máquina de fumaça - Não diluir o produto ou misturar com outros materiais ou líquidos - Pronto para uso - Não é tóxico - Não é Inflamável - Limite de 4 unidades por compra - Acompanha Nota Fiscal - Dimensões: 28 cm x 19 cm x 13 cm - Peso: 5,400 kg', 80.0, 67.0, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/br-11134207-7qukw-ljek2wp7xtthb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F20598739698', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099203831', 'Kit 6 Fraldas Geriátricas Bigfral Derma Plus G com 7un cada', 'O Kit contém: 6 pacotes de Fraldas Geriátricas Bigfral Derma Plus G com 7un cada. A Bigfral DermaPlus foi desenvolvida para adultos com incontinência urinária severa. Possui o exclusivo sistema de proteção total da pele, com extratos naturais hidratantes que ajudam a prevenir irritações, mantendo a pele protegida e saudável, além de sistema antiodor, trazendo até 10h de proteção e cuidado.', 286.79, 220.69, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-7rcdi-lryk242mphcj4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1131442264%2F20099203831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
