INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42764388161', 'Livro Cartonado O Novelo de Emoções para os Pequeninos', 'Marta é uma menina que não sabe o que se passa com ela, mas seu amigo Sukha - com o apoio de um novelo de lã colorido e cheio de fios misturados -, vai ajudá-la a nomear suas emoções. _x000D_ Marta vai conhecer as emoções, descobrir suas mensagens e aprender a organizar cada uma no seu próprio novelo._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2025_x000D_ Autor: Elizabete Neves_x000D_ Ilustrador: Natalina Cóias_x000D_ Idioma: Português_x000D_ Páginas: 20_x000D_ Dimensões: L 20.00 x A 20.00 x E 1.30_x000D_ ISBN: 9786526118184_x000D_ Coleção: Novelo de emoções_x000D_ Linha Editorial: Ciranda na Escola - Literatura infantojuvenil_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Emoções, Inteligência emocional, Saúde emocional, Inteligência socioemocional, Cores, Descoberta, Aprendizado, Alegria, Medo, Tristeza, Raiva_x000D_ BISAC: Literatura Infantil / Literatura Infantil / Temas Sociais / Emoções e Sentimentos_x000D_ Linha de Produto: Cartonado_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Verniz de máquina_x000D_ Material: Cartonado', 39.9, 27.93, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdw2-mdp0z22utiwsd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F42764388161', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
