INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22299070675', 'Alicate Extra Longo De Pesca Para Tirar Anzol Garganta Peixe Bestfer', 'O Alicate Extra Longo de Pesca da marca Bestfer é a ferramenta ideal para pescadores que buscam eficiência e conforto. Com um comprimento de 11 polegadas(28cm), este alicate permite alcançar facilmente anzóis em locais de difícil acesso, garantindo uma experiência de pesca mais tranquila e segura. Fabricado em aço carbono, o modelo BFH 1956 oferece durabilidade e resistência, essenciais para o uso em ambientes aquáticos. Sua ponta reta é perfeita para a remoção de anzóis, enquanto o punho antideslizante e o cabo ergonômico proporcionam um manuseio confortável, mesmo em condições úmidas. Este alicate é uma adição indispensável ao seu equipamento de pesca, permitindo que você se concentre no que realmente importa: a captura do seu peixe. Invista em qualidade e praticidade com o Alicate Extra Longo de Pesca Bestfer e eleve sua experiência de pesca a um novo patamar.', 51.18, 37.37, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825ap-mg5425ip6z2i63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F22299070675', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897377234', 'Alicate Bico Meia Cana Reto Cromo Vanádio Com Isolação Até 1000v 7 Polegadas Para Eletricista Vonder', 'Olá, Bem vindo a Distribuidora Brester. Trabalhamos com uma grande variedade de ferramentas elétricas e manuais, descartáveis, eletroeletrônicos, artigos para casa, artigos de petshop e outros. Aqui você encontrará Produtos Originais, Nota Fiscal, Pronta Entrega e Envio Imediato! Informações do Produto: Alicate Bico Meia Cana Reto 7" Vonder O Alicate Bico Meia Cana da Vonder é a solução para quem busca qualidade, durabilidade e versatilidade. Foi projetado para resistir ao uso constante, acompanhando você por anos. Ideal para eletricistas, mecânicos e profissionais que demandam o melhor em suas ferramentas. Características: > Produzido em aço cromo vanádio, proporcionando maior durabilidade; > Possui cabo isolado para tensão de até 1000V e função para crimpagem; > Indicado para o manuseio de terminais em instalações elétricas e corte de fios e arames macios de no máximo 1,6 mm. Especificações Técnicas: > Material: aço cromo vanádio; > Comprimento aproximado: 177mm; > Acabamento: escurecido com faces polidas; > Tipo do cabo do alicate: cabo em borracha termoplástica, com isolação de até 1000V. - Marca: Vonder - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Nota fiscal para Pessoa Física e Pessoa Jurídica; - Produto novo, com garantia de fábrica; - Produto a pronta entrega; - Envio em até 24hs em dias úteis após confirmação do pagamento. Obrigado por escolher a Brester Máquinas.', 84.59, 78.52, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcfb-lskcv8gpvzyt02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F22897377234', NULL,