INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18499564179', 'Pedaleira Onix 13/19 Automático Aço Inox - Não fura o pedal', 'Gravação em relevo antiderrapante; Aparência esportiva e personalizada; Modelagem sob medida; Não fura os pedais originais; Instalação simples feita em minutos; ITENS INCLUSOS: 1 pedaleira para acelerador 1 pedaleira para freio DESCRIÇÃO: A textura do aço escovado e a gravação em baixo relevo aumentam a aderência dos pedais garantindo mais esportividade na pilotagem. A instalação é simples e pode ser realizada em poucos minutos, pois as pedaleiras são fixadas com fita-dupla face 3M de alta performance. Este método de fixação foi testado e aperfeiçoado exaustivamente até chegarmos numa fixação firme e duradoura, o que é imprescindível para um local com tanto atrito e movimento. Projetadas especificamente para instalação no Onix com câmbio automático, estas pedaleiras cobrem os pedais originais com perfeição. A sola dos seus calçados normalmente estão sujas, contendo todo tipo de sujeira, o que colabora para o rápido desgaste dos pedais do seu Onix. Por serem produzidas em aço inoxidável elas nunca perderão o brilho. Instale este conjunto de pedaleiras que além de proteger os pedais contra o desgaste também vai proporcional um visual realmente esportivo. VEÍCULOS COMPATÍVEIS: Chevrolet: • Onix 2014 Automático • Onix 2015 Automático • Onix 2016 Automático • Onix 2017 Automático • Onix 2018 Automático • Onix 2019 Automático DADOS TÉCNICOS PEDALEIRA: Matéria prima: aço inox 304; Espessura: 1,2 mm; Acabamento: escovado; Fita dupla face: 3M VHB; GARANTIA: 1 ano', 160.27, 160.27, NULL, 'Hobbies & Collections > Souvenirs > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdvi-m0258vity4mff2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1103244663%2F18499564179', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
