INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193636113', 'Pote Hermético Acrílico Com Tampa de Bico Copo Dosador E Alça Para Segurar', 'Pote Hermetico com Tampa Dosadora de 1800ml. Acrilico Resistente ============================================================= O Pote Hermético para Alimentos de 1,8L, com sua tampa dosadora e bico dispenser, representa a solução perfeita para armazenar uma variedade de itens de forma organizada e segura. Seja para mantimentos, cereais, farinhas, ração pet, sabão líquido, amaciantes de roupas ou outros produtos, este pote é a escolha ideal. Sua tampa possui um fechamento hermético com borracha de silicone, garantindo a vedação completa contra vazamentos, além de impedir a entrada de ar e poeira, prolongando a frescura dos itens armazenados ========================================================= CARACTERISTICAS: - Capacidade 1800ml - Material Acrílico - Plástico de alta qualidade - Produto atóxico - Tampa Dosadora', 54.99, 28.99, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4kj23yb0wg15d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1333507062%2F22193636113', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
