INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597777720', 'Tampa De Válvula Chevrolet Cruze Tracker Sonic 2012 13 14 15', 'Tampa de Válvula Chevrolet Cruze 1.8 16v 2012 a 2016, Sonic 1.6 16v após 2012 e Tracker 1.8 16v após 2013 Garanta a proteção e o desempenho ideal do motor do seu Chevrolet com esta tampa de válvula original, projetada para modelos Cruze, Sonic e Tracker dentro das especificações indicadas. Fabricada em material resistente e durável, essa tampa evita a entrada de sujeira e mantém a lubrificação interna, contribuindo para a saúde do motor e maior vida útil do veículo. Aplicação: CHEVROLET CRUZE 1.8 LT Flex 2011 A 2016 CHEVROLET CRUZE Hatch 1.8 Sport6 LT Flex 2011 A 2016 CHEVROLET SONIC Hatch 1.6 LT Flex 2012 A 2014 CHEVROLET SONIC Sedan 1.6 LT Flexfuel 2012 EM DIANTE CHEVROLET TRACKER 1.8 LTZ Flex 2013 A 2017 Especificações: Tipo: Tampa de Válvula Acompanha Junta: Sim Acompanha Tampa Óleo: Não Referência: GPTV003 Marca: Greenparts EAN: 7908374413354 Números Originais: 55564395 55558673', 319.9, 299.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhvvhjikkbnm3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F405317374%2F23597777720', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997067243', 'Textos cruéis demais para serem lidos rapidamente', 'O LIVRO DE FICÇÃO MAIS VENDIDO DE 2018Indo contra a tendência dos textos curtos e superficiais que são postados nas redes sociais, o coletivo literário Textos cruéis demais para serem lidos rapidamente (TCD) passou a produzir e compartilhar um conteúdo extenso, profundo e extremamente poético em suas páginas no Facebook e no Instagram. Com seus escritos e ilustrações, eles acabaram atingindo um público muito maior do que o esperado, nos mostrando como, apesar da crescente agilidade que nossa comunicação exige, ainda precisamos de tempo para digerir e entender nossas complexas relações humanas. Para este livro, foram produzidos textos inéditos que ganharam a companhia das sensíveis ilustrações de Anália Moraes.', 51.35, 51.35, NULL, 'Books & Magazines > Books > Others', 'https://cf.shopee.com.br/file/sg-11134201-7r9ah-ln7c6pf3ivq92d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23997067243', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52510916556', 'Caledrina cefyr e o arauto sujo', 'Em Caledrina Cefyr e o arauto sujo, a jovem guerreira não é mais uma garotinha. Após desvendar os segredos sobre a sua origem e conhecer o seu criador, Cally, aos 16 anos, se vê diante de responsabilidades e causas maiores do que ela mesma. “Ela iniciou uma revolta no povo ao segurar a mão do Vento, e, ao largá-la, iniciou outra revolta dentro de si.” Ao assumir o trono da rainha roxa, Caledrina precisará enfrentar o grande dilema da escolha. Sua verdadeira missão ou a coroa. Servir ou ser servida. O acampamento dos selvagens ou a Corte dos Sete. Estar na posição que foi criada para ocupar ou criar seu próprio caminho. A cada decisão, a garota tempestuosa terá em suas mãos não apenas o poder de decidir o seu futuro, mas o de todo um povo.', 57.44, 57.44, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-823rn-moigfwwl3klq66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F52510916556', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
