INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397647484', 'SHAMPOO PROTETOR E FORTALECEDOR – JOICO DEFY DAMAGE 300 ml', 'O Joico Defy Damage Protective Shampoo limpa suavemente os fios enquanto protege contra os danos diários causados por ferramentas térmicas, poluição e processos químicos. Sua fórmula rica e cremosa mantém a integridade da fibra capilar, preserva a cor e fortalece os cabelos desde a lavagem. ESPECIFICAÇÕES TÉCNICAS: Marca: Joico Cor: Branco perolado Textura: Cremosa Peso líquido: 300ml Origem: Importado (EUA) Indicação: Todos os tipos de cabelos, especialmente quimicamente tratados ou danificados Fórmula: Complexo SmartRelease™, óleo de moringa, arginina, lipídios protetores Ação: Limpeza suave com proteção contra danos diários Frequência de uso: Diário Tipo de uso: Profissional e home care Produto lacrado e com selo de originalidade Benefício: Limpa sem agredir a fibra capilar Benefício: Protege contra os danos térmicos, químicos e ambientais Benefício: Preserva a cor e fortalece os fios Garantia: Produto original com garantia de procedência CUIDADOS Evite contato com os olhos. Manter fora do alcance de crianças. Uso externo. Conservar em local seco e fresco.', 243.45, 153.38, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxsn94tq99jm60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F525611242%2F22397647484', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
