INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799681049', 'Tênis Coca Cola Iate City Preto - Masculino', 'Tênis Coca Cola Iate City Preto - Masculino Apresentamos o Tênis Coca Cola Iate City, uma escolha perfeita para quem valoriza estilo e conforto em um único calçado. Este modelo slip-on oferece praticidade e elegância, ideal para uso no dia a dia. Seu cabedal é confeccionado em material têxtil, proporcionando leveza e flexibilidade aos seus pés. O elástico nas laterais permite um ajuste confortável e seguro, garantindo praticidade no momento de calçar. Para facilitar ainda mais o calce, o tênis possui uma tira na parte traseira, proporcionando maior conveniência e agilidade ao vestir. Além disso, sua palmilha em EVA é personalizada e removível, oferecendo conforto extra e praticidade para higienização. A sola de borracha antiderrapante proporciona segurança e estabilidade em diferentes superfícies, permitindo que você caminhe com confiança em qualquer ambiente. Com um design moderno e versátil, o Tênis Coca Cola Iate City é a escolha perfeita para quem busca um calçado que alie estilo e conforto em todas as ocasiões. Adquira o seu e desfrute de toda a qualidade e praticidade que só a Coca Cola pode oferecer! FICHA TÉCNICA: Gênero: Masculino Indicação: Dia a dia Cabedal: Têxtil Cor: Preto Solado: Borracha Ajuste: Elástico Marca: Coca Cola Conteúdo da embalagem: 1 par de Tênis Coca Cola Iate City Preto - Masculino', 219.99, 170.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7reo9-m8kyv82yl70g69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F21799681049', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22899235724', 'Cera De Carnaúba Plus Automotiva 500ml Vonixx', '🚗 Carnaúba Plus 500ml – Proteção e Limpeza Premium ✨ Desenvolvida com a mais pura cera de carnaúba cearense, limpa, protege e promove brilho profundo. 🔎 Referências Compatíveis: 35305, 2009004 🏷️ Informações do Produto: 🏢 Marca: Vonixx 📝 Tipo: Proteção e Limpeza 🆕 Condição: Novo 💧 Estado Físico: Líquido viscoso 🟡 Cor: Amarelo 🛡️ Garantia: 90 dias ⚠️ Importante: Não recomendamos uso em pinturas (lataria), pois pode ocasionar manchas. 🛠️ Aplicações 🛡️ Forma camada protetora sobre verniz da pintura automotiva 💎 Proporciona brilho intenso e espelhado 🚗 Ideal para detalhamento automotivo (car detailing) 💦 Ação hidro-repelente: efeito “beading” – gotas escorrem com facilidade 🌟 Benefícios 🛡️ Proteção da Pintura: Raios UV, chuva ácida, poluição, fezes de pássaros e seiva 💎 Brilho Intenso: Efeito molhado (wet look), realce da cor 🧽 Facilidade na Limpeza: Repele sujeira, poeira e água 💦 Efeito Beading: Água escorre mais fácil, reduzindo manchas 🤲 Fácil Aplicação e Remoção: Fórmula líquida, sem resíduos difíceis 🔄 Versatilidade: Pintura, plásticos não porosos, cromados, vidros (com cuidado) ⏳ Durabilidade: Proteção por semanas, dependendo do clima e lavagens 🌱 Componente Natural: Cera de carnaúba – sustentável e brasileira 📝 Modo de Uso 🔄 Agite bem o produto antes de usar 🧴 Aplique pequena quantidade com aplicador de espuma, em movimentos circulares ⏳ Aguarde secar alguns minutos 🧽 Remova com toalha/pano de microfibra limpo e seco até obter brilho desejado 🛒 Adquira agora o Carnaúba Plus 500ml em uma de nossas Lojas Oficiais: Camillo Parts, Genuine Automotive ou Edumac Parts ✅ Produto de alta qualidade, com garantia e suporte que você merece ⚠️ Aviso de Direitos Autorais 🚫 Proibida a cópia, uso ou alteração de nossas fotos, imagens e conteúdo. 📜 Lei 9.610/98 – qualquer violação será tratada legalmente.', 57.23, 45.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Wax', 'https://cf.shopee.com.br/file/sg-11134201-820lv-mnobhjhx8b9f62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552175911%2F22899235724', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
