INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57502898024', 'Tênis Aramis Daily Slip Canvas Masculino Confortável Leve Casual Antiderrapante', 'Casual, prático e cheio de estilo para o seu dia a dia! Tênis Aramis Daily Slip Canvas - Masculino Parte superior do formulário Parte superior do formulário Ficha Técnica: Marca: Aramis Modelo: Daily Slip Canvas Gênero: Masculino Cores: Variadas Cabedal: Têxtil - canvas Palmilha: Eva e têxtil – anatômica, antibacteriana e removível Solado: Borracha antiderrapante Forro Interno: Têxtil levemente acolchoado Fechamento: Slip-on (com elástico para mais segurança e estabilidade) Lingueta: Integrada ao cabedal Detalhes: Acabamento refinado com costuras aparentes e estilo contemporâneo, detalhe em sintético na parte traseira, logotipo da marca na lateral, fácil de calçar e retirar O equilíbrio perfeito entre praticidade e elegância está aqui. O Tênis Aramis Daily Slip foi desenvolvido para homens que buscam conforto e estilo sem complicação. Porque investir: Seu design slip-on facilita o uso no dia a dia, dispensando cadarços e oferecendo ajuste prático. O cabedal em canvas proporciona leveza, enquanto o solado de borracha garante durabilidade e aderência. Ideal para acompanhar looks urbanos e composições casuais com um toque de sofisticação. Conteúdo da embalagem: 1 par de Tênis Aramis Daily Slip Canvas - Masculino Parte superior do formulário', 339.99, 185.99, NULL, 'Men Shoes > Slip Ons & Mules', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi4gbg1ce5mq1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F57502898024', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
