INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194260638', 'Kit de Escovas para Mamadeira e Bicos Esponja - Cinza', 'Kit Escovas para Mamadeira e Bico – Cinza Buba Higiene rápida, segura e eficiente para mamadeiras e bicos do bebê. O kit Buba conta com duas escovas – uma maior, com esponja na ponta, e uma pequena, específica para bicos – projetadas para alcançar cantinhos difíceis e garantir limpeza completa. Principais Características: - 2 escovas (mamadeira e bico) com cabo Cinza em polipropileno durável. - Esponja macia na ponta da escova maior para remover resíduos sem danificar. - Cerdas flexíveis e cabeça curva que se adaptam a diferentes formatos de mamadeiras. - Cabo com gancho para pendurar e secagem rápida. - Produto livre de BPA e ftalatos – seguro para uso diário. Modo de Uso: - Utilize a escova menor para limpar o interior dos bicos. - Use a escova maior com esponja para o interior das mamadeiras. - Enxágue bem com água corrente após cada uso. - Pendure para secar após a limpeza. Especificações Técnicas: - Material: cabo e cerdas em polipropileno, base em aço, esponja de alta qualidade. - Cores: cinza - Dimensões: escova grande ~23 cm; escova pequena ~12 cm. - Segurança: livre de BPA e ftalatos. - Conteúdo: 1 escova grande + 1 escova pequena. Buba – praticidade e segurança nos cuidados com seu bebê.', 15.88, 15.88, NULL, 'Mom & Baby > Feeding Essentials > Bottle-feeding', 'https://cf.shopee.com.br/file/sg-11134201-7rdwe-mcjay7weqczy89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22194260638', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52103786449', 'Tênis Osklen Drift Verde - Masculino', 'Estilo e sofisticação para qualquer ocasião! Tênis Osklen Drift Verde - Masculino Parte superior do formulário Ficha Técnica: Marca: Osklen Cor: Verde Gênero: Masculino Indicado: Eventos sociais, trabalho e passeios Cabedal: Têxtil com partes sintéticas Palmilha: EVA, removível para melhor higienização Solado: Borracha Fechamento: Cadarço Lingueta: Fina e flexível Estilo: Casual e social Detalhes: Listra grossa na lateral, puxador traseiro e parte traseira em material sintético texturizado Com design urbano e elegante, o Tênis Osklen Drift Verde é a escolha ideal para homens que valorizam estilo e conforto no dia a dia. Porque investir: Seu cabedal combina tecido têxtil e material sintético, criando um visual moderno com excelente respirabilidade. A palmilha em EVA removível facilita a limpeza e garante leveza nas passadas, enquanto o solado de borracha assegura aderência e durabilidade. Com uma listra lateral marcante e acabamento texturizado no calcanhar, esse modelo transita com facilidade entre compromissos profissionais e momentos de lazer. Conteúdo da embalagem: 1 par de Tênis Osklen Drift Verde - Masculino', 347.99, 272.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-81zv4-mipw6hs7z94ya9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F52103786449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
