INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399562184', 'Chumbinho Carabina pressão Viking 5.5 Precisão, penetração', 'O Chumbinho Teko Viking 5.5mm é ideal para atiradores que valorizam qualidade e precisão. Desenvolvido com materiais de alta pureza, cada unidade passa por rigorosos controles de qualidade, assegurando uma performance consistente. Seu acabamento refinado proporciona uma aerodinâmica superior, resultando em estabilidade durante o voo e impactos precisos no alvo. A combinação de precisão, penetração e grande desempenho torna este chumbinho uma escolha excelente para quem busca resultados superiores em suas atividades de tiro. Ficha Técnica - Quantidade: 145 unidades - Peso e Gramatura: 0,7g | 10,8 grains - Foco Específico: Precisão, penetração e grande desempenho - Calibre: 5.5mm (.22) - Fabricado no Brasil - Composto: Esfera feita em aço carbono com acabamento em zinco branco, corpo e saia em polipropileno, assentando perfeitamente nas raias do cano.', 100.15, 100.15, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rfh0-m3c3j0kwty8y87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078949207%2F20399562184', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
