INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094254501', 'Corrente Bicicleta Gts Fina Index Para 7 e 8 Velocidades 116 Elos Bike', 'CORRENTE FINA INDEX 7V E 8V 116 ELOS - GTS ESPECIFICAÇÕES: - Marca: GTS; - Origem: China - Modelo: G81i; - Medida: 1/2"x3/32" - 116L (elos); - Material: Aço; - Indicado: SPEED, MTB, URBANO, PASSEIO; - Compatível: 6, 7 e 8 Velocidades; - Configuração Relação: 3x8v, 2x8v 1x8v / 3x7v, 2x7v, 1x7v / 3x6v, 2x6v, 1x6v; - Acompanha PINO de conexão; - Medida: 116 Elos / Links; - Peso Aproximado: 320g; - Acabamento em Níquel especial de alta durabilidade - Tratamento DHA (chromiun carbid treatment) maior durabilidade - Cor: Cinza - Compatibilidade: SHIMANO/ Campanolo / SRAM 6-7-8 velocidades; - Indexada para 6-7-8v (serve em todos Cassetes de 7v e 8v); PRODUTO DISPONÍVEL A PRONTA ENTREGA, ENVIO IMEDIATO!!! PRINCIPAIS BENEFÍCIOS: A corrente GTS tem um excelente custo x benefício e utiliza fechamento com PINO de emenda. Corrente indicada para uso em bicicleta de estrada (SPEED), bicicleta de montanha (MTB), bicicleta recreativa ou bicicleta de uso URBANO. Esse modelo é exclusivo para relações de 6v, 7v e 8v e segue com 116 elos. Sendo compatível com todas as combinações de coroas TRIPLA, DUPLA ou coroa ÚNICA com catraca ou cassete Mega Range de 34 dentes. ATENÇÃO: - Acompanha embalagem Original; - Acompanha PINO de conexão, NÃO segue com power link.', 24.4, 24.4, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdyk-mcm3d78piyszbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F23094254501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693265483', 'Fogão 4 Bocas Dako Diplomata com Grill', 'Fogão Dako Diplomata Grill tem design moderno e sofisticado que eleva a experiência de cozinhar! Além do design moderno com frente total em vidro, o novo fogão conta com uma série diferenciais: timer digital, exclusiva testeira anti-residuos em vidro temperado removível, mesa de vidro temperado com recorte frontal, grades de ferro fundido quadradas com 8 pontos de apoio, puxador de alumínio escovado, pés robustos e semi-embutidos e botões ergonômicos. O forno possui excelente capacidade de 60 litros, grill e dourador elétrico, acabamento limpa fácil, 1 grade autodeslizante e 1 deslizante e porta com vidro duplo que preserva o calor. Características: 4 Bocas Tipo de Acendimento - Superautomático Acabamento da Mesa - Vidro Temperado Fogão de Piso Grill Funcionamento - Gás Capacidade do Forno - 60 Litros Acabamento do Forno - Limpa Fácil Luz no Forno Vidro do Forno - Vidro Duplo Trempes - Individual de ferro fundido com 8 pontos de apoio 1 Grade autodeslizante 1 Grade deslizante Timer Digital Botões Removíveis 3 Queimadores - Semirrápidos de 1,7kW 1 Queimadores - Rápido de 3,0kW Sistema Corta/Bloqueia Gás Comprimento do Cabo de Energia - 96 cm Dimensões Internas do Forno (LxAxP): 37 x 36 x 45 cm Dimensões: Altura: 93,7 cm Largura: 51,5 cm Profundidade: 65 cm Peso: 32,00 kg Garantia do fornecedor de 12 meses', 2399.9, 2079.9, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-7rdw9-lzulnb8a07kyca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F22693265483', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
