INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193587087', 'Diurético Furolisin 20mg Cães E Gatos C/ 10 Comprimidos', 'Produtos 100% Originais e Lacrados de Fabrica Contém Nota Fiscal e Envio Imediato Furolisin 20mg Para Animais: Tratamento Diurético Eficaz para Cães e Gatos -Procurando um diurético confiável para seu pet? Furolisin 20mg é a escolha certa para o tratamento de edema em animais. Desenvolvido por veterinários, nosso Furolisin ajuda a aliviar o inchaço e a retenção de líquidos em cães e gatos, proporcionando alívio rápido e seguro. Benefícios do Furolisin 20mg para Seu Animal de Estimação: -Alívio do Edema: Furolisin 20mg reduz efetivamente o inchaço causado por condições cardíacas, hepáticas e renais. -Dosagem Segura: Precisamente formulado para uso animal, cada comprimido contém 20mg de furosemida. -Fácil de Administrar: Comprimidos pequenos e fáceis de misturar com a comida do seu pet. -Recomendado por Veterinários: Confie em um produto que profissionais de saúde animal recomendam. -Qualidade Garantida: Fabricado seguindo as mais rigorosas normas de qualidade, e com nota fiscal TODOS OS NOSSOS PRODUTOS SÃO LACRADOS E CONTÉM NOTA FISCAL. O ENVIO SERÁ IMEDIATO', 26.9, 19.9, NULL, 'Pets > Pet Healthcare > Vitamins & Supplements', 'https://cf.shopee.com.br/file/sg-11134201-7rfge-m3pfyb0ml1uq00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F23193587087', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
