INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20457524262', 'Kit 02 Banquetas Banco Plástico Resistente Suporta Até 100Kg Tramontina', 'Esse anúncio contém: Jogo de 2 Banquetas. Principais dúvidas: O produto é original Tramontina? Sim. É resistente? Sim. A banqueta é estilosa, ergonômica e resistente. Ideal para ser usada em vários ambientes, tanto residenciais quanto públicos.Produto monobloco, empilhável, compacto, leve, fácil de limpar e transportar. São confortáveis e resistentes. Design moderno. Produto aditivado com anti-Uv, ou seja, resistente aos raios solares.Resiste a uma carga estática de até 100 kg. Benefícios: - Leve - Fácil de limpar e transportar. - ergonômica e resistente. - Design moderno. - Benefícios de Acordo com as Especificações do Produto. Informações: Dimensões Produto (AxLxC): 33cm x 33cm x 45cm. Peso máximo suportado: Até 100kg. Material: Polipropileno. Fabricante: Tramontina. - Produto novo e em estoque; - As cores do tecido ou produto podem variar de acordo com o lote de fabricação; - Todos os produtos têm seguro contra extravio.', 99.9, 79.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgp40r1v32th91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F365257077%2F20457524262', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994290814', 'Vestido Infantil Menina Com Babados Colorittá Amarelo', 'O Vestido Colorittá é o must-have da estação! Confeccionado em tecido tricoline, que oferece conforto e leveza para o dia a dia, ele possui modelagem soltinha e mangas curtas formadas por babados. Além disso, a estampa em puff com linhas geométricas garante um destaque estiloso ao look e o fechamento em botões nas costas facilita o vestir. Ótima opção para ocasiões mais arrumadas, como aniversários e almoços de domingo, aposte nessa peça atemporal para deixar o visual ainda mais lindo!', 199.9, 199.9, NULL, 'Baby & Kids Fashion > Girl Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-825ab-mr1thap7xcee50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F22994290814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794803980', 'Conjunto Infantil Menina Laço de Pérolas Colorittá Rosa', 'O Conjunto Colorittá é composto por blusa e short em malha texturizada. A blusa possui mangas curtas amplas com detalhe franzido e aplicação delicada de pérolas em formato de laço, trazendo um toque charmoso ao look. Já o short conta com elástico no cós e detalhe em pregas. Além disso, a textura diferenciada em ambas as peças dá um destaque especial ao conjunto. Ideal para passeios e momentos de lazer, aposte nesse visual que une sofisticação e conforto para deixar as meninas ainda mais lindas!Detalhes da peça: • Conjunto composto por blusa e short • Feito em malha texturizada • Possui mangas curtas amplas • Aplicação de pérolas em forma de laço • Elástico no cós • Ideal para passeios e momentos de lazer', 149.9, 74.95, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8258j-mr1tn6vzwcue1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F23794803980', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262624448', 'Jaqueta Masculina Lotus Inter Skuba Hood Esporte 2026 Preto', 'A Jaqueta Masculina Lotus Inter Skuba Hood Esporte 2026 Preto combina visual esportivo, conforto e praticidade para acompanhar a rotina com mais estilo. A proposta é ideal para quem busca uma peça versátil para o dia a dia, com a identidade do clube em destaque e um caimento estruturado. Confeccionada em tecido plano com 95% poliéster e 5% elastano, a peça oferece toque macio e estrutura confortável. O material remete à textura do neoprene, característica que reforça a proposta Skuba e entrega isolamento térmico leve para os dias de temperatura mais amena. A Jaqueta Lotus Inter conta com capuz, fechamento principal em zíper e bolsos frontais invisíveis funcionais com fechamento em zíper. Os punhos e a barra em ribana canelada ajudam no ajuste ao corpo e deixam o visual mais alinhado para a rotina. Os detalhes discretos no tecido, em tom cinza na parte frontal e nas mangas, acrescentam mais personalidade ao modelo sem perder a versatilidade. O brasão do time no peito completa a peça com identidade marcante, transformando a jaqueta em uma opção prática e estilosa para diferentes momentos do dia. As Lojas Radan contam com 10 lojas físicas no Rio Grande do Sul, oferecendo esta e uma grande variedade de produtos e marcas de calçados e vestuário feminino, masculino, infantil e esportivo. Compre online com entrega rápida para todo o Brasil ou em uma de nossas lojas físicas, aproveitando nossa experiência e adquirindo produtos de qualidade. Aproveite! Produto de autenticidade garantida vendido pelas Lojas Radan. A cor do produto nas fotos pode sofrer alteração em decorrência do uso do flash ou da configuração do seu monitor. Características: Nome do produto: Jaqueta Masculina Lotus Inter Skuba Hood Esporte 