INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599128120', 'Coifa Tbox Parede Brastemp 90cm Inox - BAE90AR', 'A coifa Tbox de parede Brastemp 90cm combina design moderno e alto desempenho, garantindo a remoção eficaz de fumaça, odores e gordura. Esta coifa Brastemp oferece fácil manutenção, operação silenciosa e tecnologia avançada que garante eficiência no dia a dia. Ideal para cozinhas planejadas, a coifa proporciona ambiente limpo e confortável, unindo praticidade, durabilidade e estilo. Com acabamento refinado, esta coifa Brastemp transforma a rotina da cozinha, proporcionando funcionalidade e elegância em cada uso.', 3839.0, 3839.0, NULL, 'Home Appliances > Large Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259b-mr1yz1n8lpfp67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1648122739%2F23599128120', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
