INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294876579', 'Tênis Olympikus Beats Unissex', 'Tênis Olympikus Beats Unissex - O Olympikus Beats é o tênis ideal para quem busca estilo para os seus corres diários. O seu solado possui dupla camada da Tecnologia Evasense, que proporciona conforto e amortecimento. Conta também com estabilizador traseiro em material injetado, com a Tecnologia Supporter que proporciona maior estabilidade nas passadas. Visual em detalhes brilho, fosco. Já o cabedal é feito em Tecido Jacquard bicolor, que proporciona respirabilidade, flexibilidade e leveza. Conta com vista e logotipo em high frequency com detalhes de cor e relevo. Possui ainda atacador e forro em poliéster, lingueta em tecido jacquard bicolor, puxador traseiro em fita na horizontal para auxiliar no calce e palmilha anatômica composta por tecido poliéster e EVA, com aplicação gráfica. TECNOLOGIA:SUPPORTER -A tecnologia da Olympikus com estabilizador para uma pisada mais segura. EVASENSE- A tecnologia da Olympikus em EVA para máxima maciez e conforto absoluto. Características Gerais do Produto: • Gênero: Unissex Garantia: • 7 dias de garantia', 299.0, 299.0, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-8262l-mls4lq5d3uv5dd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1172340783%2F23294876579', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
