INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18366431289', 'Eletrodo 3,25mm 6013 OK 46.13 (Embalagem com 5KG) ESAB', 'Eletrodo Serralheiro 3,25 MM 6013 OK 46.13 Caixa 5,0 KG ESAB Especial para trabalhos em serralheria. Eletrodo rutílico de uso geral em todas as posições de soldagem e juntas, mesmo sem preparação. Aplicável em estruturas metálicas, construções em geral e chapas galvanizadas. Apresenta manejo fácil, arco estável, baixas perdas por respingo, escória de fácil remoção. Produz cordões de excelente acabamento. Apresenta fácil abertura de arco, o que torna seu emprego muito adequado para ponteamento. Especial para trabalhos em serralheria. Metal depositado: C=0,06 / Si=0,20 / Mn=0,35 Comprimento do bastão: 350mm Diâmetro: 3,25mm Faixa de corrente: 85-160(A) Caixa com 5KG Embalagem fechada: 5 Kg Valor divulgado da embalagem de eletrodo. * Imagens meramente ilustrativas.', 168.9, 168.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134201-820lx-mqxgrnj1fhmu12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F18366431289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
