INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898131136', 'Deo Colônia Masculino Imortal 15ml - Amakha Paris', 'Imortal é a fragrância que traduz força, confiança e conquista. Inspirada no icônico Invictus, essa deo colônia une notas amadeiradas e aquáticas para criar uma essência marcante, moderna e sedutora. Perfeita para o homem que sabe o que quer e não tem medo de alcançar grandes vitórias. ✅ Família Olfativa: Amadeirado Aquático Notas Olfativas: • Topo: Notas oceânicas, toranja e mandarina • Corpo: Folha de louro e jasmim • Fundo: Âmbar cinzento, madeira guaiac, musgo de carvalho e patchouli Indicações de Uso: ✔️ Quando usar: Dia e Noite ✔️ Ocasiões: Social ou Sedução ✔️ Perfil: Homem comunicativo, confiante e determinado Por que escolher o Imortal? ✅ Fragrância inspirada no Invictus ✅ Tamanho prático (15ml) para levar no bolso ou nécessaire ✅ Ideal para o homem moderno, confiante e sedutor ✅ Perfume versátil: combina com qualquer ocasião', 50.0, 32.5, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-8259g-mq833sltrv9e8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1454161052%2F23898131136', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
