INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793965665', 'Organizador multinivel extensível Ou Linha Clear', 'O Organizador Multinível Extensível Clear 25 x 29-54 x 10,3cm é o novo padrão de transparência na organização. Organize em níveis e enxergue facilmente o conteúdo, mantendo tudo em ordem.Seu design foi pensado para permitir diversas composições e proporcionar máximo aproveitamento de espaço nos ambientes. Produzido em material resistente o organizador possui alças confortáveis que facilitam na hora do transporte. Na despensa Ou na cozinha, no quarto Ou na lavanderia, a linha clear é indispensável para auxiliar você na organização da sua casa. INFORMAÇÕES TÉCNICAS Dimensões: LxAxP: 29x11x25 cm. Material: PS (Poliestireno) + PP (Polipropileno) CUIDADOS Sugere-se higienizar com sabão neutro e esponja macia, evitando produtos abrasivos no processo de limpeza. Não é recomendado colocar o material na lava-louças. CONTEÚDO DA EMBALAGEM 1 Organizador Multinível Extensível Clear 25 x 29-54 x 10,3cm SOBRE NÓS Somos apaixonados pelo que fazemos e utilizamos o design como meio de fazer você se sentir em casa onde estiver. Criamos produtos com carinho e cuidado para atender as suas necessidades diárias, levando bem-estar, aconchego e conforto para seu lar. Somos minimalistas e funcionais pois queremos que você tenha um estilo de vida mais leve e organizado, para atingir o máximo do seu potencial. Prazer, somos Ou.', 109.9, 109.9, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rfia-m9hut1nl3v0g21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1477305422%2F22793965665', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
