INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898199367', 'Massa Corrida Pva 3,6L - Suvinil', 'Nome : Massa Corrida Pva 3,6L - Suvinil Marca: Suvinil Modelo: Suvinil Massa Corrida Volume: 3,6L Rendimento Acabado: 18m² Superficie: Parede Base: Água Tempo Secagem: 3Horas Aerosol: Não Ambiente: Interno Massa Corrida da Suvinil Ajuda a dar um acabamento mais caprichado e a deixar sua parede mais lisa. Indicada para ambientes internos e secos, a massa corrida é fácil de aplicar e de lixar. Ela ainda cria uma camada branca que facilita na hora de pintar. É a massa por trás de uma boa pintura. Benefícios Excelente rendimento Aplicável com: rolo, desempenadeira e airless Fácil de aplicar e lixar Informações Técnicas Demãos 2 a 3 demãos Acabamento Não informado Secagem Ao toque: 40 minutos Entre demãos: 3 horas Final: 4 horas Marca Suvinil Dimensões 1.4 Kg: 11cm x 12cm x 11cm Peso 1.4 Kg: 1.404kg Diluição Pronta para uso. Se necessário, adicione até 1,5L de água por lata com 28Kg e homogeneize bem. Aplicar em camadas finas até obter o nivelamento desejado. Para aplicação com airless dilua com até 10% de água potável e aplique com pressão entre 1800 e 2200 psi. Use bico com abertura de 0,025” e a velocidade de aplicação entre 5 e 9 m2/min. Rendimento Branco e cores 1.4 Kg - 4.4m² acabados.', 112.89, 112.89, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rcdv-m65iiq6vx2frf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717380864%2F22898199367', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
