INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598639868', 'Garrafa de Agua Caramanhola para bike Squeeze com Suporte para exercicios', 'Caramanhola Garrafa de agua para bike Isotermica A Caramanhola Isotérmica Possui um sistema de isolamento isotérmico que reflete o calor ao invés de absorvê-lo, além de uma parede dupla e vedação para não entrar ar quente fazendo com que a água conserve gelada por até 2 horas. Seu bico articulável possui trava anti gotejamento. Sua boca larga facilita tanto o abastecimento com água quanto a higienização total da garrafa de forma prática e fácil. É feita de Polipropileno, que garante excelente qualidade e um designer perfeito para a hora de pegar a squeeze. Por ser flexível é possível aumentar o fluxo da água apertando a garrafinha. Livre de BPA e sem gosto. Itens da Embalagem: 1 Garrafa Isotérmica 600ml Ptk 1 Suporte para Bicicleta Preto 2 Parafusos para fixação do suporte Dimensões da Garrafa e Suporte ! Especificações Garrafa: Altura da Garrafa: 27 cm Largura: 7 cm -------------------------------------------------------- Especificações Suporte: Material : Nylon resistente Altura: 15cm Largura: 8cm Acompanha 2 parafusos para instalação do suporte. Resistente e FÁCIL de Instalar ! Já vem com os 2 parafusos para instalação ! Super leve ! Imagens meramente ilustrativas, Na compra desse produto você está adquirindo somente 1 Garrafa Isotermica (Cor a desejar) e 1 Suporte com parafusos, Demais imagens são apenas ilustrativas ! DUVIDAS FREQUENTES: TEM A PRONTA ENTREGA? R: Sim, Temos todos nossos produtos em estoque para pronta entrega! QUANDO É POSTADO O MEU PEDIDO ? R: Despachamos suas compras em menos de 24 horas Após a Liberação do Pedido ! Exceto aos finais de semana e Feriados. Caso tenha dúvidas nos consulte no chat antes de efetuar a compra, estaremos a disposição para lhe atender o mais rápido possível.', 25.55, 25.55, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7ratd-maurtpq2mwsw8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22598639868', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
