INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998363807', 'Chave de Impacto Makita 12V TW141 CXT 1/2" C/ 2 Baterias 1.5Ah Compacta Profissional Original - Sem Carregador', 'DISTRIBUÍDO POR C-JAÚ FERRAMENTAS NÃO ACOMPANHA CARREGADOR Chave De Impacto Com 2 Baterias 12v Cxt 1.5ah 1/2" Tw141 Makita Sem Carregador Chave de Impacto TW141DZ 12V CXT é ideal para trabalhar em espaços reduzidos e aplicações em zonas elevadas. Possui velocidade variável (0-2.600 RPM e 0-3.200 IPM) para uma ampla variedade de aplicações. Design ultra-compacto com bateria para reduzir a fadiga do operador. Luz LED integrada ilumina a área de trabalho. Conveniente entrada de 1/2" para rápida mudança. Martelo e bigorna Makita criados com materiais como o aço da melhor qualidade e endurecidos com calor, para maior durabilidade da ferramenta. Empunhadura ergonômica, que adapta-se perfeitamente à mão para maior comodidade e controle. - Especificações Técnicas: - Tensão da bateria: 12 V - Tipo de bateria: CXT - Rotações por minuto: 0 - 2.600 Rpm - I.p.m: 0 - 3.200 ipm - Par máx. de aperto: 145 Nm - Capacidade máx. de parafuso: M6 - M12 - Inserção: 1/2" - Velocidade variável (interruptor) - Travão elétrico - Iluminação integrada - Dimensões (CxLxA): 168 x 66 x 224 mm - Peso: 1,1 Kg - Emissão de vibração: 7,50 m/seg² - Incerteza da vibração: 1,50 m/seg² - Pressão sonora: 93,00 dB(A) - Potência sonora: 104,00 dB(A) - Incerteza (k) sonora: 3,00 dB(A) NÃO ACOMPANHA CARREGADOR ACOMPANHA: 1- CHAVE DE IMPACTO A BATERIA 1/2" TW141DZ 12V MAKITA 2- BATERIAS DE LITIO 12 VOLTS 1.5 AH BL1016 MAKITA', 689.0, 675.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m869hdp3nz01dd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F23998363807', NULL, NULL, '2026-07-28T02:11