INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51753905314', 'Capuccino Com Canela', 'Deliciosa combinação de café solúvel, leite em pó e cacau com o toque quente e aromático da canela. De textura cremosa e sabor marcante, é ideal para preparar uma bebida reconfortante e cheia de personalidade, perfeita para qualquer hora do dia. Ingredientes: Açúcar, soro de leite em pó, composto lácteo, café solúvel, canela em pó, cacau em pó alcalino, regulador de acidez INS 500(ii) antiumectantes: INS 341(ii) e INS 551 e espessante goma xantana. ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN, LEITE, SOJA, AMENDOIM E CACAU POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. - EMBALAGEM MERAMENTE ILUSTRATIVA.', 24.88, 24.88, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/br-11134207-81ztc-miu9wpxj64n70c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F51753905314', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393403131', 'Alfafa 1Kg', 'Planta alimenticia não convencional (PANC) Usos culinários: A alfafa é amplamente utilizada na culinária, especialmente em saladas, sanduíches e wraps, onde suas brotações frescas adicionam crocância e um sabor suave. Além disso, suas folhas secas podem ser usadas em chás e infusões, proporcionando um toque nutritivo. Rica em vitaminas e minerais, a alfafa também é valorizada por suas propriedades benéficas à saúde. Nome Científico: Medicago sativa Parte utilizada: Aérea Origem: Nacional', 35.09, 35.09, NULL, 'Food & Beverages > Beverages > Tea & Tea Bags', 'https://cf.shopee.com.br/file/br-11134201-820lq-mqxmcb75vv2d0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F22393403131', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23927786625', 'Noz Moscada Pó', 'A noz-moscada em pó tem aroma intenso e sabor levemente adocicado e picante. Usada em pequenas quantidades, é ideal para temperar purês, molhos, massas, doces e bebidas quentes como chás e cafés. Ingredientes: Noz moscada. ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN, LEITE, SOJA, AMENDOIM E CACAU POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. - EMBALAGEM MERAMENTE ILUSTRATIVA.', 41.44, 41.44, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqtc3nt7f94z59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F23927786625', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
