INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18141562836', 'Saida de Praia Short Curto em Poliester Soltinho com Abertura Lateral da Mash She Lingerie', 'Short She Feminino Beachwear Abertura Lateral Ref: SH38401. Com o objetivo de maximizar o conforto e a segurança nos seus momentos de lazer, a She Lingerie (Mash) criou um short da linha moda praia. Este é feito de poliéster suave e solto, com aberturas laterais para maior liberdade de movimento, cintura com elástico para um ajuste seguro, e um design moderno e estiloso para desfrutar do verão. Adequado para todos os tipos de corpo, o short pode ser usado como saída de praia ou piscina sobre biquínis e maiôs, em atividades esportivas de baixo impacto ou mesmo para montar um look de verão despojado. - Cintura com elástico. - Abertura lateral - Secagem rápida. - Pingente Delicado com Logo. Tamanhos: P M G GG Composição: Poliéster 92% Elastano 8%', 39.99, 39.99, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lym7t32badude9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308601970%2F18141562836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
