INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21197924488', 'Capa Anti Impacto Ultra Fina AZ Para Galaxy S23 Ultra', '• Capa AZ Ultra Fina desenvolvida para Galaxy S23 Ultra de 6.8 polegadas. • Feita de Policarbonato de alta qualidade com acabamento fosco e toque emborrachado que proporciona uma textura confortável ao toque. • Design confortável, leve e super fino que protege sem adicionar volume ao celular. • Se encaixa perfeitamente no celular, com recortes precisos que garantem fácil acesso a todos os botões e funcionalidades do smartphone. • Botões responsivos e fáceis de apertar. • Possui bordas elevadas para garantir proteção para a tela e a câmera do celular. As cases da AZ estão entre as melhores do mundo. Não utilize produtos químicos abrasivos para higienizar a Capa, inclusive álcool. O álcool é abrasivo e pode remover o verniz e a tinta da Capa.', 59.99, 49.9, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcalr3oalo8b22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442913304%2F21197924488', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
