INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23193491919', 'Mini Mochila Stitch - Disney', 'Vai viver um dia cheio de aventuras e momentos especiais e precisa de uma mochila que te acompanhe em todas as horas? A gente te ajuda! Feito em tecido sintético, possui um bolso principal para você carregar o que não pode faltar no seu dia a dia! O produto é importado, feito em tecido sintético, possui detalhes incríveis que vão fazer você se apaixonar! Se você gosta de se aventurar durante o seu dia a dia e precisa de uma mochilinha que encare tudo, a gente te ajuda! Com um bolso principal que conta com um compartimento extra para você guardar as coisas menores que não podem faltar nas suas aventuras! Com uma alça confortável, tem o tamanho perfeito para as coisinhas mais necessárias! Não importa onde é o rolê essa mochila te acompanha em todos os lugares! Especificações: Altura: 25m| Largura: 20cm| Comprimento: 10cm| Material: Poliéster| Bolsos: 1 Principal Cuidados e recomendações de uso: Não exceder peso máximo suportado. Limpar com pano úmido. Não passar. Não alvejar.', 354.9, 354.9, NULL, 'Men Bags > Backpacks', 'https://cf.shopee.com.br/file/sg-11134201-82609-mjirzo6yj1fk33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F23193491919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23893000949', 'Tesoura Suiça Para Poda Galhos Plantas Jardim Profissional 21,5cm Collins', 'Tesoura de Poda Collins 21,5cm- Ferramenta popular e confiável entre jardineiros e profissionais da área. Conhecida por sua qualidade e durabilidade, essa tesoura é ideal para uma variedade de tarefas de poda, desde pequenos arbustos até galhos mais grossos. Informações Técnicas: Marca: Collins; Garantia: 36 Meses; Material: Aço Carbono; Diâmetro de corte: 19mm. Diâmetro de Corte: 19mm, ideal para uma ampla gama de tarefas de poda; Trava de Segurança: Impede acidentes, garantindo que a tesoura permaneça fechada quando não estiver em uso; Cabo Anatômico: Oferece conforto e segurança durante o uso, reduzindo o cansaço nas mãos, mesmo em trabalhos prolongado; Lâminas de Aço Carbono: Garantem cortes precisos e limpos, minimizando danos as suas plantas e promovendo uma cicatrização mais rápida; Estrutura Robusta: Confeccionada em materiais de alta qualidade, a tesoura Collins é resistente e durável, suportando as exigências do dia a dia. Para que serve a tesoura de poda Collins: Poda de formação: Dar forma e tamanho desejados às plantas; Preparo de arranjos florais: Cortar caules e flores com precisão; Poda de limpeza: Remover galhos secos, doentes ou danificados; Poda de frutificação: Estimular a produção de frutos em árvores frutíferas. Dimensões Aproximadas: Altura: 2,5 cm; Largura: 7 cm; Comprimento: 21,5 cm.', 49.9, 38.0, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdx8-m17g1fzltrke3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F23893000949', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
