INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997747467', 'Cadeirinha para Auto I-Nxt 360º Grey Urban - Safety 1 St', 'Instalação exclusivamente ISOFIX + Top Tether nos grupos 0+ e 1 (verificar a compatibilidade do veículo antes da compra) Com rotação 360° real, mesmo após instalada, a i-NXT 360° da Safety 1st facilita o dia a dia dos pais e acompanha o crescimento da criança desde o nascimento até os 36 kg. Possui instalação com Isofix, redutores para os menores, ajustes de inclinação e proteção lateral, unindo conforto e segurança em todas as fases. Conheça suas características: -Sistema Easy Rotation 360° permite o giro real, mesmo após instalada -Para todas as fases, de 0 a 36kg -Aprovada pela norma ECE R129 i-Size -Proteção lateral de impactos, tecnologia SafeSide® -5 posições de inclinação, livremente ajustáveis, mesmo instalada -Redutor acolchoado desmontável, com formato adaptável ao crescimento -Cintos de 5 pontos ajustáveis simultaneamente ao apoio de cabeça -Aprovada pelo Inmetro Especificações: -Cor: Grey Urban -Reclinável: 5 Posições. -Grupos: 0+, 1, 2 e 3 -Isofix: SIM+ Top Tether, de frente ou de costas ao movimento -Material: 100% Poliester, HDPE, Ferro -Idade Indicada: 0 a 36kg -Peso: 11,500kg -Dimensões: (A x L x P | cm) 44 x 57 x 55,4 cm -Garantia: 12 meses (Garantia Padrão) + 12 meses (Garantia Estendida*) -Conteúdo da embalagem: 1 cadeirinha e 1 manual *Registre seu produto no site e ganhe 12 meses de garantia estendida. *Todos os produtos possuem Nota Fiscal Eletrônica.', 2199.0, 2199.0, NULL, 'Mom & Baby > Baby Travel Essentials > Car & Motorbike Seats', 'https://cf.shopee.com.br/file/sg-11134201-81zu0-midegdl2vm6a1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207408200%2F23997747467', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598192547', 'Pneu 265/70R17 LT 10 Lonas 121/118S Brutus TA Xbri', 'Pneu 265/70R17 LT 10 Lonas 121/118S Brutus TA Xbri O pneu Xbri Brutus T/A chegou para revolucionar o mercado de pneus off-road para caminhonetes. Com letras brancas preenchidas, carcaça LT e laterais bem reforçadas, ele foi feito para entregar durabilidade excepcional. Excelente tração em pisos irregulares por conta dos sulcos profundos da banda de rodagem. Performance e design de ponta por um preço muito menor do que o mercado cobra por produtos similares. Marca: Xbri Modelo: Brutus TA (borrachudo) Aro: 17 Índice de peso (por pneu): 121 - 1450 kg Índice de peso (rodado duplo): 118 - 1320 Kg Índice de velocidade: S - 180Km/h Construção: Radial Tipo: sem Câmara Aplicação: Todo terreno Tipo de desenho: Simétrico Lateral: Letras brancas Este pneu possui letras brancas. Para protegê-las durante o armazenamento e o transporte, o fabricante aplica uma película protetora na cor azul sobre as inscrições. Por isso, o produto poderá ser recebido com as letras aparentando ser azuis. Basta remover a película protetora para revelar as letras brancas originais do pneu.', 1069.82, 1069.82, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rep9-m20wm1y8orcv51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1173721007%2F22598192547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
