INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11270977130', 'Sete Necessidades Básicas Da Criança', 'Boa alimentação, educação de qualidade, plano de saúde, roupas, brinquedos, passeios, todas essas coisas têm o seu valor no desenvolvimento de uma criança, e pais e mães amorosos jamais negligenciam esses cuidados. No entanto, para que a criança se torne um adulto feliz e responsável, você também precisa se concentrar nas necessidades de sua alma. É isto o que o autor deste livro propõe a você: ajudar a desenvolver o caráter da criança e prepará-la para a vida adulta, tornando-a mais segura, disciplinada e, acima de tudo, temente a Deus.Número de Páginas 144', 24.9, 24.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/1a0cfbf50b67e43ab10b47bf92a7aad4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F11270977130', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40959337835', 'Comentário do Antigo Testamento | Cântico dos cânticos | Tremper Longman III', 'Comentário do Antigo Testamento | Cântico dos cânticos | Tremper Longman III Por toda a Bíblia, o relacionamento com Deus é descrito pela metáfora do casamento. Como com toda metáfora, o leitor deve observar uma reticência apropriada no que diz respeito a forçar a analogia. Entretanto, no Cântico aprendemos sobre a intensidade emocional, a intimidade e a exclusividade de nosso relacionamento com o Deus do universo. Da Introdução Os relacionamentos são uma parte maravilhosa, misteriosa, muitas vezes indescritível, às vezes dolorosa, da experiência humana. O mais íntimo de todos os relacionamentos humanos, de acordo com a Bíblia, é aquele entre um marido e uma esposa. Não é surpresa, portanto, que haja um livro da Bíblia, o Cântico dos Cânticos, que enfoque esse relacionamento. O que surpreende é quão pouca atenção seja dada ao Cântico dos Cânticos pelos estudiosos, pela igreja e pelos leitores da Bíblia. Com este volume, Tremper Longman III descompacta para as pessoas modernas o que este antigo poema de amor diz sobre a relação homem-mulher e, por analogia, sobre o amor de Deus por seu povo. Autor: Tremper Longman III Editora: Cultura Cristã Acabamento: Capa comum brochura Dimensões: 14 cm larg. x 21 cm alt. Número de páginas: 288', 64.9, 64.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdwx-mcgo0vbq7yvi5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F40959337835', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
