INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58255651934', 'Lola Cosmetics Eu Sei o Que Você Fez na Química Passada - Spray de Tratamento 250ml', 'Spray de tratamento para cabelos quimicamente tratados. Lola Cosmetics Eu Sei o Que Você Fez na Química Passada recupera os fios danificados e fortalece. Lola Cosmetics Eu Sei o Que Você Fez na Química Passada te ajuda a potencializar o tratamento do cabelo danificado e fragilizado pela química. Ainda promove uma carga proteica de aminoácidos que recupera o fio e protege dos mais agressivos procedimentos. Liberado para as técnicas de No e Low Poo, ele também restaura a fibra capilar e ainda confere aumento da massa capilar enquanto equilibra o nível de hidratação. Como usar: Aplique uma pequena quantidade em toda a extensão dos fios, após o uso do Shampoo da linha ou após os processos de descoloração ou coloração e deixe agir por 5 minutos. Não enxágue. Finalize o tratamento com a Máscara Eu Sei o Que Você Fez na Química Passada. Dica: Ao descolorir ou colorir o cabelo, adicione uma pequena quantidade do spray na mistura de pó descolorante/oxidante ou coloração para minimizar os danos. O processo ficará mais lento, porém deixará o cabelo mais saudável. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 59.9, 59.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8261f-ml2ap7in4npj90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58255651934', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
