INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294877048', 'Bruna Tavares BT Skin L50 - Base Líquida 40ml', 'Base líquida com acabamento aveludado. Bruna Tavares BT Skin garante uniformidade aliada a um efeito natural, além de oferecer benefícios de skincare. A Base Bruna Tavares BT Skin possui textura ultrafluida e cobertura leve a média com incrível acabamento de “segunda pele”, permitindo a construção de camadas, sem pesar. Sua fórmula atua como tratamento antissinais, proporcionando mais firmeza e elasticidade para a pele. Ela traz ativos que protegem a degradação do colágeno e estimulam sua produção natural, e uma boa dose de Ácido Hialurônico, mantendo a pele hidratada e prolongando a duração da maquiagem. Além disso, Bruna Tavares BT Skin confere ação contra a luz azul, protegendo as células da luz visível emitida pelas telas de computadores, celulares e tablets. Assim, evita o surgimento de marcas, o envelhecimento precoce e aumenta a energia celular, restaurando a vitalidade da pele. Essa base da Bruna Tavares conta com uma fórmula hipoalergênica, não comedogênica, livre de parabenos, vegana e não testada em animais. Ou seja, a melhor composição para a sua pele! **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 91.9, 91.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-8262a-mkk2a8z9meiqbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F22294877048', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
