INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497658789', 'Painel Festa Junina Decoração Arraia com Sanfona Fogueira Fogos Balões 140 cm', 'Itens inclusos 1 Painel em T.N.T Dimensões: 1,40 M de largura x 1,03 M de altura Detalhes do produto: Produto: Produto Novo, na embalagem. Material: T.N.T Cor: Multicolorido Produto Original Produto Licenciado e certificado pelo INMETRO Produto a pronta entrega! Transforme sua festa junina em um verdadeiro arraiá com nosso vibrante Painel Arraiá Multicolorido! Com 1,40 metros largura, este painel é o complemento perfeito para sua decoração, trazendo todo o charme e alegria das festas juninas. Celebre o São João com estilo e autenticidade! Tema: Festa Junina Quantidade: 1 painel Tamanho: 1,40 M de largura x 1,03 M de altura Design: Multicolorido, com padrões típicos de festa junina, como bandeirinhas e balões Material: T.N.T resistente e durável Fácil de aplicar Ideal para: Decoração de festas juninas, arraiás, eventos escolares e aniversários Versatilidade: Pode ser usado em ambientes internos e externos Destaque sua festa: Adicione um toque festivo e autêntico ao seu evento junino', 26.9, 26.9, NULL, 'Home & Living > Party Supplies > Backdrops & Banners', 'https://cf.shopee.com.br/file/sg-11134201-8259t-mqxg7q5bde6fbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F18497658789', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20198108210', 'Anilha Injetada Com Furo 31mm 5 a 20 kg Peso De Academia Emborrachada Para Barra E Halter Musculação', 'Anilhas Injetadas de Ferro Fundido Revestido com Grossa Camada de Borracha: O Equipamento Essencial para Quem Leva o Treino a Sério Quando falamos em treino de força, seja em academias profissionais, estúdios personalizados ou home gyms de alto nível, a escolha dos equipamentos faz toda a diferença, e entre eles, as anilhas injetadas de ferro fundido revestidas com grossa camada de borracha se destacam como um investimento inteligente, durável e seguro. Por que escolher esse modelo? Simples: elas unem o melhor dos dois mundos. Ferro Fundido no Núcleo: a base metálica garante robustez estrutural, resistência ao impacto e estabilidade no encaixe com as barras de musculação, sejam elas maciças, olímpicas ou ocas. Diferente de outras anilha, como as de concreto ou 100% borracha, essas mantêm o padrão profissional exigido em ambientes de alta performance. Revestimento com Borracha Injetada de Alta Densidade: não se trata de uma cobertura superficial, a borracha é grossa, resistente e moldada com precisão, oferecendo proteção contra impactos, absorção de ruídos e preservação do piso. O resultado é uma anilha que dura mais e entrega uma experiência superior durante os treinos. Se você está montando um espaço profissional ou quer elevar o nível do seu home gym, investir em anilhas de ferro fundido revestidas com borracha não é luxo, é estratégia para ter bons produtos no seu treino por anos e anos. Quem treina com seriedade sabe, equipamento de qualidade muda o jogo, e com a MegaGym você conta com toda garantia necessária. Benefícios Reais para Quem Treina Sério: • Durabilidade superior — ideal para uso intenso e frequente; • Segurança aumentada — evita lascas, rachaduras e desgaste precoce; • Pegada firme e visual imponente; • Compatível com treinos funcionais, musculação clássica, levantamento olímpico e cross training. Características: • Material: Estrutura De Ferro Fundido; • Revestimento: Grossa Camada De Borracha Injetada; • Com 2 Áreas De Pegadas; • Diâmetro Do Furo Central: 31mm; • Modelo: Anilha Injetada De Academia Furo 31mm; Garantia do vendedor: 3 meses', 186.85, 117.8, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8npe1h2k3k21c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F867949056%2F20198108210', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
