INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897668056', 'Botão de Emergência Pisca Alerta - GM 1241646 - 90181853 e 93213042 - DNI 2109', 'Botão de Emergência Pisca Alerta - GM 1241646 - 90181853 e 93213042 - DNI 2109Descrição do ProdutoEste Botão de Emergência Pisca Alerta é um componente essencial para garantir a segurança do seu veículo. Com o modelo "Interruptor", possui uma ficha técnica completa para atender às suas necessidades. Atributos do Produto Marca: DNI Modelo: DNI2109 Número de Peça: DNI2109 Detalhes TécnicosEste botão de emergência opera com uma tensão de 12V e conta com 8 terminais para uma conexão segura e eficiente. Com códigos equivalentes da GM (1241646, 90181853, 93213042) e compatibilidade com veículos Monza, Kadett e Ipanema fabricados entre 1993 e 1996, você terá a certeza de estar adquirindo um produto de qualidade e confiabilidade. BenefíciosO Botão de Emergência Pisca Alerta DNI2109 oferece uma solução prática e segura para situações de emergência, garantindo que você esteja sempre preparado para qualquer eventualidade no trânsito. Sua instalação fácil e rápida torna este componente indispensável para a manutenção preventiva do seu veículo. Adquira já o seu Botão de Emergência Pisca Alerta DNI2109 e dirija com tranquilidade e segurança!', 116.36, 116.36, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rd49-ltzls7vy7h1ddc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972460632%2F18897668056', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55404794291', 'Sandália Piccadilly Taila Salto Baixo Off White', 'Sandália Piccadilly Salto Baixo 590079 Com design moderno e linhas delicadas, o modelo traz um salto baixo superestável, ideal para quem deseja praticidade sem abrir mão do estilo. Seu cabedal é desenvolvido em material macio e flexível, que abraça os pés com suavidade. O calce é confortável desde o primeiro uso, graças ao acabamento Super Conforto e ao forro acolchoado. A palmilha anatômica proporciona apoio extra, enquanto o solado leve e antiderrapante garante segurança ao caminhar. Versátil e charmosa, combina perfeitamente com looks casuais ou sociais, sendo uma excelente opção para trabalho, passeios e ocasiões que pedem conforto prolongado. Altura do salto - 3cm Atenção: As imagens podem sofrer variações de cor dependendo da configuração do dispositivo utilizado para visualização.', 259.9, 149.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-82610-mjk8hxjr6dc6ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F420274591%2F55404794291', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
