INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793396542', 'Chocolate Individual Branco Zero Lactose Linea - 15 unidades de 30g', 'Linea Chocolate Branco Zero Lactose é sem adição de açúcares. Adoçado com sucralose e maltitol, contém 169kcal por porção. Com a manteiga de cacau como o 1º ingrediente, resulta em um chocolate macio, cremoso e baixo em sódio. Sabor indescritível que derrete na boca! 1 Kit Composto por: - Chocolate Individual Branco Zero Lactose Linea 30g - 15 unidades INGREDIENTES manteiga de cacau, leite em pó integral, soro de leite desmineralizado, gordura vegetal, fibra de milho solúvel, colágeno, edulcorantes: maltitol e sucralose, umectante: polidextrose, emulsificantes: lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E SOJA. CONTEM LACTOSE.', 194.39, 184.67, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-7rdvy-m0uy7xto95s488', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365822827%2F23793396542', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
