INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29337034555', 'Vestido de Festa Junina Infantil pra Menina Xadrez Preto de Luxo Neon', 'Itens inclusos:01 - Vestido Xadrez Preto e Branco Dimensões do produto: Tamanho TAM - 2: Altura 88 cm / Busto 51 a 52 cm / Cintura 51 a 52 cm / Quadril 53 a 54 cm TAM - 4: Altura 105 cm / Busto 55 a 57 cm / Cintura 55 a 57 cm / Quadril 57 a 61 cm TAM - 6: Altura 117 cm / Busto 58 a 62 cm / Cintura 58 a 59 cm / Quadril 62 a 65 cm TAM - 8: Altura 128 cm / Busto 64 a 67 cm / Cintura 60 a 61 cm / Quadril 66 a 72 cm TAM - 10: Altura 137 cm / Busto 68 a 71 cm / Cintura 62 a 63 cm / Quadril 73 a 78 cm TAM - 12: Altura 150 cm / Busto 72 a 75 cm / Cintura 64 a 65 cm / Quadril 79 a 84 cm TAM - 14: Altura 156 cm / Busto 76 a 78 cm / Cintura 66 a 67 cm / Quadril 85 a 88 cm TAM - 16: Altura 158 cm / Busto 79 a 82 cm / Cintura 68 a 69 cm / Quadril 90 a 92 cm Ficou na dúvida de qual tamanho escolher? Sempre indicamos a escolha de um tamanho maior pois é mais fácil fazer um ajuste, caso necessário. E por ser para criança, a fantasia irá durar por mais tempo conforme ela for crescendo. Especificações TécnicasMaterial: : Poliéster. Cor: Preto. Produto a pronta entrega! Produto original! A Fantasia Junina Vestido Xadrez Preto Infantil é a escolha ideal para quem busca um visual autêntico, divertido e cheio de cor para as festas de São João. Com design inspirado nas tradições caipiras, o vestido traz uma paleta ousada de preto, branco, verde neon e rosa, mesclando tecidos com estampas xadrez e poá que encantam pelo contraste e pelo charme. A modelagem rodada e o acabamento com rendas e babados dão um toque lúdico e animado para a brincadeira e as apresentações escolares. O corpete estruturado com detalhes de fitas e laços coloridos proporciona conforto e firmeza, enquanto a saia volumosa, com camadas em tule e acabamento em renda, garante movimento e presença. O decote arredondado e as mangas babadinhas completam o visual com graciosidade. Ideal para crianças que adoram dançar quadrilha, brincar e se destacar nas festas juninas com um look vibrante e estiloso. Tule e renda Estampa xadrez preto e branco Babados e fitas Rendas coloridas Camadas rodadas Diversas idades Modelagem infantil Ajuste confortável OBS.: Tiara não inclusa. Apenas vestido incluso', 199.88, 199.88, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-825al-mq2sus870b9c25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1064041628%2F29337034555', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19148972869', 'Educador Sanitário Para Cães Pet Clean Xixi Stop 500 Ml', '"A LeluPets nasceu de uma paixão e dedicação de aproximadamente 20 anos de experiência nessa área tão incrível. Desde o início de nossa história, já são mais de 100 mil clientes atendidos. Estamos aqui determinados em fazer a diferença, democratizando e simplificando o cuidado com o seu pet para oferecer a melhor experiência para você e seu amiguinho. Mantemos nossas orelhas em pé, atentos às novidades do mundo pet para trazê-las até você. Nós somos apaixonados por pets! O seu pet é também da nossa família! Educador Sanitário para Cães Pet Clean Xixi Stop 500 ml Produto desenvolvido para cães. Fórmula desenvolvida para evitar com que o animal urine em locais indesejáveis. Utilizado para adestrar o animal indicando quais lugares onde não deve urinar ou defecar. Seu odor não é perceptível ao nosso olfato, e repele apenas os animais sem prejudicá-los - Indicado para cães; - Ensina onde os animais não devem fazer suas necessidades; - Pode ser utilizado com pets de todas as idades, - Disponível em embalagem de 500 ml."', 22.9, 15.9, NULL, 'Pets > Litter & Toilet > Others', 'https://cf.shopee.com.br/file/80cb958bf833c867e40edc11766a3079', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F19148972869', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19298101404', 'PORTA JOIAS ENVELOPE SUEDE ROSE PIUKA', 'A Carteira Porta Riveira, a escolha perfeita para elevar a experiência de presentear e cuidar das suas semijoias. Desenvolvida com atenção aos mínimos detalhes, esta carteira combina elegância e funcionalidade, refletindo a sofisticação e o carinho que colocamos em cada peça. Para quem deseja uma solução prática e charmosa para guardar suas semijoias, esta carteira porta Riviera é a escolha ideal. Detalhes: - Modelo Envelope. - Tecido Suede externo com forro de courino interno. - Cartela interna com 2 botões. - Tamanho: 13 x15.', 71.88, 71.88, NULL, 'Fashion Accessories > Hair Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-7renp-m82gpuqijiyoe3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F762167039%2F19298101404', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898392205', 'Car Flush Car 80 Limpeza Motor Pré Troca Óleo 400ml Original - Remove Borra Cárter', 'CAR FLUSH CAR80 – Limpeza Interna do Motor Antes da Troca de Óleo Mantenha o motor mais limpo, protegido e preparado para receber o óleo novo. O Car Flush CAR80 foi desenvolvido para remover borras, resíduos e impurezas acumuladas no sistema de lubrificação, ajudando a melhorar o desempenho e a eficiência do motor. APLICAÇÃO / COMPATIBILIDADE Indicado para motores Gasolina, Etanol, Flex, Diesel e GNV Uso antes da troca de óleo Compatível com motores leves e utilitários Aplicação direta no óleo velho do motor DADOS TÉCNICOS Tipo: Limpador interno de motor Função: Remoção de borras, gomas e resíduos Aplicação: Cárter e sistema de lubrificação Uso recomendado: Antes da troca de óleo Modo de uso: Adicione o produto ao óleo velho Deixe o motor em marcha lenta por 10 a 15 minutos Não acelere o motor Drene o óleo e substitua o filtro antes de colocar o óleo novo BENEFÍCIOS Ajuda a remover sujeiras acumuladas no motor Melhora a circulação do óleo novo Auxilia na redução de resíduos no sistema Fórmula com aditivos protetores Não agride juntas e retentores em bom estado Aplicação prática e rápida RECOMENDAÇÕES IMPORTANTES Utilize conforme as instruções do fabricante Recomendado realizar a troca do filtro de óleo após a aplicação Produto indicado para limpeza preventiva do motor Em caso de dúvidas, consulte um profissional especializado antes da aplicação', 36.5, 34.67, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7repp-m8ntgc6ta4rm4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1424408486%2F23898392205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093255197', 'Oleo Johnson''s Baby Puro 200ml', 'O Óleo Puro JOHNSON''S® Baby 200ml foi desenvolvido com óleo mineral de alta qualidade para manter a umidade natural da pele. Possui fórmula transparente e emoliente que hidrata e amacia, suavizando as partes ásperas e ressecadas do corpo. Ideal para massagear o bebê, o óleo ajuda na remoção de pequenas crostas e cascões na cabeça e orelha do bebê, além de prevenir contra assaduras e irritações na pele.', 57.59, 57.59, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-7rdxo-lzfmx69d0lxia2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22093255197', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297678362', 'Lacrifilm 5mg Solucao Oftalmica 10ml', 'LACRIFILM é indicado para o tratamento da melhora da irritação, ardor e secura dos olhos, que podem ser causadas pela exposição ao vento, sol, calor, ar seco, e também como protetor contra irritações oculares. É Também indicado como lubrificante e re-umidificante durante o uso de lentes de contato para aliviar o ressecamento, irritação, desconforto e coceira. PARA MAIS INFORMAÇÕES CONTINUE LENDO A BULA.', 38.78, 38.78, NULL, 'Health > Personal Care > Eye Care', 'https://cf.shopee.com.br/file/sg-11134201-7rdwj-lyinm1nf4lc759', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F23297678362', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
