INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14496815041', 'Jogo Vela Dafra Horizon Roadwin 250 Cb 650f Hornet Cbr 600 900rr Fireblade 1100xx Blackbird 2005 2006 2007 2008 2009 2010 2011 2012 2013 2014 2015 2016 Original Ngk Iridium', 'Jogo Vela de ignicao NGK Iridium para motocicletas. Valor referente ao jogo (04 velas) Aplicacoes: - Dafra Horizon 250 2013-2017; - Dafra Roadwin 250R 2012-2015; - Honda CB 600F Hornet 2005-2016; - Honda CB 650F 2015-2020; - Honda CBR 1100XX Blackbird 1997-2000; - Honda CBR 600F 1991-2000; - Honda CBR 600F 2012-2015; - Honda CBR 900RR Fireblade 1992-2000. A linha de velas Iridium possuem a ponta do eletrodo de Iridio que e um metal extremamente duro e altamente resistente ao desgaste. Desta forma e possivel diminuir o diametro do eletrodo central da vela que pode variar de 0,4 a 0,6mmm. Esta caracteristica especial propicia uma melhor ignibilidade da vela, ou seja a centelha ocorre de maneira muito mais facil. Vantagens das velas de Iridium: - Melhor performance; - Maior vida util. Especificacoes Tecnicas - Vela de Iridium; - Gap de 0,9mm; - Codigo do fornecedor: CR9EHIX-9 Observacao: - Valor referente ao jogo (04 velas)', 299.9, 291.89, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7qveq-lf5qywxlqwmned', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F969248320%2F14496815041', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497736077', 'Hirudoid Pomada 3mg 40g', 'HIRUDOID POMADA está indicado para processos inflamatórios localizados como: Manchas roxas (hematomas) que aparecem após traumas ou contusões, ou após cirurgias; Inflamação nas veias superficiais (flebites ou tromboflebites), após injeção de medicamentos numa veia ou punção de uma veia para colher exames de sangue. Também está indicado para auxiliar o tratamento nos seguintes casos: Varizes nas coxas e pernas, com ou sem feridas abertas; Em casos de inflamação dos vasos linfáticos ou linfonodos (linfangites ou linfadenites) que ocorre, por exemplo, na erisipela; Em furúnculos; Nas mamas (mastite). PARA MAIS INFORMAÇÕES CONTINUE LENDO A BULA.', 45.66, 45.66, NULL, 'Health > Medical Supplies > First Aid Supplies', 'https://cf.shopee.com.br/file/sg-11134201-7rdx2-lyin8m4epn9ic5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F20497736077', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
