INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22220368927', 'Tomilho Especiaria', 'O tomilho é uma erva aromática muito utilizada na culinária para adicionar sabor e fragrância a diversos pratos. Com um sabor levemente picante e terroso, é ideal para temperar carnes, sopas, molhos, e até legumes. Também é uma erva muito presente na culinária mediterrânea e em pratos de longa cocção, pois seu sabor se intensifica com o tempo. Ingredientes: Tomilho. ALÉRGICOS: PODE CONTER TRAÇOS DE GLÚTEN POR CONTAMINAÇÃO CRUZADA. INFORMAÇÕES ADICIONAIS - PODE HAVER VARIAÇÃO DE COR DEPENDENDO DO LOTE. - EMBALAGEM MERAMENTE ILUSTRATIVA.', 26.81, 26.81, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/br-11134207-820m6-mqjbaoy6iwowda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F22220368927', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
