INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498933993', 'Fluido Para Freio E Embreagem Dot 4lv Classe 6 Tirreno', 'Apresentamos o Fluido Para Freio E Embreagem Dot 4lv Classe 6 da marca Tirreno, um produto de alta qualidade e confiabilidade, desenvolvido para garantir a máxima eficiência do seu veículo. Este fluido de freio é ideal para todos os tipos de sistemas de freio e embreagem que requerem um fluido DOT 4. O Fluido Para Freio E Embreagem Dot 4lv Classe 6 Tirreno é produzido no Brasil, garantindo um produto de alta qualidade e confiabilidade. Com um volume de 500 mL, este fluido é suficiente para uma aplicação completa, garantindo a máxima eficiência do seu sistema de freio e embreagem. Este fluido de freio não é inflamável, proporcionando uma maior segurança durante a sua aplicação. Além disso, o Fluido Para Freio E Embreagem Dot 4lv Classe 6 Tirreno atende aos mais altos padrões de qualidade, garantindo a máxima eficiência e segurança para o seu veículo. Invista na segurança e eficiência do seu veículo com o Fluido Para Freio E Embreagem Dot 4lv Classe 6 Tirreno. Um produto de alta qualidade que garante a máxima performance do seu sistema de freio e embreagem. Garantia do vendedor: 7 dias', 39.0, 39.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf2w610asbnq7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1463940101%2F23498933993', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
