INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19819837310', 'Mamadeira Super Evolution Magia 300ml 6m+ Azul – Lillo', 'Mamadeira Super Evolution Magia 300ml Azul – Lillo A Mamadeira Super Evolution Magia 300ml Lillo foi especialmente projetada com o formato de frasco mais acinturado e fácil de pegar para auxiliar as crianças a segurar mamadeira. Sua abertura mais larga facilita a limpeza e o preparo dos alimentos. O bico redondo em silicone macio e flexível contém uma área maior de apoio para os lábios durante a alimentação. Sua tampa antivazamento fecha de forma eficaz e mantém o bico protegido durante o transporte. Livre de BPA. O MINISTÉRIO DA SAÚDE ADVERTE: A CRIANÇA QUE MAMA NO PEITO NÃO NECESSITA DE MAMADEIRA, BICO OU CHUPETA. O USO DE MAMADEIRA, BICO OU CHUPETA PREJUDICA O ALEITAMENTO MATERNO. Principais Características: - Bico Tamanho 2 (6m+) - Cores Alegres, estampas divertidas - Fácil de limpar - Livre de BPA - Bico em silicone redondo - Com tampa Antivazamento, bocal largo - Capacidade: 300ml Especificações Técnicas: - Conteúdo da Embalagem: 1 Mamadeira 300ml – Tamanho 2 - Material/Composição: Polipropileno - Garantia: 90 Dias (Contra Defeito de Fabricação Pelo Fabricante) - Certificação Inmetro: CE-PUR /IQB-000632 - Referência do Fabricante: 624921 - Cód. EAN: 7896033211086 - Lillo Fotos ilustrativas! Cores e modelos podem variar conforme fabricação.', 37.9, 37.9, NULL, 'Mom & Baby > Feeding Essentials > Bottle-feeding', 'https://cf.shopee.com.br/file/998a6898bcd77f08e9a74d5debacf3fc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340054154%2F19819837310', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
