INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18772641307', 'KIT NOVEX RECONSTUTOR MAX KERATIN', 'Esse KIT contém:1- Creme de Tratamento Novex Queratina Absoluta 400G1- Reconstrutor Novex Max Keratin Para todos os tipos de cabelos. AÇÃO Age penetrando profundamente e garantindo uma rápida absorção pelos fios, fortalecendo sua estrutura e revitalizando-os poderosamente. ATIVOS Queratina Brasileira Hidrolisada. BENEFÍCIOS Tratamento Reconstrutor Novex Recarga de Queratina Brasileira 80G Hiperativado, fórmula concentrada, resultado imediato, força, saúde e resistência. Reconstrutor Novex Max Keratin 250ML Fórmula concentrada. Resultado imediato. RESULTADO Cabelos fortes, resistentes e saudáveis. MODO DE USO Tratamento Reconstrutor Novex Recarga de Queratina Brasileira 80G Ritual para Cabelos Secos Com os cabelos úmidos, aplique o produto nos cabelos da raiz às pontas. Sem enxaguar, penteie de acordo com a sua preferência. Para um melhor resultado, finalize com prancha ou escova e aplique o reparador de pontas Nutrire Queratina Brasileira. Cabelos Oleosos: Com os cabelos úmidos, aplique nos cabelos da raiz às pontas, deixe agir por 15 minutos e enxágue. Você pode potencializar a ação do produto utilizando uma touca térmica. Após o seu passo a passo, enxágue os cabelos retirando o produto. Para um melhor resultado, finalize com prancha ou escova e aplique o reparador de pontas Nutrire Queratina Brasileira. Reconstrutor Novex Max Keratin 250ML Ritual: Após lavar os cabelos com o shampoo Vitay, com os fios ainda úmidos, coloque uma pequena quantidade de Novex Max Keratin. Deixe agir por 15 minutos. Enxágue abundantemente, condicione ou faça um tratamento mais completo de hidratação com o Novex Queratina Brasileira Creme de Tratamento Ultraprofundo 1 Kg. Frequência de Uso: 1º mês usar 1 vez na semana. No 2º mês usar a cada 15 dias. A partir do 3º mês, usar a cada 30 dias.', 37.0, 37.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-820m7-mnwyt17igpoh25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719923009%2F18772641307', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
