INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20498274756', 'Babador Bandana Loupiot Temas Flores Dupla Face', 'Babador Bandana Loupiot Temas Flores O Babador Bandana Loupiot Temas é uma escolha prática e estilosa para os pequenos. Feito em flanela e com botão, é fácil de ajustar. Sendo dupla face, oferece versatilidade no uso. A estampa fofa adiciona um toque encantador, tornando-o não apenas funcional, mas também um acessório adorável para o visual do bebê. Este babador não apenas simplifica a rotina dos pais, mas também é uma opção sustentável, pois sua durabilidade e facilidade de limpeza evitam o desperdício de babadores descartáveis. Com o babador, as refeições do bebê se tornam mais práticas e agradáveis, contribuindo para uma experiência mais tranquila. Informações Adicionais: Tamanho: Único Cores: Rosa Referência: 523705 Marca: Loupiot Temas', 19.9, 19.9, NULL, 'Mom & Baby > Feeding Essentials > Bibs', 'https://cf.shopee.com.br/file/sg-11134201-7rdws-mcgtxn3f45z4a5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F20498274756', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
