INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42219945886', '[Single-use] NUMBUZIN No.9 Eye Cream', 'CREME DE OlhoS VOLUMIZANTE] Um creme para os olhos perolado e rico que firma visivelmente A pele e suaviza o visual de linhas finas e rugas. Olhos escuros revitaliza olheiras de aparência cansada e reviva sub-olhos inchados para uma aparência mais brilhante e jovem. Formulado com NAD+, um poderoso ingrediente anti-envelhecimento que suporta a produção de colágeno e reparação da pele, juntamente com 50 tipos de peptídeos para aglomerar e firmar a pele. A ceramida nutre e fortalece a pele Retinol suaviza a pele e reduz o visual das rugas, enquanto a ceramida nutre e fortalece a área delicada dos olhos. A niacinamida ilumina círculos escuros e rejuvenesce toda a área dos olhos restaurando a vitalidade e o brilho. [CLINICAMENTE TESTADO] Clinicamente comprovado para melhorar 5 tipos de rugas oculares (pezinhos da crow, linhas sub-olhos, linhas profundas entre olhos e bochechas, linhas internas dos olhos e rugas das pálpebras superiores) enquanto restaura volume e elasticidade ao oco Áreas sub-olhos. O visual mais brilhante reduz visivelmente os círculos escuros, hiperpigmentação e descoloração para um visual mais brilhante e refrescante em apenas 4 semanas. Todos os tipos de pele [RECOMENDADOS PARA] Todos os tipos de pele. Especialmente eficaz para rugas, linhas finas, olhos que se cansam, olhosidade, especialmente eficazes para rugas, linhas finas, olheiras, olhos que brilham cansados, oleosidade sub-olho, bolsas para os olhos, inchaço, flacidez, flacidez da pele e perda de elasticidade e firmeza. [PRO DICA] Par Creme para os olhos no 9 com remendos para os olhos no 9 para maximizar a elevação e firmeza! Remendos para os olhos no 9 do local do olho no 9 em cima das áreas onde você aplicou o creme para os olhos no 9. Pele visivelmente, e revitalizada Use consistentemente para ameixador visivelmente, mais volumizada e pele revitalizada.', 17.63, 17.0, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/sg-11134207-824i2-metnbtu1syrl64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F42219945886', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42615397570', 'mixsoon PDRN Collagen Serum, 30mL', 'mixsoon PDRN Collagen Serum, 30mL ✨ Hydration + Firmness in One Drop ✨ 🌸 Key Benefits 💧 Deep Hydration – PDRN + Hyaluronic Acid lock in long-lasting moisture 🌟 Firm & Elastic Skin – Collagen helps improve skin resilience ✨ Bright & Radiant Tone – With Niacinamide & Honey Extract 🧴 Lightweight Serum – Absorbs fast, non-sticky 🌿 Main Ingredients PDRN (Salmon DNA extract) – Repairs & strengthens skin Collagen – Boosts firmness & elasticity Niacinamide – Brightens dull skin tone Hyaluronic Acid + Honey Extract – Deep, soothing hydration 💡 Recommended For Dry & dehydrated skin Dull skin that lost elasticity Skin needing anti-aging daily care Anyone who wants a natural, healthy glow 🧴 How to Use 1. After cleansing & toner, apply 2–3 drops on the face. 2. Gently pat until absorbed. 3. Follow with moisturizer.', 119.68, 114.0, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/sg-11134207-824i5-mdxzpkpd1vr80a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F42615397570', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093014115', 'Protetor Solar Facial Avene Mat Perfect Fluido Clareador cor Media FPS70 40g', 'Avène Mat Perfect é um protetor solar em forma de fluido clareador com FPS 70 e alta proteção contra os danos causados pelos raios UVA e UVB. Ele oferece ação clareadora, prevenindo e uniformizando manchas e matificando a pele por até 12 horas. Desenvolvido especificamente para as peles brasileiras, o protetor solar Avène Mat Perfect conta com uma textura leve com toque aveludado e uma fórmula com o poderoso complexo clareador e antioxidante HMC + Dextran.', 106.47, 106.47, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-7rd4s-lvaqlxte8uvlf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22093014115', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993241009', 'Fotoprotetor Facial Isdin Fusion Water FPS50 Cor Clara 50ml', 'Fusion Water Color Cor Clara é um protetor solar facial com cor. Graças à sua fórmula ultraleve, protege diariamente a pele contra os raios UVB e UVA (FPS 50). Proporciona uma cobertura natural que disfarça imperfeições, uniformiza o tom da pele e proporciona controle de oleosidade. O melhor? Não irrita os olhos.', 128.69, 128.69, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-7rdyk-lzfkeht05fucff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22993241009', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
