INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694544081', 'Máquina de Lavar Consul 18Kg Branca com Lavagem Econômica e Ciclo Edredom - CWK18AB', 'Para famílias grandes, soluções poderosas! Chega de passar o dia todo lavando roupa. Com a Lavadora Consul 18kg, você resolve a lavanderia da semana de uma só vez. Ela foi bem pensada para dar conta de tudo, até do seu edredom King Size, que sai limpinho e bem cuidado com um ciclo especial. A economia aqui é inteligente e em dobro. O copo dosador exclusivo te ajuda a acertar na medida e economizar até 70% de sabão. E que tal economizar água também? Com a função de Reúso, você aproveita a água da lavagem para limpar a casa, cuidando do seu bolso e do planeta. É a Consul unindo máxima capacidade com a economia e a praticidade que sua família precisa para ter mais tempo livre. Bem pensado, né?', 2229.99, 2229.99, NULL, 'Home Appliances > Large Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-82591-mqf2hh8llkhuf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1623409915%2F22694544081', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894155011', 'Combo Jogo da Memória Infantil Animais da Floresta + Memorix Ratinhos', 'Combo Educativo com 2 Jogos - Super Memória Animais e Memorix Ratinhos Diversão garantida para as crianças enquanto desenvolvem memória, concentração e raciocínio lógico! 🎁 O que vem no kit: ✅ 1x Super Memória Animais (vários bichinhos fofos) ✅ 1x Memorix Ratinhos (super divertido!) 👶 Indicado para: crianças a partir de 3 anos 📦 Material: papel cartão rígido ou madeira leve (resistente) 📏 Tamanho das peças: ideal para mãos pequenas – não é brinquedo perigoso! ✨ Benefícios: ✔ Estimula o aprendizado brincando ✔ Ajuda no foco e coordenação motora ✔ Pode jogar sozinho, com amigos ou em família! 💝 Presente perfeito para datas especiais: Dia das Crianças, aniversário, Natal ou volta às aulas. Ficou alguma dúvida ? Sinta-se à vontade para nos enviar uma mensagem! Nossa equipe de atendimento está pronta para de auxiliar da melhor forma possível!', 79.9, 59.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb2gul8j77jtd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438068303%2F22894155011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44812459846', 'Carrinho de Controle Remoto Super Rápido Com Farol Várias Cores', 'Combo: Carrinho de Controle Remoto Apresentamos o Carrinho Controle Remoto Feminino Super Rápido Rosa Com Luz, um brinquedo encantador que promete horas de diversão para meninas a partir de 3 anos. Com uma escala de 1:18, este carrinho da franquia Racing Star combina design atraente e desempenho impressionante, alcançando uma velocidade máxima de 8 km/h. O modelo é alimentado por pilhas, que já estão inclusas, garantindo que a diversão comece imediatamente. O controle remoto também utiliza pilhas AA, permitindo uma experiência de uso prática e sem complicações. Ideal para presentear em datas especiais, como o Natal, este carrinho é uma escolha perfeita para quem busca um brinquedo que une estilo e velocidade. Com luzes que iluminam o caminho, o Carrinho Controle Remoto Feminino é mais do que um simples brinquedo; é uma forma de estimular a imaginação e a coordenação motora. Fabricado pela Atacarejo Kids, este produto é uma adição valiosa à coleção de qualquer jovem entusiasta de carros.', 99.9, 52.9, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-820m6-mpmlojhoyvi98f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438068303%2F44812459846', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
