INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397629220', 'Garrafa Térmica Inox para Café e Chá, Sanremo Expressar 1L', 'Mantenha sua bebida quente por horas com a Garrafa Térmica Expressar da Sanremo! Descubra o companheiro perfeito para seus momentos de café, chá ou chocolate quente. Com capacidade para 1 litro, a Garrafa Térmica Expressar da Sanremo não só mantém sua bebida quente por até 12 horas, como também preserva o sabor e a temperatura original. Por que escolher a Garrafa Térmica Expressar da Sanremo? 𖧹 Design Prático e Moderno: Com um corpo elegante e fácil de segurar, a garrafa é ideal para casa, escritório ou viagens. 𖧹 Tecnologia de Ponta: Construída com materiais de alta qualidade que garantem durabilidade e eficiência térmica. 𖧹 Versatilidade: Perfeita para bebidas quentes ou frias, para uso diário ou para ocasiões especiais. Especificações Técnicas: 𖧹 Capacidade: 1 Litro. 𖧹 Material: 100% Inox e Ampola de Vidro. Sanremo - Inovando para o seu conforto.', 94.5, 94.5, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxbk1ufhkibjcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438656550%2F22397629220', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
