INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22291285195', 'Anilha Standard Pintada 5kg Sport Ferro Fundido Peso de Academia Musculação Fitness', 'ANILHA STANDARD PINTADA 5KG – POTENCIALIZE SEUS TREINOS COM MAIS FORÇA E DURABILIDADE A Anilha Sport Pintada MegaGym Equipamentos, é o equipamento ideal para o seu treino. Sendo a mesma elaborada em ferro fundido com revestimento em pintura weglack premium, se destaca por sua qualidade e durabilidade. Com suas pegadas anatômicas tripartidas, a mesma oferece uma experiência mais completa e eficiente de treino por conta de sua aerodinâmica, e facilidade de manuseio. Sendo extremamente recomendada por conta de seu formato, que permite seu uso em diversos ambientes de treino. E sem que ocorra acidentes por conta da falta de aderência das mãos do usuário, pois a mesma oferece aderência necessária para inibir estes acidentes. Benefícios: — Pegada Anatômica — Treinamento Versátil — Ganhos de Massa e Definição Muscular — Aprimoramento da Postura e Equilíbrio — Fortalecimento Muscular Característica Do Produto: Material: Ferro Fundido; Revestimento: Pintura Protetora Premium, que evita corrosão e desgaste por longos períodos; Alças Laterais Anatômicas: Facilita o manuseio; Numeração Gravada: Facilita a identificação do peso; Furo Central: 30 à 31 mm; Exercícios Indicados: — Agachamento; — Supino; — Elevação Frontal; — Abdominal; — Afundo;', 156.57, 83.48, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lh3tz8uyih6dca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F867949056%2F22291285195', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204325986', 'KORRES GARDENIA GREGA SABONETE 90G', 'Sabonete em barra cremoso. Korres Gardênia Grega deixa a pele higienizada e macia com hidratação e aroma suave. Korres Gardênia Grega envolve a pele com sua espuma cremosa, que limpa e hidrata, além de perfumar com o toque luxuoso das pétalas de Gardênia Grega e Almíscares Doces. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 12.9, 12.9, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-82618-mk2tndzarpjbf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58204325986', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
