INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49307052523', 'Brinco Moissanite 5mm Prata 925 Três Garras Ponto de Luz Feminino Brilho Intenso', 'O Brinco Moissanite 5mm Três Garras em Prata 925 é uma joia sofisticada e cheia de brilho, ideal para quem busca elegância e destaque na medida certa. A pedra moissanite de 5mm apresenta alto poder de reflexão da luz, proporcionando um brilho intenso semelhante ao diamante. A fixação em três garras valoriza a pedra e garante um visual moderno e delicado. - Material: Prata 925 - Pedra: Moissanite - Formato: Redondo com fixação em três garras - Tamanho da pedra: 5 mm - Fecho: Tarraxa tradicional - Acompanha: Certificado de garantia de autenticidade - Observação: Não acompanha caixinha Perfeito para quem deseja um acessório elegante e versátil, ideal tanto para uso diário quanto para ocasiões especiais.', 980.0, 469.0, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/br-11134207-820l9-mn4ds8nc0bup01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340468765%2F49307052523', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18698124505', 'Travel System Romanzo TRIO ISOFIX - Infanti', 'Conjunto moderno com detalhes premium, tem assento reversível e moisés ajustável em posição antirrefluxo, bebê conforto e a moderna base Zion Isofix inclusos. Quando os pais estão se preparando para a chegada de um bebê, procuram por produtos práticos, seguros e confortáveis. O TS Romanzo é tudo isso e muito mais e vai deixar essa fase ainda mais especial: ele inclui um carrinho incrível e um bebê conforto acoplável para facilitar os passeios da família. -Carrinho com assento moisés e passeio -Assento dobrável para um fechamento mais compacto -Assento reversível -Capota ampla com visor, aba de sol e FPS UV50+ -Cinto de 5 pontos com protetores acolchoados, ajuste de largura e altura -Tecido e detalhes premium -Revestimentos especiais na manopla e barra frontal -3 posições de inclinação do assento -Ajuste em múltiplas posições no encosto, incluindo posição antirrefluxo quando ajustado como moisés -Acompanha bebê conforto Zion e base Zion Isofix -Adaptadores inclusos -Cesto porta objetos grande com capacidade 2 kg Modelos compatíveis: - Bebê conforto Zion, Infanti (Incluso) - Base Veícular Zion, Infanti (Incluso) Especificações: Carrinho: - Material: Poliéster, PP, PA, Alumínio, Ferro - Idade Indicada: 0 meses a 15 kg - Peso: 10,700kg - Dimensões: 113 x 60 x 92 - Fechamento: Compacto com moisés dobrável Bebê Conforto: - Isofix: Base: Sim - Material: Bebê conforto: Poliéster, HDPE | Base: HDPE, Metal - Idade Indicada: 0 a 13kg - Peso: Bebê conforto: 2,5 | Base: 3,74 - Dimensões: Bebê conforto: 62 x 43 x 53 | Base: 57,5 x 36 x 16', 2749.0, 2749.0, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-7rep8-m8eyo4nqvu8066', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshop