INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797685966', 'Limpador Perfumado 500ml Uau Brisa E Frescor', 'Momentos de bem-estar! O Limpador Perfumado UAU Perfumes Brisa e Frescor garante um perfume envolvente, leve e refrescante como um dia de praia. Entre limpeza e perfume, escolha os dois! Inspirado na perfumaria internacional. Limpeza diária eficiente. Casa perfumada por mais tempo.', 6.85, 6.85, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcwdq2wpwk5df0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F22797685966', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098534553', 'Pulseira Elos de Corações com Pingente Filho Menino em Prata 925 Legítima', 'Uma joia que representa o amor mais sincero e protetor: o de mãe e filho. Com elos em formato de coração e um delicado pingente de menino, esta pulseira é uma forma especial de carregar esse laço eterno sempre com você. Produzida em prata 925 legítima, ela une significado, delicadeza e beleza em cada detalhe — ideal para presentear ou usar no dia a dia como uma lembrança do seu maior amor. - Material: Prata 925 - Formato: Elos de corações com pingente de menino (filho) - Acompanha: Certificado de garantia de autenticidade - Observação: Não acompanha caixinha Um gesto de amor eterno traduzido em uma joia que emociona e encanta.', 54.0, 54.0, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/br-11134207-81ztl-mkjuph7yrv288a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340468765%2F23098534553', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694799360', 'K Rastase Densifique Bain Densité - Shampoo 250ml', 'Shampoo para cabelos ralosou com afinamento. Kérastase apresenta Bain Densité, o shampoo desenvolvido para quem tem cabelos finos e ralos e busca uma solução eficaz para a perda de densidade. Um convite para redescobrir a vitalidade e o volume dos seus fios, com um tratamento que começa no banho. O Shampoo Kérastase Densifique Bain Densité atua diretamente no afinamento capilar, um problema comum para cabelos que perderam densidade. Sua fórmula une a tecnologia Power Renewal Complex + Ceramida, que restaura e fortalece a fibra, protegendo-a de novos danos. O Gluco-Peptide penetra profundamente para reparar a superfície do fio, resultando em uma cutícula mais lisa e uniforme. Os principais benefícios incluem hidratação profunda, volume imediato e reconstrução da fibra capilar. O resultado esperado é um cabelo visivelmente mais encorpado, com elasticidade, brilho e uma incrível resistência à quebra, revelando uma aparência mais espessa, saudável e cheia de vitalidade desde a primeira aplicação. Benefícios do Shampoo Kérastase Densifique Bain Densité: ▸ Shampoo de densidade para cabelos finos e ralos, que limpa suavemente enquanto encorpa os fios desde a raiz.▸Com Ácido Hialurônico, Glicopeptídeo e Ceramidas, que fortalecem e reparam a superfície da fibra capilar.▸Sua ação reconstrói a fibra, devolvendo a elasticidade e proporcionando um volume imediato e notável.▸ O uso contínuo resulta em cabelos mais resistentes à quebra, com uma aparência mais espessa e cheia de vida.▸ Conquiste um cabelo visivelmente mais denso, saudável e com um volume incrível que dura o dia todo. Ingredientes principais: - Ácido Hialurônico- Glicopeptídeo- Ceramidas Adicione o Shampoo Kérastase Densifique Bain Densité à sua rotina e redescubra a densidade e o volume dos seus cabelos! **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 260.9, 260.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-825zr-mjy6ot34m4g0e6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F23694799360', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694948318', 'Sonny Angel Série Hippes Sonhadores', 'O popular anjinho que vem para trazer alegria aos ambientes. Na cultura oriental, a felicidade é uma das maiores fontes de saúde para todos. Sorrir é sempre o melhor remédio. Com estilo retro, os olhinhos grandes e sorriso fofo. Nascidos no Japão, cada série é única. Com personagens especiais, cada série contém 12 personagens ou segredo aleatório. São colecionáveis e um mais lindo que o outro. Se prepare para ser surpreendido. Esse anjinho pode te deixar muito feliz. Você não escolhe um Sonny Angel. O Sonny Angel é quem escolhe você. PRODUTO IMPORTADO. Cada série contém 12 personagens. Você receberá uma caixinha contendo um dos 12 bonecos desta coleção. Como as caixinhas são lacradas, nem nós büp baby sabemos o que tem dentro da cada uma delas. Você descobrirá o modelo que comprou somente quando abrir a caixinha. ESPECIFICAÇÕES: - Contém 1 unidade; - Perfeito para decoração de ambientes; - Itens colecionáveis; - Origem: Japão. MATERIAL: - PVC. MEDIDAS: - 8 x 4 x 2 cm. LIMPEZA E MANUTENÇÃO: - Limpeza localizada com pano úmido e sabão neutro. SOBRE A MARCA: Sonny Angel encanta os fãs há 14 anos. Desde o nascimento de Sonny Angel, que nasceu para nos fazer sorrir e adicionar um pouco de diversão às nossas vidas, decora do canto de uma sala a uma prateleira. Você não escolhe um Sonny Angel. O Sonny Angel é quem escolhe você.', 129.9, 119.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-820lc-mnoawydhm9s18c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1240688238%2F23694948318', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
