INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497769187', 'Forno Elétrico Fischer Gourmet Grill 44L', 'O Forno Elétrico Fischer Gourmet Grill de bancada foi projetado para quem considera o ato de cozinhar, uma arte. Capacidade de 44 litros e potência de 1775W. Apresenta controle automático de temperatura de 50ºC à 320ºC, controle independente da resistência superior (dourador) e a resistência inferior é acionada pelo termostato, timer de até 120 min com aviso sonoro, garantindo praticidade na hora de cozinhar. A luz piloto indica que o forno está ligado. O Forno Gourmet Grill também traz lâmpada interna acionada pelo timer, porta com vidro duplo que impede a fuga de calor e economiza energia. O corpo interno é revestido com autolimpante (a limpeza ocorre através do processo de volatilização). A grade cromada com duas alturas é removível e possui bandeja esmaltada para resíduos. Características: Assa, doura, tosta, gratina e aquece; Luz piloto (indica quando o forno está ligado); Lâmpada interna que facilita a visualização dos assados, com proteção de vidro; Timer com programação de até 120 minutos com aviso sonoro; Controle automático de temperatura 50°C a 320°C; Dourador: receitas com melhor aspecto; Abertura da porta: lateral Produto Certificado pelo INMETRO (Portaria 148) Dimensões: Altura: 37 cm Largura: 57,5 cm Profundidade: 52 cm Peso: 13,22 kg Garantia do fornecedor de 12 meses', 999.9, 799.9, NULL, 'Home Appliances > Kitchen Appliances > Ovens', 'https://cf.shopee.com.br/file/sg-11134201-7rdws-m00hjcxry9ftfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F23497769187', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
